-- StayNas Finance P2-04 — enforce cash-refund ledger semantics.
-- A refund is a negative cash movement with a booking-matched currency and
-- an auditable reason. Provider status callbacks (including "reversed") are
-- intentionally not treated as cash refunds by this trigger.

begin;

-- Finance audit entries contain payment/refund details. Keep their read scope
-- aligned with the booking's property instead of the generic staff-wide log
-- policy. Other activity-log modules retain the existing staff visibility.
drop policy if exists "Staff can view activity logs" on public.activity_logs;
create policy "Staff can view activity logs"
on public.activity_logs
for select
to authenticated
using (
  public.is_staff(auth.uid())
  and (
    coalesce(module, '') <> 'finance.payments'
    or (
      entity_type = 'booking'
      and exists (
        select 1
        from public.bookings b
        where b.id = activity_logs.entity_id
          and public.staynas_user_has_property_access(auth.uid(), b.property_id)
      )
    )
  )
);

grant select on public.activity_logs to authenticated;

create or replace function public.enforce_payment_refund_event_integrity()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $function$
declare
  v_booking_currency text;
  v_reason text;
begin
  if new.event_type <> 'refund' then
    return new;
  end if;

  if new.amount is null or new.amount >= 0 then
    raise exception using errcode = '22023',
      message = 'A cash refund must be recorded as a negative ledger amount';
  end if;

  if new.booking_id is null then
    raise exception using errcode = '22023',
      message = 'A cash refund must reference a booking';
  end if;

  select upper(b.currency)
    into v_booking_currency
  from public.bookings b
  where b.id = new.booking_id;

  if not found then
    raise exception using errcode = '23503',
      message = 'Refund booking does not exist';
  end if;

  if nullif(upper(btrim(new.currency)), '') is distinct from v_booking_currency then
    raise exception using errcode = '22023',
      message = 'Refund currency must match the booking currency';
  end if;

  v_reason := nullif(btrim(coalesce(new.raw->>'note', '')), '');
  if v_reason is null then
    raise exception using errcode = '22023',
      message = 'A refund reason is required for the audit trail';
  end if;

  return new;
end;
$function$;

drop trigger if exists enforce_payment_refund_event_integrity
  on public.payment_events;

create trigger enforce_payment_refund_event_integrity
before insert or update of event_type, amount, currency, booking_id, raw
on public.payment_events
for each row
execute function public.enforce_payment_refund_event_integrity();

commit;

-- StayNas Finance P2-04: linked, atomic refunds.
-- A refund must reference the successful payment event being refunded. Provider
-- reversal notifications are not cash refunds and never reduce paid_amount.

begin;

alter table public.payment_events
  add column if not exists reverses_event_id uuid
    references public.payment_events(id) on delete restrict;

alter table public.payment_events
  add column if not exists provider_reverses_event_id uuid
    references public.payment_events(id) on delete restrict;

create index if not exists payment_events_reverses_event_idx
  on public.payment_events (reverses_event_id)
  where reverses_event_id is not null;

-- Prevent the legacy general payment RPC from creating unlinked refunds.
-- A refund event must identify the original successful payment event.
create or replace function public.enforce_linked_refund_event()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $trigger$
begin
  if new.event_type = 'refund' and new.reverses_event_id is null then
    raise exception using errcode = '22023',
      message = 'Refund events must reference the original payment event';
  end if;
  if new.reverses_event_id is not null and new.event_type <> 'refund' then
    raise exception using errcode = '22023',
      message = 'Only refund events may reference an original payment event';
  end if;
  return new;
end;
$trigger$;

drop trigger if exists enforce_linked_refund_event on public.payment_events;
create trigger enforce_linked_refund_event
before insert or update of event_type, reverses_event_id
on public.payment_events
for each row execute function public.enforce_linked_refund_event();

create or replace function public.record_booking_refund(
  _booking_id uuid,
  _payment_event_id uuid,
  _amount numeric,
  _method text,
  _note text,
  _idempotency_key text
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $function$
declare
  v_actor uuid := auth.uid();
  v_booking public.bookings%rowtype;
  v_payment public.payment_events%rowtype;
  v_refund public.payment_events%rowtype;
  v_already_refunded numeric(14,2);
  v_paid numeric(14,2);
  v_balance numeric(14,2);
  v_status public.payment_status;
  v_signed numeric(14,2);
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  if not public.has_any_role(v_actor, array['owner','manager','finance']::public.app_role[]) then
    raise exception using errcode = '42501', message = 'Finance permission required';
  end if;
  if _booking_id is null or _payment_event_id is null then
    raise exception using errcode = '22023', message = 'Booking and original payment are required';
  end if;
  if _amount is null or _amount <= 0 or _amount <> round(_amount, 2) then
    raise exception using errcode = '22023', message = 'Refund amount must be positive and limited to two decimal places';
  end if;
  if nullif(btrim(_method), '') is null or _method <> btrim(_method) or length(_method) > 40 then
    raise exception using errcode = '22023', message = 'A valid refund method is required';
  end if;
  if nullif(btrim(_note), '') is null then
    raise exception using errcode = '22023', message = 'A refund reason is required';
  end if;
  if length(_note) > 500 then
    raise exception using errcode = '22023', message = 'Note must be 500 characters or fewer';
  end if;
  if nullif(btrim(_idempotency_key), '') is null or length(_idempotency_key) < 8 or length(_idempotency_key) > 128 then
    raise exception using errcode = '22023', message = 'A valid idempotency key is required';
  end if;

  select b.* into v_booking
  from public.bookings b
  where b.id = _booking_id
    and public.staynas_user_has_property_access(v_actor, b.property_id)
  for update;
  if not found then
    raise exception using errcode = '42501', message = 'Booking not found or property access denied';
  end if;

  -- The booking row is already locked above. That lock serializes every
  -- refund on this booking, so do not request UPDATE privilege on the
  -- tenant-readable payment_events table just to lock the source event.
  select e.* into v_payment
  from public.payment_events e
  where e.id = _payment_event_id
    and e.booking_id = _booking_id
    and e.amount > 0
    and e.event_type in ('manual_payment','payment_completed');
  if not found then
    raise exception using errcode = '22023', message = 'Original payment event is not refundable';
  end if;
  if upper(coalesce(v_payment.currency,'')) <> upper(coalesce(v_booking.currency,'')) then
    raise exception using errcode = '22023', message = 'Original payment currency does not match booking currency';
  end if;
  if exists (
    select 1 from public.payment_events e
    where e.provider_reverses_event_id = _payment_event_id
  ) then
    raise exception using errcode = '55000',
      message = 'This Pesapal settlement was provider-reversed and cannot receive a cash refund';
  end if;

  perform set_config('staynas.payment_rpc', 'on', true);

  select e.* into v_refund
  from public.payment_events e
  where e.booking_id = _booking_id
    and e.idempotency_key = _idempotency_key;
  if found then
    if v_refund.event_type <> 'refund'
       or v_refund.reverses_event_id is distinct from _payment_event_id
       or abs(v_refund.amount) <> _amount
       or coalesce(v_refund.payment_method,'') <> _method
       or upper(coalesce(v_refund.currency,'')) <> upper(coalesce(v_booking.currency,'')) then
      raise exception using errcode = '23505', message = 'Idempotency key was already used with a different refund payload';
    end if;
    return jsonb_build_object(
      'ok', true, 'duplicate', true, 'event_id', v_refund.id,
      'paid_amount', coalesce(v_booking.paid_amount,0),
      'balance_amount', v_booking.balance_amount,
      'payment_status', v_booking.payment_status
    );
  end if;

  -- Legacy refunds without an original-event link cannot safely be allocated
  -- to this payment. Fail closed instead of risking a duplicate cash refund.
  if exists (
    select 1 from public.payment_events e
    where e.booking_id = _booking_id
      and e.event_type = 'refund'
      and e.reverses_event_id is null
  ) then
    raise exception using errcode = '55000',
      message = 'This booking has legacy unlinked refunds; reconcile them before issuing another refund';
  end if;

  select coalesce(sum(abs(e.amount)),0) into v_already_refunded
  from public.payment_events e
  where e.reverses_event_id = _payment_event_id
    and e.event_type = 'refund';

  if v_already_refunded + _amount > v_payment.amount then
    raise exception using errcode = '22023', message = 'Refund exceeds the remaining refundable amount for this payment';
  end if;

  v_paid := round(coalesce(v_booking.paid_amount,0) - _amount, 2);
  if v_paid < 0 then
    raise exception using errcode = '22023', message = 'Refund exceeds net amount paid on this booking';
  end if;
  v_balance := greatest(0, round(v_booking.total - v_paid, 2));
  if v_paid = 0 then
    v_status := 'refunded';
  elsif v_paid >= v_booking.total then
    v_status := 'paid';
  elsif v_paid >= coalesce(v_booking.deposit_amount,0) then
    v_status := 'deposit_paid';
  else
    v_status := 'unpaid';
  end if;

  v_signed := -_amount;
  insert into public.payment_events (
    booking_id, provider, event_type, amount, currency, payment_method,
    reverses_event_id, idempotency_key, raw
  ) values (
    _booking_id, 'manual', 'refund', v_signed, upper(v_booking.currency), _method,
    _payment_event_id, _idempotency_key,
    jsonb_build_object('note', btrim(_note), 'actor_id', v_actor, 'original_payment_event_id', _payment_event_id)
  ) returning * into v_refund;

  update public.bookings
  set paid_amount = v_paid,
      balance_amount = v_balance,
      payment_status = v_status
  where id = _booking_id;

  insert into public.activity_logs (
    actor_id, action, entity_type, entity_id, entity_label, module, metadata, severity
  ) values (
    v_actor, 'finance.refund', 'booking', _booking_id, v_booking.reference, 'finance.payments',
    jsonb_build_object(
      'event_id', v_refund.id, 'original_payment_event_id', _payment_event_id,
      'amount', v_signed, 'currency', v_booking.currency, 'method', _method,
      'note', nullif(_note,''), 'idempotency_key', _idempotency_key
    ), 'audit'
  );

  return jsonb_build_object(
    'ok', true, 'duplicate', false, 'event_id', v_refund.id,
    'paid_amount', v_paid, 'balance_amount', v_balance, 'payment_status', v_status
  );
end;
$function$;

revoke all on function public.record_booking_refund(uuid,uuid,numeric,text,text,text) from public, anon;
grant execute on function public.record_booking_refund(uuid,uuid,numeric,text,text,text) to authenticated;

commit;

-- StayNas Finance P2-04 — atomic Pesapal provider reversal.
-- Provider reversals are distinct from operator-issued cash refunds. They link
-- to the original Pesapal settlement and reverse booking balances atomically.

begin;

create unique index if not exists payment_events_provider_reversal_once_idx
  on public.payment_events (provider_reverses_event_id)
  where provider_reverses_event_id is not null;

create index if not exists payment_events_provider_reversal_booking_idx
  on public.payment_events (booking_id, order_tracking_id)
  where event_type = 'provider_reversal';

create or replace function public.finalize_pesapal_reversal(
  _booking_id uuid,
  _order_tracking_id text,
  _amount numeric,
  _currency text,
  _source text,
  _raw jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_booking public.bookings%rowtype;
  v_payment public.payment_events%rowtype;
  v_existing public.payment_events%rowtype;
  v_reversal public.payment_events%rowtype;
  v_paid numeric(14,2);
  v_balance numeric(14,2);
  v_status public.payment_status;
  v_key text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception using errcode = '42501',
      message = 'Pesapal reversal is restricted to the server service role';
  end if;
  if _booking_id is null
     or nullif(btrim(_order_tracking_id), '') is null
     or length(_order_tracking_id) > 128 then
    raise exception using errcode = '22023',
      message = 'Invalid booking or Pesapal tracking reference';
  end if;
  if _amount is null or _amount <= 0 or _amount <> round(_amount, 2) then
    raise exception using errcode = '22023',
      message = 'Pesapal reversal amount must be positive and limited to two decimal places';
  end if;
  if nullif(btrim(_currency), '') is null or length(_currency) <> 3 then
    raise exception using errcode = '22023',
      message = 'A valid ISO currency code is required for Pesapal reversal';
  end if;
  if _source not in ('ipn','status_check') then
    raise exception using errcode = '22023',
      message = 'Unsupported Pesapal reversal source';
  end if;

  select b.* into v_booking
  from public.bookings b
  where b.id = _booking_id
    and b.pesapal_order_tracking_id = _order_tracking_id
  for update;
  if not found then
    raise exception using errcode = '42501',
      message = 'Booking and Pesapal tracking reference do not match';
  end if;

  select e.* into v_payment
  from public.payment_events e
  where e.booking_id = _booking_id
    and e.provider = 'pesapal'
    and e.event_type = 'payment_completed'
    and e.order_tracking_id = _order_tracking_id
    and e.amount > 0
  for update;
  if not found then
    raise exception using errcode = '22023',
      message = 'No successful Pesapal settlement exists to reverse';
  end if;
  if round(v_payment.amount,2) <> round(_amount,2)
     or upper(coalesce(v_payment.currency,'')) <> upper(_currency)
     or upper(coalesce(v_booking.currency,'')) <> upper(_currency) then
    raise exception using errcode = '22023',
      message = 'Pesapal reversal amount or currency does not match the original settlement';
  end if;

  v_key := 'pesapal:' || _order_tracking_id || ':reversed';
  select e.* into v_existing
  from public.payment_events e
  where e.booking_id = _booking_id
    and e.idempotency_key = v_key;
  if found then
    if v_existing.event_type <> 'provider_reversal'
       or v_existing.provider_reverses_event_id is distinct from v_payment.id
       or round(abs(v_existing.amount),2) <> round(_amount,2)
       or upper(coalesce(v_existing.currency,'')) <> upper(_currency) then
      raise exception using errcode = '23505',
        message = 'Pesapal reversal idempotency key was reused with a different payload';
    end if;
    return jsonb_build_object(
      'ok', true, 'duplicate', true, 'event_id', v_existing.id,
      'paid_amount', coalesce(v_booking.paid_amount,0),
      'balance_amount', v_booking.balance_amount,
      'payment_status', v_booking.payment_status
    );
  end if;

  if exists (
    select 1 from public.payment_events e
    where e.provider_reverses_event_id = v_payment.id
  ) then
    raise exception using errcode = '23505',
      message = 'The original Pesapal settlement has already been reversed';
  end if;

  if exists (
    select 1 from public.payment_events e
    where e.event_type = 'refund'
      and e.reverses_event_id = v_payment.id
  ) then
    raise exception using errcode = '55000',
      message = 'The Pesapal settlement has a cash refund; provider reversal requires manual reconciliation';
  end if;

  v_paid := round(coalesce(v_booking.paid_amount,0) - v_payment.amount, 2);
  if v_paid < 0 then
    raise exception using errcode = '55000',
      message = 'Pesapal reversal would make booking net paid negative; manual reconciliation is required';
  end if;

  v_balance := greatest(0, round(v_booking.total - v_paid, 2));
  if v_paid = 0 then
    v_status := 'unpaid';
  elsif v_paid >= v_booking.total then
    v_status := 'paid';
  elsif v_paid >= coalesce(v_booking.deposit_amount,0) then
    v_status := 'deposit_paid';
  else
    v_status := 'unpaid';
  end if;

  perform set_config('staynas.payment_rpc', 'on', true);

  insert into public.payment_events (
    booking_id, provider, event_type, amount, currency, order_tracking_id,
    status_code, idempotency_key, provider_reverses_event_id, raw
  ) values (
    _booking_id, 'pesapal', 'provider_reversal', -v_payment.amount,
    upper(v_booking.currency), _order_tracking_id, 3, v_key,
    v_payment.id,
    coalesce(_raw, '{}'::jsonb) || jsonb_build_object(
      'source', _source,
      'original_payment_event_id', v_payment.id,
      'reversal_amount', _amount,
      'reversal_currency', upper(_currency)
    )
  ) returning * into v_reversal;

  update public.bookings
  set paid_amount = v_paid,
      balance_amount = v_balance,
      payment_status = v_status
  where id = _booking_id;

  return jsonb_build_object(
    'ok', true, 'duplicate', false, 'event_id', v_reversal.id,
    'paid_amount', v_paid, 'balance_amount', v_balance,
    'payment_status', v_status
  );
end;
$function$;

revoke all on function public.finalize_pesapal_reversal(uuid,text,numeric,text,text,jsonb)
  from public, anon, authenticated;
grant execute on function public.finalize_pesapal_reversal(uuid,text,numeric,text,text,jsonb)
  to service_role;

commit;

-- Keep confirmation's existing room-preparation side effect inside the property boundary.
create or replace function public.handle_booking_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_event text;
begin
  if new.status is distinct from old.status then
    v_event := 'status_' || new.status::text;
    update public.guest_threads
      set timeline = timeline || jsonb_build_object(
        'at', now(), 'type', v_event,
        'message', 'Status changed: ' || old.status || ' → ' || new.status),
        last_updated = now()
      where booking_id = new.id;
    insert into public.pending_notifications (booking_id, event_type, payload)
    values (new.id, v_event, jsonb_build_object('from', old.status, 'to', new.status));

    if new.status::text = 'confirmed' then
      insert into public.ops_tasks (property_id, booking_id, task_type, title, description, due_at, priority)
      values (new.property_id, new.id, 'room_prep',
        'Prepare room for ' || new.guest_name,
        'Check-in on ' || new.check_in,
        (new.check_in - interval '1 day')::timestamptz, 2);
    end if;
  end if;

  if new.payment_status is distinct from old.payment_status then
    v_event := 'payment_' || new.payment_status::text;
    update public.guest_threads
      set timeline = timeline || jsonb_build_object(
        'at', now(), 'type', v_event,
        'message', 'Payment ' || old.payment_status || ' → ' || new.payment_status),
        last_updated = now()
      where booking_id = new.id;
    insert into public.pending_notifications (booking_id, event_type, payload)
    values (new.id, v_event, jsonb_build_object('from', old.payment_status, 'to', new.payment_status));
  end if;

  return new;
end;
$function$;

-- StayNas Phase 3: Booking Lifecycle Controls
-- One database-enforced transition contract for every booking status writer.
begin;

create or replace function public.staynas_enforce_booking_lifecycle()
returns trigger
language plpgsql
security invoker
set search_path = public
as $function$
declare
  v_actor uuid := auth.uid();
begin
  if new.status is not distinct from old.status then
    return new;
  end if;

  if new.status::text = 'confirmed' then
    if old.status::text <> 'pending'
      or (v_actor is not null and not public.has_any_role(v_actor, array['owner','manager','admin','reservations','reception']::public.app_role[])) then
      raise exception using errcode = '42501', message = 'Only authorized reservations staff may confirm a pending booking';
    end if;
    new.confirmed_at := coalesce(new.confirmed_at, now());
  elsif new.status::text = 'checked_in' then
    if old.status::text <> 'confirmed'
      or (v_actor is not null and not public.has_any_role(v_actor, array['owner','manager','admin','reception']::public.app_role[])) then
      raise exception using errcode = '42501', message = 'Only front-desk staff may check in a confirmed booking';
    end if;
    new.checked_in_at := coalesce(new.checked_in_at, now());
  elsif new.status::text = 'completed' then
    if old.status::text <> 'checked_in'
      or (v_actor is not null and not public.has_any_role(v_actor, array['owner','manager','admin','reception']::public.app_role[])) then
      raise exception using errcode = '42501', message = 'A booking must be checked in by authorized front-desk staff before completion';
    end if;
    if exists (select 1 from public.room_states rs where rs.room_id = old.room_id)
      and not exists (
        select 1 from public.room_states rs
        where rs.booking_id = old.id and rs.room_id = old.room_id and rs.state = 'occupied'
      ) then
      raise exception using errcode = '55000', message = 'Checkout requires the assigned physical room to be in occupied state';
    end if;
  elsif new.status::text = 'cancelled' then
    if old.status::text not in ('pending','confirmed')
      or (v_actor is not null and not public.has_any_role(v_actor, array['owner','manager','admin','reservations']::public.app_role[])) then
      raise exception using errcode = '42501', message = 'Cancellation is permitted only for pending or confirmed bookings by reservations managers';
    end if;
    new.cancelled_at := coalesce(new.cancelled_at, now());
  elsif new.status::text = 'no_show' then
    if old.status::text <> 'confirmed'
      or (now() at time zone coalesce((select sp.timezone from public.staynas_properties sp where sp.id = old.property_id), 'Africa/Dar_es_Salaam'))::date <= old.check_in
      or (v_actor is not null and not public.has_any_role(v_actor, array['owner','manager','admin','reservations']::public.app_role[])) then
      raise exception using errcode = '42501', message = 'No-show requires an unarrived confirmed booking after its check-in date and reservations authorization';
    end if;
  else
    raise exception using errcode = '22023', message = 'Unsupported booking lifecycle transition';
  end if;

  return new;
end;
$function$;

drop trigger if exists staynas_booking_lifecycle_guard on public.bookings;
create trigger staynas_booking_lifecycle_guard
before update of status on public.bookings
for each row execute function public.staynas_enforce_booking_lifecycle();

create or replace function public.staynas_transition_booking(
  _booking_id uuid,
  _target_status text,
  _notes text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_actor uuid := auth.uid();
  v_booking public.bookings%rowtype;
  v_room_state public.room_states%rowtype;
  v_room_count integer := 0;
  v_previous_status text;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'Authentication required';
  end if;
  if _booking_id is null or _target_status not in ('confirmed','checked_in','completed','cancelled','no_show') then
    raise exception using errcode = '22023', message = 'Invalid booking lifecycle request';
  end if;
  if _notes is not null and length(_notes) > 1000 then
    raise exception using errcode = '22023', message = 'Lifecycle notes must not exceed 1000 characters';
  end if;

  select b.* into v_booking
  from public.bookings b
  where b.id = _booking_id
  for update;
  if not found or not public.staynas_user_has_property_access(v_actor, v_booking.property_id) then
    raise exception using errcode = '42501', message = 'Booking not found or property access denied';
  end if;

  v_previous_status := v_booking.status::text;

  if v_booking.status::text = _target_status then
    return jsonb_build_object('ok', true, 'duplicate', true, 'booking_id', v_booking.id, 'status', v_booking.status::text);
  end if;

  -- Enforce the exact transition graph before any side effects.
  if not (
    (v_booking.status::text = 'pending' and _target_status in ('confirmed','cancelled')) or
    (v_booking.status::text = 'confirmed' and _target_status in ('checked_in','cancelled','no_show')) or
    (v_booking.status::text = 'checked_in' and _target_status = 'completed')
  ) then
    raise exception using errcode = '22023',
      message = format('Invalid booking transition: %s -> %s', v_booking.status::text, _target_status);
  end if;

  if _target_status = 'no_show' and (now() at time zone coalesce((select sp.timezone from public.staynas_properties sp where sp.id = v_booking.property_id), 'Africa/Dar_es_Salaam'))::date <= v_booking.check_in then
    raise exception using errcode = '22023', message = 'No-show can be recorded only after the scheduled check-in date';
  end if;

  if _target_status = 'checked_in' then
    select count(*) into v_room_count from public.room_states rs where rs.room_id = v_booking.room_id;
    select rs.* into v_room_state
    from public.room_states rs
    where rs.room_id = v_booking.room_id
      and rs.state in ('vacant_clean','reserved','inspection')
      and (rs.booking_id = v_booking.id or rs.booking_id is null)
    order by (rs.booking_id = v_booking.id) desc, rs.unit_label
    limit 1
    for update skip locked;

    if v_room_count > 0 and v_room_state.id is null then
      raise exception using errcode = '55000', message = 'No eligible physical room unit is available for check-in';
    end if;
  end if;

  update public.bookings
  set status = _target_status::public.booking_status,
      notes = case when nullif(btrim(_notes),'') is null then notes
                   else concat_ws(E'\n', notes, '[' || _target_status || ' ' || now()::text || '] ' || btrim(_notes)) end
  where id = _booking_id
  returning * into v_booking;

  if _target_status = 'checked_in' and v_room_state.id is not null then
    update public.room_states
    set state = 'occupied', booking_id = v_booking.id, updated_by = v_actor
    where id = v_room_state.id;
  elsif _target_status = 'completed' then
    select rs.* into v_room_state
    from public.room_states rs
    where rs.booking_id = v_booking.id
    order by rs.unit_label
    limit 1
    for update;

    if v_room_state.id is not null then
      update public.room_states
      set state = 'vacant_dirty', booking_id = null, updated_by = v_actor
      where id = v_room_state.id;

      insert into public.ops_tasks (
        property_id, booking_id, room_state_id, task_type, category, title, priority, status, due_at
      ) values (
        v_booking.property_id, v_booking.id, v_room_state.id, 'housekeeping', 'housekeeping',
        'Clean ' || v_room_state.unit_label || ' after ' || v_booking.guest_name,
        2, 'pending', now() + interval '3 hours'
      );
    end if;
  elsif _target_status in ('cancelled','no_show') then
    update public.room_states
    set state = case when state = 'reserved' then 'vacant_clean' else state end,
        booking_id = null, updated_by = v_actor
    where booking_id = v_booking.id and state = 'reserved';
  end if;

  insert into public.activity_logs (
    actor_id, action, entity_type, entity_id, entity_label, module, metadata, severity
  ) values (
    v_actor, 'reservation.status_changed', 'booking', v_booking.id, v_booking.reference,
    'reservations',
    jsonb_build_object('from', v_previous_status, 'to', _target_status,
                       'notes', nullif(btrim(_notes),''), 'property_id', v_booking.property_id),
    'audit'
  );

  return jsonb_build_object('ok', true, 'duplicate', false, 'booking_id', v_booking.id, 'status', _target_status);
end;
$function$;

revoke all on function public.staynas_transition_booking(uuid,text,text) from public, anon;
grant execute on function public.staynas_transition_booking(uuid,text,text) to authenticated;

