CREATE OR REPLACE FUNCTION public.validate_staynas_rate_override()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_currency text;
  v_room_property uuid;
  v_room_type uuid;
  v_plan_status text;
  v_plan_active boolean;
  v_plan_effective_from date;
  v_plan_effective_to date;
BEGIN
  SELECT upper(currency) INTO v_currency
  FROM public.staynas_properties WHERE id=NEW.property_id;
  IF v_currency IS NULL OR v_currency !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'Rate override property must have an explicit currency';
  END IF;
  IF upper(NEW.currency) <> v_currency THEN
    RAISE EXCEPTION 'Rate override currency must match property currency %',v_currency;
  END IF;
  NEW.currency := v_currency;
  NEW.reason := trim(NEW.reason);
  NEW.updated_at := now();

  IF NEW.room_id IS NOT NULL THEN
    SELECT property_id,catalogue_type_id INTO v_room_property,v_room_type
    FROM public.rooms WHERE id=NEW.room_id;
    IF v_room_property IS DISTINCT FROM NEW.property_id THEN
      RAISE EXCEPTION 'Override room must belong to the same property';
    END IF;
  END IF;
  IF NEW.room_type_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.rooms r
    WHERE r.property_id=NEW.property_id AND r.catalogue_type_id=NEW.room_type_id
  ) THEN
    RAISE EXCEPTION 'Override room type is not configured for this property';
  END IF;
  IF NEW.room_id IS NOT NULL AND v_room_type IS NULL THEN
    RAISE EXCEPTION 'Override room must have a configured room catalogue type';
  END IF;
  IF NEW.rate_plan_id IS NOT NULL THEN
    SELECT publication_status,active,effective_from,effective_to
      INTO v_plan_status,v_plan_active,v_plan_effective_from,v_plan_effective_to
    FROM public.staynas_rate_plans
    WHERE id=NEW.rate_plan_id AND property_id=NEW.property_id;
    IF v_plan_status IS NULL THEN RAISE EXCEPTION 'Rate plan must belong to the same property'; END IF;
    IF NEW.effective_from < COALESCE(v_plan_effective_from,NEW.effective_from)
       OR NEW.effective_to > COALESCE(v_plan_effective_to,NEW.effective_to) THEN
      RAISE EXCEPTION 'Override effective dates must fall within the rate plan effective period';
    END IF;
    IF NEW.room_type_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.staynas_rate_plan_room_types a
      WHERE a.property_id=NEW.property_id AND a.rate_plan_id=NEW.rate_plan_id
        AND a.room_type_id=NEW.room_type_id AND a.active=true
    ) THEN
      RAISE EXCEPTION 'Room type must be actively assigned to the selected rate plan';
    END IF;
  END IF;

  IF TG_OP='INSERT' AND NEW.status='approved' THEN
    RAISE EXCEPTION 'Create rate overrides as pending, then approve them';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status IN ('rejected','revoked') AND NEW.status<>OLD.status THEN
    RAISE EXCEPTION 'Rejected and revoked overrides are terminal';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='pending' AND NEW.status NOT IN ('pending','approved','rejected') THEN
    RAISE EXCEPTION 'Pending overrides may only be approved or rejected';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='approved' AND NEW.status NOT IN ('approved','revoked') THEN
    RAISE EXCEPTION 'Approved overrides may only be revoked';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='approved'
     AND (to_jsonb(OLD) - 'updated_at' - 'approved_by' - 'approved_at' - 'status' - 'revoked_by' - 'revoked_at')
       IS DISTINCT FROM (to_jsonb(NEW) - 'updated_at' - 'approved_by' - 'approved_at' - 'status' - 'revoked_by' - 'revoked_at') THEN
    RAISE EXCEPTION 'Approved rate override terms are immutable; revoke and create a new override';
  END IF;
  IF TG_OP='UPDATE' AND OLD.scope='room_date' AND OLD.status='pending'
     AND NEW.status='approved'
     AND current_setting('staynas.rate_override_rpc',true) IS DISTINCT FROM 'approve' THEN
    RAISE EXCEPTION 'Exact room/date overrides must be approved through the inventory-safe approval RPC';
  END IF;
  IF TG_OP='UPDATE' AND OLD.scope='room_date' AND OLD.status='approved'
     AND NEW.status='revoked'
     AND current_setting('staynas.rate_override_rpc',true) IS DISTINCT FROM 'revoke' THEN
    RAISE EXCEPTION 'Exact room/date overrides must be revoked through the inventory-safe revocation RPC';
  END IF;
  IF NEW.status='approved' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'approved') THEN
    IF NEW.rate_plan_id IS NOT NULL
       AND (v_plan_status IS DISTINCT FROM 'published' OR v_plan_active IS DISTINCT FROM true) THEN
      RAISE EXCEPTION 'Overrides for a rate plan can be approved only while that plan is published and active';
    END IF;
    NEW.approved_by := auth.uid();
    NEW.approved_at := now();
    NEW.rejected_by := NULL;
    NEW.rejected_at := NULL;
    NEW.revoked_by := NULL;
    NEW.revoked_at := NULL;
  ELSIF NEW.status='rejected' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'rejected') THEN
    NEW.rejected_by := auth.uid();
    NEW.rejected_at := now();
  ELSIF NEW.status='revoked' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'revoked') THEN
    NEW.revoked_by := auth.uid();
    NEW.revoked_at := now();
  END IF;

  IF NEW.status='approved' AND EXISTS (
    SELECT 1 FROM public.staynas_rate_overrides o
    WHERE o.property_id=NEW.property_id AND o.id<>NEW.id
      AND o.status='approved'
      AND o.scope=NEW.scope
      AND o.rate_plan_id IS NOT DISTINCT FROM NEW.rate_plan_id
      AND o.room_type_id IS NOT DISTINCT FROM NEW.room_type_id
      AND o.room_id IS NOT DISTINCT FROM NEW.room_id
      AND daterange(o.effective_from,o.effective_to,'[]') &&
          daterange(NEW.effective_from,NEW.effective_to,'[]')
  ) THEN
    RAISE EXCEPTION 'Approved rate overrides cannot overlap for the same property, plan and room scope';
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS staynas_rate_overrides_validate ON public.staynas_rate_overrides;
CREATE TRIGGER staynas_rate_overrides_validate
  BEFORE INSERT OR UPDATE ON public.staynas_rate_overrides
  FOR EACH ROW EXECUTE FUNCTION public.validate_staynas_rate_override();

CREATE OR REPLACE FUNCTION public.audit_staynas_rate_override()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_row jsonb;
  v_before jsonb;
  v_property_id uuid;
  v_override_id uuid;
  v_event text;
BEGIN
  IF TG_OP='DELETE' THEN
    v_row := to_jsonb(OLD);
    v_before := v_row;
    v_property_id := OLD.property_id;
    v_override_id := OLD.id;
    v_event := 'deleted';
  ELSE
    v_row := to_jsonb(NEW);
    v_before := CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END;
    v_property_id := NEW.property_id;
    v_override_id := NEW.id;
    v_event := CASE WHEN TG_OP='INSERT' THEN 'created' ELSE 'updated' END;
    IF TG_OP='UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
      v_event := 'status_'||NEW.status;
    END IF;
  END IF;
  INSERT INTO public.staynas_rate_override_audit(
    property_id,override_id,source,event_type,actor_id,before_state,after_state
  ) VALUES(v_property_id,v_override_id,'rate_override',v_event,auth.uid(),v_before,v_row);
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS staynas_rate_overrides_audit ON public.staynas_rate_overrides;
CREATE TRIGGER staynas_rate_overrides_audit
  AFTER INSERT OR UPDATE OR DELETE ON public.staynas_rate_overrides
  FOR EACH ROW EXECUTE FUNCTION public.audit_staynas_rate_override();

-- Preserve the legacy SPE-02 price input. Every price_override change is
-- auditable; this trigger never changes available_units or is_blocked.
CREATE OR REPLACE FUNCTION public.audit_staynas_inventory_price_override()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_property_id uuid;
BEGIN
  IF OLD.price_override IS NOT DISTINCT FROM NEW.price_override THEN RETURN NEW; END IF;
  SELECT property_id INTO v_property_id FROM public.rooms WHERE id=NEW.room_id;
  INSERT INTO public.staynas_rate_override_audit(
    property_id,source,event_type,actor_id,
    before_state,after_state
  ) VALUES(
    v_property_id,'room_inventory_price_override','legacy_price_override_changed',auth.uid(),
    jsonb_build_object('room_id',NEW.room_id,'date',NEW.date,'price_override',OLD.price_override),
    jsonb_build_object('room_id',NEW.room_id,'date',NEW.date,'price_override',NEW.price_override)
  );
  RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS room_inventory_price_override_audit ON public.room_inventory;
CREATE TRIGGER room_inventory_price_override_audit
  AFTER UPDATE OF price_override ON public.room_inventory
  FOR EACH ROW EXECUTE FUNCTION public.audit_staynas_inventory_price_override();

-- Approved exact-room/date overrides are the approval-controlled extension of
-- the legacy inventory price_override. The RPC changes only price_override;
-- availability units and block state are not touched. Existing inventory rows
-- are required: the RPC will not create or backfill inventory.
CREATE OR REPLACE FUNCTION public.apply_staynas_room_date_rate_override(
  _property_id uuid,
  _room_id uuid,
  _stay_date date,
  _nightly_rate numeric,
  _reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_override_id uuid;
  v_currency text;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL
     OR public.staynas_active_property_id(v_actor) IS DISTINCT FROM _property_id
     OR NOT public.staynas_user_has_property_access(v_actor,_property_id)
     OR NOT public.has_any_role(v_actor,ARRAY['owner','manager','finance','admin']::public.app_role[]) THEN
    RAISE EXCEPTION 'Rate override access denied';
  END IF;
  IF _nightly_rate IS NULL OR _nightly_rate<=0 OR length(trim(COALESCE(_reason,'')))<5 THEN
    RAISE EXCEPTION 'A positive nightly rate and a reason of at least five characters are required';
  END IF;
  SELECT upper(currency) INTO v_currency FROM public.staynas_properties WHERE id=_property_id;
  IF NOT EXISTS (SELECT 1 FROM public.rooms WHERE id=_room_id AND property_id=_property_id) THEN
    RAISE EXCEPTION 'Room does not belong to the selected property';
  END IF;
  INSERT INTO public.staynas_rate_overrides(
    property_id,scope,room_id,effective_from,effective_to,
    nightly_rate,currency,reason,status,created_by
  ) VALUES(
    _property_id,'room_date',_room_id,_stay_date,_stay_date,
    _nightly_rate,v_currency,trim(_reason),'pending',v_actor
  ) RETURNING id INTO v_override_id;

  -- Approval is explicit and separate from proposal creation.
  RETURN jsonb_build_object('override_id',v_override_id,'status','pending','currency',v_currency);
END;
$function$;

CREATE OR REPLACE FUNCTION public.approve_staynas_room_date_rate_override(_override_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_override public.staynas_rate_overrides%ROWTYPE;
  v_inventory public.room_inventory%ROWTYPE;
  v_actor uuid := auth.uid();
BEGIN
  SELECT * INTO v_override FROM public.staynas_rate_overrides
  WHERE id=_override_id AND scope='room_date'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Room/date rate override not found'; END IF;
  IF v_actor IS NULL
     OR public.staynas_active_property_id(v_actor) IS DISTINCT FROM v_override.property_id
     OR NOT public.staynas_user_has_property_access(v_actor,v_override.property_id)
     OR NOT public.has_any_role(v_actor,ARRAY['owner','manager','finance','admin']::public.app_role[]) THEN
    RAISE EXCEPTION 'Rate override approval access denied';
  END IF;
  IF v_override.status<>'pending' THEN RAISE EXCEPTION 'Only pending rate overrides can be approved'; END IF;

  SELECT * INTO v_inventory FROM public.room_inventory
  WHERE room_id=v_override.room_id AND date=v_override.effective_from FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Inventory calendar row is missing; rate override was not applied';
  END IF;
  PERFORM set_config('staynas.rate_override_rpc','approve',true);
  UPDATE public.staynas_rate_overrides
  SET status='approved',previous_inventory_price_override=v_inventory.price_override,applied_at=now()
  WHERE id=_override_id;

  UPDATE public.room_inventory
  SET price_override=v_override.nightly_rate,updated_at=now()
  WHERE room_id=v_override.room_id AND date=v_override.effective_from;

  RETURN jsonb_build_object('override_id',_override_id,'status','approved',
    'nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
END;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_staynas_room_date_rate_override(_override_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_override public.staynas_rate_overrides%ROWTYPE;
  v_actor uuid := auth.uid();
BEGIN
  SELECT * INTO v_override FROM public.staynas_rate_overrides
  WHERE id=_override_id AND scope='room_date'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Room/date rate override not found'; END IF;
  IF v_actor IS NULL
     OR public.staynas_active_property_id(v_actor) IS DISTINCT FROM v_override.property_id
     OR NOT public.staynas_user_has_property_access(v_actor,v_override.property_id)
     OR NOT public.has_any_role(v_actor,ARRAY['owner','manager','finance','admin']::public.app_role[]) THEN
    RAISE EXCEPTION 'Rate override revocation access denied';
  END IF;
  IF v_override.status<>'approved' THEN RAISE EXCEPTION 'Only approved overrides can be revoked'; END IF;

  UPDATE public.room_inventory
  SET price_override=v_override.previous_inventory_price_override,updated_at=now()
  WHERE room_id=v_override.room_id AND date=v_override.effective_from;
  IF NOT FOUND THEN RAISE EXCEPTION 'Inventory calendar row is missing; override was not revoked'; END IF;

  PERFORM set_config('staynas.rate_override_rpc','revoke',true);
  UPDATE public.staynas_rate_overrides SET status='revoked' WHERE id=_override_id;
  RETURN jsonb_build_object('override_id',_override_id,'status','revoked',
    'restored_price_override',v_override.previous_inventory_price_override);
END;
$function$;

REVOKE ALL ON FUNCTION public.validate_staynas_rate_override() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.audit_staynas_rate_override() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.audit_staynas_inventory_price_override() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.prevent_staynas_rate_override_audit_mutation() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.apply_staynas_room_date_rate_override(uuid,uuid,date,numeric,text) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.approve_staynas_room_date_rate_override(uuid) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.revoke_staynas_room_date_rate_override(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.apply_staynas_room_date_rate_override(uuid,uuid,date,numeric,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.approve_staynas_room_date_rate_override(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.revoke_staynas_room_date_rate_override(uuid) TO authenticated;




COMMENT ON TABLE public.staynas_rate_overrides IS
  'Property-scoped override proposals and approvals. Resolution precedence for SPE-04: approved exact-date override, published daily calendar, seasonal rate, then inherited/base rate. Rate-plan/room-type scopes are recorded here for SPE-04; exact room/date approval writes only the legacy room_inventory.price_override field.';
COMMENT ON TABLE public.staynas_rate_override_audit IS
  'Append-only audit trail for rate override lifecycle and legacy room_inventory.price_override changes.';
COMMENT ON FUNCTION public.apply_staynas_room_date_rate_override(uuid,uuid,date,numeric,text) IS
  'Creates a pending exact-room/date rate override proposal. Does not modify inventory until approved.';
COMMENT ON FUNCTION public.approve_staynas_room_date_rate_override(uuid) IS
  'Approves a pending exact-room/date override and updates only room_inventory.price_override; availability and blocked state remain unchanged.';

COMMIT;

-- Serialize approval checks so concurrent requests cannot create overlapping approved overrides.
BEGIN;
CREATE OR REPLACE FUNCTION public.validate_staynas_rate_override()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_currency text;
  v_room_property uuid;
  v_room_type uuid;
  v_plan_status text;
  v_plan_active boolean;
  v_plan_effective_from date;
  v_plan_effective_to date;
BEGIN
  SELECT upper(currency) INTO v_currency
  FROM public.staynas_properties WHERE id=NEW.property_id;
  IF v_currency IS NULL OR v_currency !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'Rate override property must have an explicit currency';
  END IF;
  IF upper(NEW.currency) <> v_currency THEN
    RAISE EXCEPTION 'Rate override currency must match property currency %',v_currency;
  END IF;
  NEW.currency := v_currency;
  NEW.reason := trim(NEW.reason);
  NEW.updated_at := now();

  IF NEW.room_id IS NOT NULL THEN
    SELECT property_id,catalogue_type_id INTO v_room_property,v_room_type
    FROM public.rooms WHERE id=NEW.room_id;
    IF v_room_property IS DISTINCT FROM NEW.property_id THEN
      RAISE EXCEPTION 'Override room must belong to the same property';
    END IF;
  END IF;
  IF NEW.room_type_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.rooms r
    WHERE r.property_id=NEW.property_id AND r.catalogue_type_id=NEW.room_type_id
  ) THEN
    RAISE EXCEPTION 'Override room type is not configured for this property';
  END IF;
  IF NEW.room_id IS NOT NULL AND v_room_type IS NULL THEN
    RAISE EXCEPTION 'Override room must have a configured room catalogue type';
  END IF;
  IF NEW.rate_plan_id IS NOT NULL THEN
    SELECT publication_status,active,effective_from,effective_to
      INTO v_plan_status,v_plan_active,v_plan_effective_from,v_plan_effective_to
    FROM public.staynas_rate_plans
    WHERE id=NEW.rate_plan_id AND property_id=NEW.property_id;
    IF v_plan_status IS NULL THEN RAISE EXCEPTION 'Rate plan must belong to the same property'; END IF;
    IF NEW.effective_from < COALESCE(v_plan_effective_from,NEW.effective_from)
       OR NEW.effective_to > COALESCE(v_plan_effective_to,NEW.effective_to) THEN
      RAISE EXCEPTION 'Override effective dates must fall within the rate plan effective period';
    END IF;
    IF NEW.room_type_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.staynas_rate_plan_room_types a
      WHERE a.property_id=NEW.property_id AND a.rate_plan_id=NEW.rate_plan_id
        AND a.room_type_id=NEW.room_type_id AND a.active=true
    ) THEN
      RAISE EXCEPTION 'Room type must be actively assigned to the selected rate plan';
    END IF;
  END IF;

  IF TG_OP='INSERT' AND NEW.status='approved' THEN
    RAISE EXCEPTION 'Create rate overrides as pending, then approve them';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status IN ('rejected','revoked') AND NEW.status<>OLD.status THEN
    RAISE EXCEPTION 'Rejected and revoked overrides are terminal';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='pending' AND NEW.status NOT IN ('pending','approved','rejected') THEN
    RAISE EXCEPTION 'Pending overrides may only be approved or rejected';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='approved' AND NEW.status NOT IN ('approved','revoked') THEN
    RAISE EXCEPTION 'Approved overrides may only be revoked';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='approved'
     AND (to_jsonb(OLD) - 'updated_at' - 'approved_by' - 'approved_at' - 'status' - 'revoked_by' - 'revoked_at')
       IS DISTINCT FROM (to_jsonb(NEW) - 'updated_at' - 'approved_by' - 'approved_at' - 'status' - 'revoked_by' - 'revoked_at') THEN
    RAISE EXCEPTION 'Approved rate override terms are immutable; revoke and create a new override';
  END IF;
  IF TG_OP='UPDATE' AND OLD.scope='room_date' AND OLD.status='pending'
     AND NEW.status='approved'
     AND current_setting('staynas.rate_override_rpc',true) IS DISTINCT FROM 'approve' THEN
    RAISE EXCEPTION 'Exact room/date overrides must be approved through the inventory-safe approval RPC';
  END IF;
  IF TG_OP='UPDATE' AND OLD.scope='room_date' AND OLD.status='approved'
     AND NEW.status='revoked'
     AND current_setting('staynas.rate_override_rpc',true) IS DISTINCT FROM 'revoke' THEN
    RAISE EXCEPTION 'Exact room/date overrides must be revoked through the inventory-safe revocation RPC';
  END IF;
  IF NEW.status='approved' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'approved') THEN
    IF NEW.rate_plan_id IS NOT NULL
       AND (v_plan_status IS DISTINCT FROM 'published' OR v_plan_active IS DISTINCT FROM true) THEN
      RAISE EXCEPTION 'Overrides for a rate plan can be approved only while that plan is published and active';
    END IF;
    NEW.approved_by := auth.uid();
    NEW.approved_at := now();
    NEW.rejected_by := NULL;
    NEW.rejected_at := NULL;
    NEW.revoked_by := NULL;
    NEW.revoked_at := NULL;
  ELSIF NEW.status='rejected' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'rejected') THEN
    NEW.rejected_by := auth.uid();
    NEW.rejected_at := now();
  ELSIF NEW.status='revoked' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'revoked') THEN
    NEW.revoked_by := auth.uid();
    NEW.revoked_at := now();
  END IF;

  IF NEW.status='approved' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      concat_ws(':',NEW.property_id::text,NEW.scope,
        COALESCE(NEW.rate_plan_id::text,''),COALESCE(NEW.room_type_id::text,''),
        COALESCE(NEW.room_id::text,'')),0
    ));
  END IF;
  IF NEW.status='approved' AND EXISTS (
    SELECT 1 FROM public.staynas_rate_overrides o
    WHERE o.property_id=NEW.property_id AND o.id<>NEW.id
      AND o.status='approved'
      AND o.scope=NEW.scope
      AND o.rate_plan_id IS NOT DISTINCT FROM NEW.rate_plan_id
      AND o.room_type_id IS NOT DISTINCT FROM NEW.room_type_id
      AND o.room_id IS NOT DISTINCT FROM NEW.room_id
      AND daterange(o.effective_from,o.effective_to,'[]') &&
          daterange(NEW.effective_from,NEW.effective_to,'[]')
  ) THEN
    RAISE EXCEPTION 'Approved rate overrides cannot overlap for the same property, plan and room scope';
  END IF;
  RETURN NEW;
END;
$function$;
COMMIT;

-- SPE-03.08: validate inherited rate-plan restrictions without touching inventory.
BEGIN;

CREATE OR REPLACE FUNCTION public.validate_staynas_rate_plan_restrictions()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_rules jsonb;
  v_parent_resolved jsonb;
  v_key text;
  v_rule jsonb;
  v_type text;
  v_start date;
  v_end date;
  v_room_type uuid;
  v_value numeric;
  v_left record;
  v_right record;
BEGIN
  v_rules := COALESCE(NEW.rate_plan_data->'restrictions','{}'::jsonb);
  IF jsonb_typeof(v_rules) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'restrictions must be a keyed JSON object';
  END IF;

  IF NEW.parent_rate_plan_id IS NOT NULL THEN
    v_parent_resolved := public.resolve_staynas_rate_plan_inheritance(
      NEW.property_id,NEW.parent_rate_plan_id
    );
    v_rules := public.staynas_rate_plan_jsonb_deep_merge(
      COALESCE(v_parent_resolved->'resolved_data'->'restrictions','{}'::jsonb),
      v_rules
    );
  END IF;

  FOR v_key,v_rule IN SELECT key,value FROM jsonb_each(v_rules)
  LOOP
    IF v_rule='null'::jsonb THEN CONTINUE; END IF;
    IF v_key !~ '^[A-Za-z0-9_-]{2,80}$' THEN
      RAISE EXCEPTION 'Restriction key % must use 2-80 letters, numbers, underscores or hyphens',v_key;
    END IF;
    IF jsonb_typeof(v_rule) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'Restriction % must be an object or null to clear an inherited rule',v_key;
    END IF;
    IF v_rule - ARRAY[
      'type','value','start_date','end_date','room_type_ids','active','reason'
    ]::text[] <> '{}'::jsonb THEN
      RAISE EXCEPTION 'Restriction % contains unsupported fields',v_key;
    END IF;

    v_type := v_rule->>'type';
    IF v_type IS NULL OR v_type NOT IN (
      'min_los','max_los','closed_to_arrival','closed_to_departure',
      'stop_sell','advance_booking_min_hours','advance_booking_max_days'
    ) THEN
      RAISE EXCEPTION 'Restriction % has an unsupported type',v_key;
    END IF;
    IF jsonb_typeof(v_rule->'start_date') IS DISTINCT FROM 'string'
       OR (v_rule->>'start_date') !~ '^\d{4}-\d{2}-\d{2}$'
       OR jsonb_typeof(v_rule->'end_date') IS DISTINCT FROM 'string'
       OR (v_rule->>'end_date') !~ '^\d{4}-\d{2}-\d{2}$' THEN
      RAISE EXCEPTION 'Restriction % requires ISO calendar start and end dates',v_key;
    END IF;
    BEGIN
      v_start := (v_rule->>'start_date')::date;
      v_end := (v_rule->>'end_date')::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'Restriction % contains an invalid calendar date',v_key;
    END;
    IF v_end<v_start THEN
      RAISE EXCEPTION 'Restriction % end date must be on or after its start date',v_key;
    END IF;
    IF NEW.effective_from IS NOT NULL AND v_start<NEW.effective_from THEN
      RAISE EXCEPTION 'Restriction % starts before the rate plan effective period',v_key;
    END IF;
    IF NEW.effective_to IS NOT NULL AND v_end>NEW.effective_to THEN
      RAISE EXCEPTION 'Restriction % ends after the rate plan effective period',v_key;
    END IF;

    IF jsonb_typeof(v_rule->'room_type_ids') IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_rule->'room_type_ids')=0 THEN
      RAISE EXCEPTION 'Restriction % requires at least one room type',v_key;
    END IF;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements_text(v_rule->'room_type_ids') AS ids(value)
      WHERE value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) THEN
      RAISE EXCEPTION 'Restriction % contains an invalid room type identifier',v_key;
    END IF;
    IF (SELECT count(*)<>count(DISTINCT value)
        FROM jsonb_array_elements_text(v_rule->'room_type_ids') AS ids(value)) THEN
      RAISE EXCEPTION 'Restriction % contains duplicate room type identifiers',v_key;
    END IF;
    IF jsonb_typeof(v_rule->'active') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'Restriction % active must be a boolean',v_key;
    END IF;
    IF jsonb_typeof(v_rule->'reason') IS DISTINCT FROM 'string'
       OR length(trim(v_rule->>'reason')) NOT BETWEEN 5 AND 500 THEN
      RAISE EXCEPTION 'Restriction % requires a reason between 5 and 500 characters',v_key;
    END IF;

    IF v_type IN ('min_los','max_los','advance_booking_min_hours','advance_booking_max_days') THEN
      IF jsonb_typeof(v_rule->'value') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'Restriction % requires a numeric value',v_key;
      END IF;
      v_value := (v_rule->>'value')::numeric;
      IF trunc(v_value)<>v_value THEN
        RAISE EXCEPTION 'Restriction % value must be a whole number',v_key;
      END IF;
      IF v_type IN ('min_los','max_los') AND v_value NOT BETWEEN 1 AND 365 THEN
        RAISE EXCEPTION 'Restriction % LOS value must be between 1 and 365 nights',v_key;
      END IF;
      IF v_type='advance_booking_min_hours' AND v_value NOT BETWEEN 0 AND 87600 THEN
        RAISE EXCEPTION 'Restriction % minimum advance hours must be between 0 and 87600',v_key;
      END IF;
      IF v_type='advance_booking_max_days' AND v_value NOT BETWEEN 0 AND 3650 THEN
        RAISE EXCEPTION 'Restriction % maximum advance days must be between 0 and 3650',v_key;
      END IF;
    ELSIF v_rule ? 'value' THEN
      RAISE EXCEPTION 'Restriction % type % must not include a value',v_key,v_type;
    END IF;

    FOR v_room_type IN
      SELECT value::uuid FROM jsonb_array_elements_text(v_rule->'room_type_ids') AS ids(value)
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.rooms r
        WHERE r.property_id=NEW.property_id AND r.catalogue_type_id=v_room_type
      ) THEN
        RAISE EXCEPTION 'Restriction % references a room type outside the property catalogue',v_key;
      END IF;
      IF NEW.publication_status='published' AND NOT EXISTS (
        SELECT 1 FROM public.staynas_rate_plan_room_types a
        WHERE a.property_id=NEW.property_id
          AND a.rate_plan_id=NEW.id
          AND a.room_type_id=v_room_type
          AND a.active=true
      ) THEN
        RAISE EXCEPTION 'Published restriction % must target room types actively assigned to this rate plan',v_key;
      END IF;
    END LOOP;
  END LOOP;

  -- Prevent contradictory minimum/maximum LOS rules for intersecting
  -- room types and arrival-date windows. Other rules remain composable.
  FOR v_left IN
    SELECT key,value FROM jsonb_each(v_rules)
    WHERE value<>'null'::jsonb AND value->>'active'='true' AND value->>'type'='min_los'
  LOOP
    FOR v_right IN
      SELECT key,value FROM jsonb_each(v_rules)
      WHERE value<>'null'::jsonb AND value->>'active'='true' AND value->>'type'='max_los'
    LOOP
      IF (v_left.value->>'value')::integer > (v_right.value->>'value')::integer
         AND daterange((v_left.value->>'start_date')::date,(v_left.value->>'end_date')::date,'[]')
             && daterange((v_right.value->>'start_date')::date,(v_right.value->>'end_date')::date,'[]')
         AND EXISTS (
           SELECT 1
           FROM jsonb_array_elements_text(v_left.value->'room_type_ids') l(value)
           JOIN jsonb_array_elements_text(v_right.value->'room_type_ids') r(value)
             ON l.value=r.value
         ) THEN
        RAISE EXCEPTION 'Minimum LOS restriction % exceeds overlapping maximum LOS restriction %',v_left.key,v_right.key;
      END IF;
    END LOOP;
  END LOOP;
  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION public.validate_staynas_rate_plan_restrictions() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS staynas_rate_plan_restrictions_validate ON public.staynas_rate_plans;
CREATE TRIGGER staynas_rate_plan_restrictions_validate
  BEFORE INSERT OR UPDATE OF property_id,parent_rate_plan_id,rate_plan_data,effective_from,effective_to,publication_status
  ON public.staynas_rate_plans
  FOR EACH ROW EXECUTE FUNCTION public.validate_staynas_rate_plan_restrictions();

COMMENT ON FUNCTION public.validate_staynas_rate_plan_restrictions() IS
  'Validates effective inherited stay restrictions. Stop-sell and closure restrictions are commercial availability rules and never mutate room_inventory.';

COMMIT;

-- SPE-03.09: immutable publication snapshots, publication audit and authorized read contract.
BEGIN;

CREATE TABLE IF NOT EXISTS public.staynas_rate_plan_publications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  property_id uuid NOT NULL,
  rate_plan_id uuid NOT NULL,
  publication_number integer NOT NULL,
  rate_plan_version integer NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  currency text NOT NULL,
  effective_from date,
  effective_to date,
  published_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  published_at timestamptz NOT NULL DEFAULT now(),
  resolved_data jsonb NOT NULL,
  inheritance_trace jsonb NOT NULL,
  lineage jsonb NOT NULL,
  own_policy jsonb NOT NULL,
  room_type_assignments jsonb NOT NULL,
  snapshot_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT staynas_rate_plan_publications_plan_fk
    FOREIGN KEY(property_id,rate_plan_id)
    REFERENCES public.staynas_rate_plans(property_id,id) ON DELETE RESTRICT,
  CONSTRAINT staynas_rate_plan_publications_version_fk
    FOREIGN KEY(rate_plan_id,rate_plan_version)
    REFERENCES public.staynas_rate_plan_versions(rate_plan_id,version) ON DELETE RESTRICT,
  CONSTRAINT staynas_rate_plan_publications_number_positive CHECK (publication_number>0),
  CONSTRAINT staynas_rate_plan_publications_version_positive CHECK (rate_plan_version>0),
  CONSTRAINT staynas_rate_plan_publications_currency_check CHECK (currency ~ '^[A-Z]{3}$'),
  CONSTRAINT staynas_rate_plan_publications_dates_check
    CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from),
  CONSTRAINT staynas_rate_plan_publications_hash_check CHECK (snapshot_hash ~ '^[a-f0-9]{32}$'),
  CONSTRAINT staynas_rate_plan_publications_unique UNIQUE(property_id,rate_plan_id,publication_number)
);
CREATE INDEX IF NOT EXISTS staynas_rate_plan_publications_current_idx
  ON public.staynas_rate_plan_publications(property_id,rate_plan_id,publication_number DESC);
ALTER TABLE public.staynas_rate_plan_publications ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Property finance read rate plan publications" ON public.staynas_rate_plan_publications;
CREATE POLICY "Property finance read rate plan publications"
  ON public.staynas_rate_plan_publications FOR SELECT TO authenticated
  USING (
    public.staynas_user_has_property_access((select auth.uid()),property_id)
    AND public.has_any_role((select auth.uid()),ARRAY['owner','manager','finance','admin']::public.app_role[])
  );
GRANT SELECT ON public.staynas_rate_plan_publications TO authenticated;
REVOKE ALL ON public.staynas_rate_plan_publications FROM anon;

CREATE TABLE IF NOT EXISTS public.staynas_rate_plan_publication_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  property_id uuid NOT NULL,
  rate_plan_id uuid NOT NULL,
  rate_plan_version integer NOT NULL,
  previous_status text NOT NULL,
  new_status text NOT NULL,
  previous_active boolean NOT NULL,
  new_active boolean NOT NULL,
  event_type text NOT NULL,
  actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  change_reason text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT staynas_rate_plan_publication_events_plan_fk
    FOREIGN KEY(property_id,rate_plan_id)
    REFERENCES public.staynas_rate_plans(property_id,id) ON DELETE RESTRICT,
  CONSTRAINT staynas_rate_plan_publication_events_version_fk
    FOREIGN KEY(rate_plan_id,rate_plan_version)
    REFERENCES public.staynas_rate_plan_versions(rate_plan_id,version) ON DELETE RESTRICT,
  CONSTRAINT staynas_rate_plan_publication_events_type_check
    CHECK (event_type IN ('published','suspended','archived','draft_restored','activated','deactivated')),
  CONSTRAINT staynas_rate_plan_publication_events_reason_check
    CHECK (length(trim(change_reason)) BETWEEN 5 AND 500)
);
CREATE INDEX IF NOT EXISTS staynas_rate_plan_publication_events_lookup_idx
  ON public.staynas_rate_plan_publication_events(property_id,rate_plan_id,created_at DESC);
ALTER TABLE public.staynas_rate_plan_publication_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Property finance read rate plan publication events" ON public.staynas_rate_plan_publication_events;
CREATE POLICY "Property finance read rate plan publication events"
  ON public.staynas_rate_plan_publication_events FOR SELECT TO authenticated
  USING (
    public.staynas_user_has_property_access((select auth.uid()),property_id)
    AND public.has_any_role((select auth.uid()),ARRAY['owner','manager','finance','admin']::public.app_role[])
  );
GRANT SELECT ON public.staynas_rate_plan_publication_events TO authenticated;
REVOKE ALL ON public.staynas_rate_plan_publication_events FROM anon;

CREATE OR REPLACE FUNCTION public.prevent_staynas_rate_plan_publication_mutation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path=public
AS $function$
BEGIN
  RAISE EXCEPTION 'Rate-plan publication history is immutable';
END;
$function$;
DROP TRIGGER IF EXISTS staynas_rate_plan_publications_immutable ON public.staynas_rate_plan_publications;
CREATE TRIGGER staynas_rate_plan_publications_immutable
  BEFORE UPDATE OR DELETE ON public.staynas_rate_plan_publications
  FOR EACH ROW EXECUTE FUNCTION public.prevent_staynas_rate_plan_publication_mutation();
DROP TRIGGER IF EXISTS staynas_rate_plan_publication_events_immutable ON public.staynas_rate_plan_publication_events;
CREATE TRIGGER staynas_rate_plan_publication_events_immutable
  BEFORE UPDATE OR DELETE ON public.staynas_rate_plan_publication_events
  FOR EACH ROW EXECUTE FUNCTION public.prevent_staynas_rate_plan_publication_mutation();

CREATE OR REPLACE FUNCTION public.require_staynas_rate_plan_publication_reason()
RETURNS trigger
LANGUAGE plpgsql
SET search_path=public
AS $function$
DECLARE
  v_reason text := current_setting('staynas.rate_plan_publication_reason',true);
BEGIN
  IF OLD.publication_status IS DISTINCT FROM NEW.publication_status
     OR OLD.active IS DISTINCT FROM NEW.active THEN
    IF auth.uid() IS NULL OR length(trim(COALESCE(v_reason,''))) NOT BETWEEN 5 AND 500 THEN
      RAISE EXCEPTION 'Publication and activation changes must use the audited publication RPC with a reason';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS staynas_rate_plan_publication_reason_guard ON public.staynas_rate_plans;
CREATE TRIGGER staynas_rate_plan_publication_reason_guard
  BEFORE UPDATE OF publication_status,active ON public.staynas_rate_plans
  FOR EACH ROW EXECUTE FUNCTION public.require_staynas_rate_plan_publication_reason();

CREATE OR REPLACE FUNCTION public.capture_staynas_rate_plan_publication()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_resolved jsonb;
  v_assignments jsonb;
  v_publication_number integer;
  v_published_at timestamptz;
  v_published_by uuid;
  v_hash text;
BEGIN
  IF OLD.publication_status='published'
     OR NEW.publication_status<>'published'
     OR NEW.active IS DISTINCT FROM true THEN
    RETURN NEW;
  END IF;

  v_resolved := public.resolve_staynas_rate_plan_inheritance(NEW.property_id,NEW.id);
  SELECT COALESCE(
    jsonb_agg(jsonb_build_object(
      'room_type_id',a.room_type_id,
      'name',c.name,
      'slug',c.slug,
      'display_order',a.display_order
    ) ORDER BY a.display_order,c.name),
    '[]'::jsonb
  ) INTO v_assignments
  FROM public.staynas_rate_plan_room_types a
  JOIN public.staynas_room_catalogue_types c ON c.id=a.room_type_id
  WHERE a.property_id=NEW.property_id AND a.rate_plan_id=NEW.id AND a.active=true;

  IF jsonb_array_length(v_assignments)=0 THEN
    RAISE EXCEPTION 'A published rate plan must have at least one active room-type assignment';
  END IF;

  SELECT COALESCE(MAX(publication_number),0)+1 INTO v_publication_number
  FROM public.staynas_rate_plan_publications
  WHERE property_id=NEW.property_id AND rate_plan_id=NEW.id;

  v_published_at := COALESCE(NEW.published_at,now());
  v_published_by := COALESCE(NEW.published_by,auth.uid());
  v_hash := md5(jsonb_build_object(
    'property_id',NEW.property_id,
    'rate_plan_id',NEW.id,
    'publication_number',v_publication_number,
    'rate_plan_version',NEW.version,
    'resolved_data',v_resolved->'resolved_data',
    'inheritance_trace',v_resolved->'inheritance_trace',
    'lineage',v_resolved->'lineage',
    'own_policy',v_resolved->'own_policy',
    'room_type_assignments',v_assignments,
    'effective_from',NEW.effective_from,
    'effective_to',NEW.effective_to
  )::text);

  INSERT INTO public.staynas_rate_plan_publications(
    property_id,rate_plan_id,publication_number,rate_plan_version,
    code,name,currency,effective_from,effective_to,published_by,published_at,
    resolved_data,inheritance_trace,lineage,own_policy,room_type_assignments,snapshot_hash
  ) VALUES (
    NEW.property_id,NEW.id,v_publication_number,NEW.version,
    NEW.code,NEW.name,NEW.currency,NEW.effective_from,NEW.effective_to,
    v_published_by,v_published_at,
    v_resolved->'resolved_data',v_resolved->'inheritance_trace',v_resolved->'lineage',
    v_resolved->'own_policy',v_assignments,v_hash
  );
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS zz_staynas_rate_plan_publication_capture ON public.staynas_rate_plans;
CREATE TRIGGER zz_staynas_rate_plan_publication_capture
  AFTER UPDATE OF publication_status ON public.staynas_rate_plans
  FOR EACH ROW
  WHEN (OLD.publication_status IS DISTINCT FROM 'published'
        AND NEW.publication_status='published' AND NEW.active=true)
  EXECUTE FUNCTION public.capture_staynas_rate_plan_publication();

CREATE OR REPLACE FUNCTION public.audit_staynas_rate_plan_publication_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_event text;
  v_reason text;
BEGIN
  IF OLD.publication_status IS DISTINCT FROM NEW.publication_status THEN
    v_event := CASE NEW.publication_status
      WHEN 'published' THEN 'published'
      WHEN 'suspended' THEN 'suspended'
      WHEN 'archived' THEN 'archived'
      WHEN 'draft' THEN 'draft_restored'
      ELSE 'draft_restored'
    END;
  ELSIF OLD.active IS DISTINCT FROM NEW.active THEN
    v_event := CASE WHEN NEW.active THEN 'activated' ELSE 'deactivated' END;
  ELSE
    RETURN NEW;
  END IF;

  v_reason := COALESCE(
    NULLIF(trim(current_setting('staynas.rate_plan_publication_reason',true)),''),
    'Rate-plan publication state changed to '||NEW.publication_status
  );
  INSERT INTO public.staynas_rate_plan_publication_events(
    property_id,rate_plan_id,rate_plan_version,previous_status,new_status,
    previous_active,new_active,event_type,actor_id,change_reason
  ) VALUES (
    NEW.property_id,NEW.id,NEW.version,OLD.publication_status,NEW.publication_status,
    OLD.active,NEW.active,v_event,COALESCE(NEW.updated_by,auth.uid()),v_reason
  );
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS staynas_rate_plan_publication_event_capture ON public.staynas_rate_plans;
DROP TRIGGER IF EXISTS zy_staynas_rate_plan_publication_event_capture ON public.staynas_rate_plans;
CREATE TRIGGER zy_staynas_rate_plan_publication_event_capture
  AFTER UPDATE OF publication_status,active ON public.staynas_rate_plans
  FOR EACH ROW EXECUTE FUNCTION public.audit_staynas_rate_plan_publication_event();

CREATE OR REPLACE FUNCTION public.set_staynas_rate_plan_publication(
  _rate_plan_id uuid,
  _publication_status text,
  _active boolean,
  _change_reason text
)
RETURNS public.staynas_rate_plans
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_plan public.staynas_rate_plans%ROWTYPE;
  v_next_active boolean;
  v_updated public.staynas_rate_plans%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF _publication_status NOT IN ('draft','published','suspended','archived') THEN
    RAISE EXCEPTION 'Unsupported rate-plan publication status';
  END IF;
  IF length(trim(COALESCE(_change_reason,''))) NOT BETWEEN 5 AND 500 THEN
    RAISE EXCEPTION 'A publication change reason between 5 and 500 characters is required';
  END IF;

  SELECT * INTO v_plan FROM public.staynas_rate_plans
  WHERE id=_rate_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Rate plan not found'; END IF;
  IF public.staynas_active_property_id(v_uid) IS DISTINCT FROM v_plan.property_id
     OR NOT public.staynas_user_has_property_access(v_uid,v_plan.property_id)
     OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin']::public.app_role[]) THEN
    RAISE EXCEPTION 'Rate-plan publication access denied';
  END IF;
  IF v_plan.publication_status='archived' THEN
    RAISE EXCEPTION 'Archived rate plans are terminal and cannot be changed';
  END IF;

  v_next_active := CASE WHEN _publication_status='archived' THEN false
    ELSE COALESCE(_active,v_plan.active) END;
  IF _publication_status='published' AND NOT v_next_active THEN
    RAISE EXCEPTION 'An inactive rate plan cannot be published';
  END IF;
  IF _publication_status='published' AND NOT EXISTS (
    SELECT 1 FROM public.staynas_rate_plan_room_types a
    WHERE a.property_id=v_plan.property_id AND a.rate_plan_id=v_plan.id AND a.active=true
  ) THEN
    RAISE EXCEPTION 'Assign at least one active room type before publishing';
  END IF;
  IF v_plan.publication_status=_publication_status AND v_plan.active=v_next_active THEN
    RETURN v_plan;
  END IF;

  PERFORM set_config('staynas.rate_plan_publication_reason',trim(_change_reason),true);
  UPDATE public.staynas_rate_plans
  SET publication_status=_publication_status,
      active=v_next_active,
      updated_by=v_uid,
      published_by=CASE WHEN _publication_status='published' THEN v_uid ELSE published_by END,
      published_at=CASE WHEN _publication_status='published' THEN now() ELSE published_at END
  WHERE id=_rate_plan_id
  RETURNING * INTO v_updated;
  RETURN v_updated;
END;
$function$;

REVOKE ALL ON FUNCTION public.set_staynas_rate_plan_publication(uuid,text,boolean,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_staynas_rate_plan_publication(uuid,text,boolean,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_staynas_published_rate_plans(_property_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role',true);
BEGIN
  IF _property_id IS NULL THEN RAISE EXCEPTION 'Property id is required'; END IF;
  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR public.staynas_active_property_id(v_uid) IS DISTINCT FROM _property_id
       OR NOT public.staynas_user_has_property_access(v_uid,_property_id)
       OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin','reservations','reception']::public.app_role[]) THEN
      RAISE EXCEPTION 'Published rate-plan access denied for property';
    END IF;
  END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'publication_id',p.id,
      'property_id',p.property_id,
      'rate_plan_id',p.rate_plan_id,
      'publication_number',p.publication_number,
      'rate_plan_version',p.rate_plan_version,
      'code',p.code,
      'name',p.name,
      'currency',p.currency,
      'effective_from',p.effective_from,
      'effective_to',p.effective_to,
      'published_by',p.published_by,
      'published_at',p.published_at,
      'resolved_data',p.resolved_data,
      'inheritance_trace',p.inheritance_trace,
      'lineage',p.lineage,
      'own_policy',p.own_policy,
      'room_type_assignments',p.room_type_assignments,
      'snapshot_hash',p.snapshot_hash
    ) ORDER BY p.name,p.publication_number), '[]'::jsonb)
    FROM (
      SELECT DISTINCT ON (pub.rate_plan_id) pub.*
      FROM public.staynas_rate_plan_publications pub
      JOIN public.staynas_rate_plans plan
        ON plan.id=pub.rate_plan_id AND plan.property_id=pub.property_id
      WHERE pub.property_id=_property_id
        AND plan.publication_status='published'
        AND plan.active=true
      ORDER BY pub.rate_plan_id,pub.publication_number DESC
    ) p
  );
END;
$function$;
REVOKE ALL ON FUNCTION public.get_staynas_published_rate_plans(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_staynas_published_rate_plans(uuid) TO authenticated,service_role;

REVOKE ALL ON FUNCTION public.prevent_staynas_rate_plan_publication_mutation() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.require_staynas_rate_plan_publication_reason() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.capture_staynas_rate_plan_publication() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.audit_staynas_rate_plan_publication_event() FROM PUBLIC,anon,authenticated;

COMMENT ON TABLE public.staynas_rate_plan_publications IS
  'Immutable, property-scoped resolved rate-plan publication snapshots. Only the latest publication of currently published and active plans is exposed to authorized consumers.';
COMMENT ON TABLE public.staynas_rate_plan_publication_events IS
  'Append-only audit of rate-plan publication, suspension, archive, draft restoration and activation state changes.';
COMMENT ON FUNCTION public.get_staynas_published_rate_plans(uuid) IS
  'Returns immutable publication snapshots for active published rate plans only. Draft and suspended plans are never exposed; no pricing calculation is performed.';
COMMENT ON FUNCTION public.set_staynas_rate_plan_publication(uuid,text,boolean,text) IS
  'Audited property-scoped rate-plan lifecycle transition. Publishing captures a resolved immutable publication snapshot; confirmed bookings are not modified.';

COMMIT;

-- SPE-04.03: strict database validation for canonical base-rate and occupancy JSON.
-- Feature-branch migration only. It is intentionally not applied to UAT or production.
BEGIN;

CREATE OR REPLACE FUNCTION public.validate_staynas_rate_plan_base_and_occupancy_data()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_currency text;
  v_base_rates jsonb;
  v_occupancy_rules jsonb;
  v_room_type_key text;
  v_rule_key text;
  v_rate jsonb;
  v_rules jsonb;
  v_room_type_id uuid;
  v_adults integer;
  v_children_below_6 integer;
  v_children_7_plus integer;
  v_seen integer;
BEGIN
  SELECT upper(p.currency)
    INTO v_currency
  FROM public.staynas_properties p
  WHERE p.id=NEW.property_id AND p.status='active';

  IF v_currency IS NULL OR v_currency !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION USING
      ERRCODE='22023',
      MESSAGE='PROPERTY_CONTEXT_INVALID',
      DETAIL='Rate-plan property must have an explicit valid currency';
  END IF;

  v_base_rates := COALESCE(NEW.rate_plan_data->'base_rates','{}'::jsonb);
  v_occupancy_rules := COALESCE(NEW.rate_plan_data->'occupancy_rules','{}'::jsonb);

  IF jsonb_typeof(v_base_rates) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
      DETAIL='base_rates must be an object keyed by room catalogue type UUID';
  END IF;
  IF jsonb_typeof(v_occupancy_rules) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
      DETAIL='occupancy_rules must be an object keyed by room catalogue type UUID';
  END IF;

  FOR v_room_type_key,v_rate IN SELECT key,value FROM jsonb_each(v_base_rates)
  LOOP
    IF v_room_type_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='base_rates contains an invalid room catalogue type identifier';
    END IF;
    v_room_type_id := v_room_type_key::uuid;
    IF NOT EXISTS (
      SELECT 1 FROM public.rooms r
      WHERE r.property_id=NEW.property_id AND r.catalogue_type_id=v_room_type_id
    ) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='base_rates references a room type outside the property catalogue';
    END IF;
    IF jsonb_typeof(v_rate) IS DISTINCT FROM 'object'
       OR v_rate - ARRAY['nightly_rate','currency']::text[] <> '{}'::jsonb
       OR NOT (v_rate ?& ARRAY['nightly_rate','currency']) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='Each base rate must contain only nightly_rate and currency';
    END IF;
    IF jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='Base nightly_rate must be a JSON number';
    END IF;
    BEGIN
      IF (v_rate->>'nightly_rate')::numeric <= 0 THEN
        RAISE EXCEPTION 'non-positive';
      END IF;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='Base nightly_rate must be a positive decimal';
    END;
    IF jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string'
       OR v_rate->>'currency' !~ '^[A-Z]{3}$' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='Base rate currency must be an uppercase ISO-4217 code';
    END IF;
    IF v_rate->>'currency' IS DISTINCT FROM v_currency
       OR upper(NEW.currency) IS DISTINCT FROM v_currency THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='CURRENCY_MISMATCH',
        DETAIL='Base rate and rate-plan currency must match the property currency';
    END IF;
  END LOOP;

  FOR v_room_type_key,v_rules IN SELECT key,value FROM jsonb_each(v_occupancy_rules)
  LOOP
    IF v_room_type_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='occupancy_rules contains an invalid room catalogue type identifier';
    END IF;
    v_room_type_id := v_room_type_key::uuid;
    IF NOT EXISTS (
      SELECT 1 FROM public.rooms r
      WHERE r.property_id=NEW.property_id AND r.catalogue_type_id=v_room_type_id
    ) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='occupancy_rules references a room type outside the property catalogue';
    END IF;
    IF jsonb_typeof(v_rules) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
        DETAIL='Each occupancy_rules room-type value must be an occupancy-keyed object';
    END IF;

    FOR v_rule_key,v_rate IN SELECT key,value FROM jsonb_each(v_rules)
    LOOP
      IF v_rule_key !~ '^[1-9][0-9]*:[0-9]+:[0-9]+$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
          DETAIL='Occupancy keys must use adults:children_below_6:children_7_plus';
      END IF;
      v_adults := split_part(v_rule_key,':',1)::integer;
      v_children_below_6 := split_part(v_rule_key,':',2)::integer;
      v_children_7_plus := split_part(v_rule_key,':',3)::integer;
      IF v_adults<1 OR v_children_below_6<0 OR v_children_7_plus<0
         OR v_adults+v_children_below_6+v_children_7_plus>30 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
          DETAIL='Occupancy key counts are outside supported bounds';
      END IF;
      IF jsonb_typeof(v_rate) IS DISTINCT FROM 'object'
         OR v_rate - ARRAY['nightly_rate','currency']::text[] <> '{}'::jsonb
         OR NOT (v_rate ?& ARRAY['nightly_rate','currency']) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
          DETAIL='Each occupancy rate must contain only nightly_rate and currency';
      END IF;
      IF jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
          DETAIL='Occupancy nightly_rate must be a JSON number';
      END IF;
      BEGIN
        IF (v_rate->>'nightly_rate')::numeric<=0 THEN
          RAISE EXCEPTION 'non-positive';
        END IF;
      EXCEPTION WHEN others THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
          DETAIL='Occupancy nightly_rate must be a positive decimal';
      END;
      IF jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string'
         OR v_rate->>'currency' !~ '^[A-Z]{3}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
          DETAIL='Occupancy rate currency must be an uppercase ISO-4217 code';
      END IF;
      IF v_rate->>'currency' IS DISTINCT FROM v_currency THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='CURRENCY_MISMATCH',
          DETAIL='Occupancy rate currency must match the property currency';
      END IF;
    END LOOP;
  END LOOP;

  IF NEW.pricing_basis='occupancy_based' AND (SELECT count(*) FROM jsonb_object_keys(v_occupancy_rules))=0 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
      DETAIL='occupancy_based plans require exact occupancy_rules';
  END IF;
  IF NEW.pricing_basis IN ('per_room','per_person')
     AND (SELECT count(*) FROM jsonb_object_keys(v_occupancy_rules))>0 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_RATE_CONFIGURATION',
      DETAIL='Occupancy overrides for per_room/per_person are not supported until a complete included-occupant and extra-fee contract is implemented';
  END IF;

  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS staynas_rate_plans_base_occupancy_guard ON public.staynas_rate_plans;
CREATE TRIGGER staynas_rate_plans_base_occupancy_guard
  BEFORE INSERT OR UPDATE OF property_id,currency,pricing_basis,rate_plan_data
  ON public.staynas_rate_plans
  FOR EACH ROW EXECUTE FUNCTION public.validate_staynas_rate_plan_base_and_occupancy_data();

REVOKE ALL ON FUNCTION public.validate_staynas_rate_plan_base_and_occupancy_data()
  FROM PUBLIC,anon,authenticated;

COMMENT ON FUNCTION public.validate_staynas_rate_plan_base_and_occupancy_data() IS
  'SPE-04.03 strict validation for property-scoped base rates and exact occupancy rate keys. Does not calculate or publish prices.';

COMMIT;

-- SPE-04.03: database-authoritative published-plan nightly resolver.
-- Feature branch only. Existing quote/availability/booking RPCs are not rerouted here.
BEGIN;

CREATE OR REPLACE FUNCTION public.resolve_staynas_published_room_pricing(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0,
  _rate_plan_id uuid DEFAULT NULL,
  _booking_timestamp timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role',true);
  v_room public.rooms%ROWTYPE;
  v_property_currency text;
  v_timezone text;
  v_plan record;
  v_plan_count integer;
  v_active_plan_count integer;
  v_publication record;
  v_data jsonb;
  v_base jsonb;
  v_daily jsonb;
  v_seasons jsonb;
  v_restrictions jsonb;
  v_occupancy jsonb;
  v_occupancy_key text;
  v_rate jsonb;
  v_override record;
  v_day date;
  v_nights integer;
  v_occupants integer;
  v_paid_occupants integer;
  v_rate_amount numeric;
  v_nightly_rate numeric;
  v_subtotal numeric := 0;
  v_source text;
  v_source_id uuid;
  v_source_key text;
  v_breakdown jsonb := '[]'::jsonb;
  v_rule record;
  v_min_los integer := 1;
  v_max_los integer;
  v_local_booking timestamp;
  v_hours numeric;
  v_days numeric;
  v_matches integer;
BEGIN
  IF _property_id IS NULL OR _room_id IS NULL OR _check_in IS NULL OR _check_out IS NULL
     OR _check_out<=_check_in OR COALESCE(_adults,0)<1
     OR COALESCE(_children_below_6,0)<0 OR COALESCE(_children_7_plus,0)<0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','A valid property, room, stay and occupancy are required');
  END IF;

  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR public.staynas_active_property_id(v_uid) IS DISTINCT FROM _property_id
       OR NOT public.staynas_user_has_property_access(v_uid,_property_id)
       OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin','reservations','reception']::public.app_role[]) THEN
      RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED',
        'message','Pricing access denied for property');
    END IF;
  END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','ROOM_NOT_IN_PROPERTY',
      'message','Room is not active in the requested property');
  END IF;

  SELECT upper(p.currency),p.timezone
    INTO v_property_currency,v_timezone
  FROM public.staynas_properties p
  WHERE p.id=_property_id AND p.status='active';
  IF v_property_currency IS NULL OR v_property_currency !~ '^[A-Z]{3}$'
     OR v_timezone IS NULL OR NOT EXISTS (
       SELECT 1 FROM pg_timezone_names WHERE name=v_timezone
     ) THEN
    RETURN jsonb_build_object('ok',false,'error_code','PROPERTY_CONTEXT_INVALID',
      'message','Property currency and valid IANA timezone must be configured');
  END IF;
  IF upper(COALESCE(v_room.currency,''))<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Room currency does not match property currency');
  END IF;

  v_nights := _check_out-_check_in;
  v_occupants := _adults+_children_below_6+_children_7_plus;
  v_paid_occupants := _adults+_children_7_plus;
  IF _adults>COALESCE(v_room.capacity_adults,0)
     OR _children_below_6+_children_7_plus>COALESCE(v_room.capacity_children,0)
     OR v_occupants>COALESCE(v_room.max_occupancy,0) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message','Room occupancy capacity exceeded');
  END IF;

  SELECT count(*) INTO v_active_plan_count
  FROM public.staynas_rate_plans p
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true;

  SELECT count(*) INTO v_plan_count
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number) FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id AND pub2.rate_plan_id=pub.rate_plan_id
    );

  IF _rate_plan_id IS NOT NULL AND v_plan_count=0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Selected plan is not published, active, assigned, or effective for the complete stay');
  END IF;
  IF _rate_plan_id IS NULL AND v_plan_count>1 THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_PLAN_REQUIRED',
      'message','More than one eligible published rate plan applies; select one explicitly');
  END IF;
  IF v_plan_count=0 THEN
    IF v_active_plan_count>0 OR _rate_plan_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
        'message','Property has active published plans but none is eligible for this room and stay');
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'mode','legacy','rate_plan_id',NULL,'publication_id',NULL,
      'pricing',public.calculate_staynas_room_pricing(
        _property_id,_room_id,_check_in,_check_out,_adults,
        COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0)
      )
    );
  END IF;

  SELECT p.id,p.code,p.name,p.currency,p.pricing_basis,p.version,p.property_id
    INTO v_plan
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  WHERE p.id=COALESCE(_rate_plan_id,(
    SELECT p2.id FROM public.staynas_rate_plans p2
    JOIN public.staynas_rate_plan_room_types a2
      ON a2.property_id=p2.property_id AND a2.rate_plan_id=p2.id AND a2.active=true
    JOIN public.staynas_rate_plan_publications x
      ON x.property_id=p2.property_id AND x.rate_plan_id=p2.id
    WHERE p2.property_id=_property_id AND p2.publication_status='published' AND p2.active=true
      AND a2.room_type_id=v_room.catalogue_type_id
      AND (p2.effective_from IS NULL OR p2.effective_from<=_check_in)
      AND (p2.effective_to IS NULL OR p2.effective_to>=_check_out-1)
      AND (x.effective_from IS NULL OR x.effective_from<=_check_in)
      AND (x.effective_to IS NULL OR x.effective_to>=_check_out-1)
    ORDER BY p2.id LIMIT 1
  )) AND p.property_id=_property_id AND a.room_type_id=v_room.catalogue_type_id
  LIMIT 1;

  SELECT pub.* INTO v_publication
  FROM public.staynas_rate_plan_publications pub
  WHERE pub.property_id=_property_id AND pub.rate_plan_id=v_plan.id
  ORDER BY pub.publication_number DESC LIMIT 1;
  IF NOT FOUND OR v_publication.snapshot_hash IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
      'message','Eligible plan has no immutable publication snapshot');
  END IF;
  IF upper(v_plan.currency)<>v_property_currency
     OR upper(v_publication.currency)<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Published plan currency does not match property currency');
  END IF;

  v_data := v_publication.resolved_data;
  v_base := COALESCE(v_data->'base_rates','{}'::jsonb);
  v_daily := COALESCE(v_data->'daily_rates','{}'::jsonb);
  v_seasons := COALESCE(v_data->'seasonal_rates','{}'::jsonb);
  v_restrictions := COALESCE(v_data->'restrictions','{}'::jsonb);
  v_occupancy := COALESCE(v_data->'occupancy_rules','{}'::jsonb);

  IF jsonb_typeof(v_base)<>'object' OR jsonb_typeof(v_daily)<>'object'
     OR jsonb_typeof(v_seasons)<>'object' OR jsonb_typeof(v_restrictions)<>'object'
     OR jsonb_typeof(v_occupancy)<>'object' THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','Published pricing snapshot contains malformed commercial data');
  END IF;

  -- Validate applicable cumulative restrictions before calculating any amount.
  FOR v_rule IN SELECT key,value FROM jsonb_each(v_restrictions)
    WHERE value<>'null'::jsonb AND value->>'active'='true'
  LOOP
    IF NOT (v_rule.value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)) THEN
      CONTINUE;
    END IF;
    CASE v_rule.value->>'type'
      WHEN 'min_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_min_los:=GREATEST(v_min_los,(v_rule.value->>'value')::integer); END IF;
      WHEN 'max_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_max_los:=LEAST(COALESCE(v_max_los,365),(v_rule.value->>'value')::integer); END IF;
      WHEN 'closed_to_arrival' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to arrival');
        END IF;
      WHEN 'closed_to_departure' THEN
        IF _check_out BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to departure');
        END IF;
      WHEN 'stop_sell' THEN
        IF EXISTS (SELECT 1 FROM generate_series(_check_in,_check_out-1,interval '1 day') d
          WHERE d::date BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date) THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Stop sell applies to one or more stay nights');
        END IF;
      WHEN 'advance_booking_min_hours' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_hours:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/3600;
          IF v_hours < (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Minimum advance booking window not met');
          END IF;
        END IF;
      WHEN 'advance_booking_max_days' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_days:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/86400;
          IF v_days > (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Maximum advance booking window exceeded');
          END IF;
        END IF;
      ELSE
        RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Unsupported restriction type');
    END CASE;
  END LOOP;
  IF v_nights<v_min_los OR (v_max_los IS NOT NULL AND v_nights>v_max_los) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message',format('Stay length must be between %s and %s nights',v_min_los,COALESCE(v_max_los::text,'unlimited')));
  END IF;

  IF v_plan.pricing_basis='occupancy_based' THEN
    v_occupancy_key:=format('%s:%s:%s',_adults,COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0));
  END IF;

  v_day:=_check_in;
  WHILE v_day<_check_out LOOP
    v_rate:=NULL; v_source:=NULL; v_source_id:=NULL; v_source_key:=NULL;

    -- Approved overrides: exact room/date, plan+room type, room type, then plan.
    SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
    WHERE o.property_id=_property_id AND o.status='approved'
      AND o.scope='room_date' AND o.room_id=_room_id
      AND o.effective_from=v_day AND o.effective_to=v_day
    ORDER BY o.approved_at DESC,o.id LIMIT 1;
    IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
      v_source:='approved_room_date_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
    ELSE
      SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
      WHERE o.property_id=_property_id AND o.status='approved'
        AND o.scope='rate_plan_room_type' AND o.rate_plan_id=v_plan.id
        AND o.room_type_id=v_room.catalogue_type_id
        AND v_day BETWEEN o.effective_from AND o.effective_to
      ORDER BY o.approved_at DESC,o.id LIMIT 1;
      IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
        v_source:='approved_plan_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
      ELSE
        SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
        WHERE o.property_id=_property_id AND o.status='approved'
          AND o.scope='room_type' AND o.room_type_id=v_room.catalogue_type_id
          AND v_day BETWEEN o.effective_from AND o.effective_to
        ORDER BY o.approved_at DESC,o.id LIMIT 1;
        IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
          v_source:='approved_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
        ELSE
          SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
          WHERE o.property_id=_property_id AND o.status='approved'
            AND o.scope='rate_plan' AND o.rate_plan_id=v_plan.id
            AND v_day BETWEEN o.effective_from AND o.effective_to
          ORDER BY o.approved_at DESC,o.id LIMIT 1;
          IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
            v_source:='approved_plan_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Published daily rate supersedes seasonal and inherited/base rate.
    IF v_rate IS NULL THEN
      v_rate:=v_daily->v_day::text->v_room.catalogue_type_id::text;
      IF v_rate IS NOT NULL AND v_rate<>'null'::jsonb AND COALESCE((v_rate->>'active')::boolean,false) THEN
        v_source:='published_daily_rate'; v_source_key:=v_day::text;
      ELSE
        v_rate:=NULL;
      END IF;
    END IF;

    IF v_rate IS NULL THEN
      SELECT count(*) INTO v_matches
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text);
      SELECT s.key,s.value INTO v_source_key,v_rate
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
      ORDER BY (value->>'priority')::integer DESC,s.key LIMIT 1;
      IF v_matches>1 AND EXISTS (
        SELECT 1 FROM jsonb_each(v_seasons) s(key,value)
        WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
          AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
          AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
          GROUP BY (value->>'priority')::integer HAVING count(*)>1
      ) THEN
        RETURN jsonb_build_object('ok',false,'error_code','AMBIGUOUS_RATE_SOURCE',
          'message','Equal-priority seasonal rates overlap for a charged night');
      END IF;
      IF v_rate IS NOT NULL THEN v_source:='published_seasonal_rate'; END IF;
    END IF;

    IF v_rate IS NULL AND v_plan.pricing_basis='occupancy_based' THEN
      v_rate:=v_occupancy->v_room.catalogue_type_id::text->v_occupancy_key;
      IF v_rate IS NULL OR v_rate='null'::jsonb THEN
        RETURN jsonb_build_object('ok',false,'error_code','OCCUPANCY_RATE_MISSING',
          'message',format('No exact occupancy rate is published for %s',v_day));
      END IF;
      v_source:='published_occupancy_rate'; v_source_key:=v_occupancy_key;
    END IF;
    IF v_rate IS NULL AND v_plan.pricing_basis IN ('per_room','per_person') THEN
      v_rate:=v_base->v_room.catalogue_type_id::text;
      v_source:='published_base_rate'; v_source_key:=v_room.catalogue_type_id::text;
    END IF;
    IF v_rate IS NULL OR v_rate='null'::jsonb
       OR jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string' THEN
      RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
        'message',format('No valid published rate source for %s',v_day));
    END IF;
    IF v_rate->>'currency' IS DISTINCT FROM v_property_currency THEN
      RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
        'message',format('Rate currency mismatch on %s',v_day));
    END IF;
    v_rate_amount:=(v_rate->>'nightly_rate')::numeric;
    IF v_rate_amount<=0 THEN
      RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
        'message',format('Non-positive nightly rate on %s',v_day));
    END IF;
    IF v_source NOT IN ('published_occupancy_rate') THEN
      IF v_plan.pricing_basis='per_person' THEN
        v_nightly_rate:=round(v_rate_amount*v_paid_occupants,2);
      ELSE
        v_nightly_rate:=round(v_rate_amount,2);
      END IF;
    ELSE
      v_nightly_rate:=round(v_rate_amount,2);
    END IF;
    v_subtotal:=round(v_subtotal+v_nightly_rate,2);
    v_breakdown:=v_breakdown||jsonb_build_array(jsonb_build_object(
      'date',v_day,'nightly_rate',v_nightly_rate,'source_rate',v_rate_amount,'currency',v_property_currency,
      'source',v_source,'source_id',v_source_id,'source_key',v_source_key,
      'rate_plan_id',v_plan.id,'publication_id',v_publication.id,
      'publication_number',v_publication.publication_number,
      'rate_plan_version',v_publication.rate_plan_version,
      'snapshot_hash',v_publication.snapshot_hash,
      'pricing_basis',v_plan.pricing_basis,'occupancy_key',v_occupancy_key
    ));
    v_day:=v_day+1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'rate_plan_id',v_plan.id,'rate_plan_code',v_plan.code,
    'rate_plan_name',v_plan.name,'publication_id',v_publication.id,
    'publication_number',v_publication.publication_number,
    'rate_plan_version',v_publication.rate_plan_version,
    'snapshot_hash',v_publication.snapshot_hash,
    'currency',v_property_currency,'timezone',v_timezone,
    'check_in',_check_in,'check_out',_check_out,'nights',v_nights,
    'minimum_stay',v_min_los,
    'adults',_adults,'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),'occupants',v_occupants,
    'billable_occupants',v_paid_occupants,'nightly',v_breakdown,
    'accommodation_subtotal',v_subtotal
  );
EXCEPTION
  WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED','message','Pricing access denied');
  WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing data is malformed');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing resolution failed closed');
END;
$function$;

REVOKE ALL ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz)
  TO authenticated,service_role;

COMMENT ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz) IS
  'SPE-04 database-authoritative published-plan accommodation resolver. Reads latest immutable publication snapshot; returns nightly source evidence and structured fail-closed outcomes. Does not mutate inventory or bookings.';

COMMIT;

-- SPE-04.04-A: route shared accommodation pricing through the SPE-04 resolver.
-- Feature branch only. Do not apply to production without separate release approval.
BEGIN;

-- Preserve the SPE-02 calculator for legacy-only properties. The SPE-04 resolver
-- calls this renamed function in compatibility mode, preventing recursive routing.
ALTER FUNCTION public.calculate_staynas_room_pricing(uuid,uuid,date,date,integer,integer,integer)
  RENAME TO calculate_staynas_room_pricing_legacy;

CREATE OR REPLACE FUNCTION public.resolve_staynas_published_room_pricing(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0,
  _rate_plan_id uuid DEFAULT NULL,
  _booking_timestamp timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role',true);
  v_room public.rooms%ROWTYPE;
  v_property_currency text;
  v_timezone text;
  v_plan record;
  v_plan_count integer;
  v_active_plan_count integer;
  v_publication record;
  v_data jsonb;
  v_base jsonb;
  v_daily jsonb;
  v_seasons jsonb;
  v_restrictions jsonb;
  v_occupancy jsonb;
  v_occupancy_key text;
  v_rate jsonb;
  v_override record;
  v_day date;
  v_nights integer;
  v_occupants integer;
  v_paid_occupants integer;
  v_rate_amount numeric;
  v_nightly_rate numeric;
  v_subtotal numeric := 0;
  v_source text;
  v_source_id uuid;
  v_source_key text;
  v_breakdown jsonb := '[]'::jsonb;
  v_rule record;
  v_min_los integer := 1;
  v_max_los integer;
  v_local_booking timestamp;
  v_hours numeric;
  v_days numeric;
  v_matches integer;
BEGIN
  IF _property_id IS NULL OR _room_id IS NULL OR _check_in IS NULL OR _check_out IS NULL
     OR _check_out<=_check_in OR COALESCE(_adults,0)<1
     OR COALESCE(_children_below_6,0)<0 OR COALESCE(_children_7_plus,0)<0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','A valid property, room, stay and occupancy are required');
  END IF;

  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR public.staynas_active_property_id(v_uid) IS DISTINCT FROM _property_id
       OR NOT public.staynas_user_has_property_access(v_uid,_property_id)
       OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin','reservations','reception']::public.app_role[]) THEN
      RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED',
        'message','Pricing access denied for property');
    END IF;
  END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','ROOM_NOT_IN_PROPERTY',
      'message','Room is not active in the requested property');
  END IF;

  SELECT upper(p.currency),p.timezone
    INTO v_property_currency,v_timezone
  FROM public.staynas_properties p
  WHERE p.id=_property_id AND p.status='active';
  IF v_property_currency IS NULL OR v_property_currency !~ '^[A-Z]{3}$'
     OR v_timezone IS NULL OR NOT EXISTS (
       SELECT 1 FROM pg_timezone_names WHERE name=v_timezone
     ) THEN
    RETURN jsonb_build_object('ok',false,'error_code','PROPERTY_CONTEXT_INVALID',
      'message','Property currency and valid IANA timezone must be configured');
  END IF;
  IF upper(COALESCE(v_room.currency,''))<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Room currency does not match property currency');
  END IF;

  v_nights := _check_out-_check_in;
  v_occupants := _adults+_children_below_6+_children_7_plus;
  v_paid_occupants := _adults+_children_7_plus;
  IF _adults>COALESCE(v_room.capacity_adults,0)
     OR _children_below_6+_children_7_plus>COALESCE(v_room.capacity_children,0)
     OR v_occupants>COALESCE(v_room.max_occupancy,0) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message','Room occupancy capacity exceeded');
  END IF;

  SELECT count(*) INTO v_active_plan_count
  FROM public.staynas_rate_plans p
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true;

  SELECT count(*) INTO v_plan_count
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number) FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id AND pub2.rate_plan_id=pub.rate_plan_id
    );

  IF _rate_plan_id IS NOT NULL AND v_plan_count=0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Selected plan is not published, active, assigned, or effective for the complete stay');
  END IF;
  IF _rate_plan_id IS NULL AND v_plan_count>1 THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_PLAN_REQUIRED',
      'message','More than one eligible published rate plan applies; select one explicitly');
  END IF;
  IF v_plan_count=0 THEN
    IF v_active_plan_count>0 OR _rate_plan_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
        'message','Property has active published plans but none is eligible for this room and stay');
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'mode','legacy','rate_plan_id',NULL,'publication_id',NULL,
      'pricing',public.calculate_staynas_room_pricing_legacy(
        _property_id,_room_id,_check_in,_check_out,_adults,
        COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0)
      )
    );
  END IF;

  SELECT p.id,p.code,p.name,p.currency,p.pricing_basis,p.version,p.property_id
    INTO v_plan
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  WHERE p.id=COALESCE(_rate_plan_id,(
    SELECT p2.id FROM public.staynas_rate_plans p2
    JOIN public.staynas_rate_plan_room_types a2
      ON a2.property_id=p2.property_id AND a2.rate_plan_id=p2.id AND a2.active=true
    JOIN public.staynas_rate_plan_publications x
      ON x.property_id=p2.property_id AND x.rate_plan_id=p2.id
    WHERE p2.property_id=_property_id AND p2.publication_status='published' AND p2.active=true
      AND a2.room_type_id=v_room.catalogue_type_id
      AND (p2.effective_from IS NULL OR p2.effective_from<=_check_in)
      AND (p2.effective_to IS NULL OR p2.effective_to>=_check_out-1)
      AND (x.effective_from IS NULL OR x.effective_from<=_check_in)
      AND (x.effective_to IS NULL OR x.effective_to>=_check_out-1)
    ORDER BY p2.id LIMIT 1
  )) AND p.property_id=_property_id AND a.room_type_id=v_room.catalogue_type_id
  LIMIT 1;

  SELECT pub.* INTO v_publication
  FROM public.staynas_rate_plan_publications pub
  WHERE pub.property_id=_property_id AND pub.rate_plan_id=v_plan.id
  ORDER BY pub.publication_number DESC LIMIT 1;
  IF NOT FOUND OR v_publication.snapshot_hash IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
      'message','Eligible plan has no immutable publication snapshot');
  END IF;
  IF upper(v_plan.currency)<>v_property_currency
     OR upper(v_publication.currency)<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Published plan currency does not match property currency');
  END IF;

  v_data := v_publication.resolved_data;
  v_base := COALESCE(v_data->'base_rates','{}'::jsonb);
  v_daily := COALESCE(v_data->'daily_rates','{}'::jsonb);
  v_seasons := COALESCE(v_data->'seasonal_rates','{}'::jsonb);
  v_restrictions := COALESCE(v_data->'restrictions','{}'::jsonb);
  v_occupancy := COALESCE(v_data->'occupancy_rules','{}'::jsonb);

  IF jsonb_typeof(v_base)<>'object' OR jsonb_typeof(v_daily)<>'object'
     OR jsonb_typeof(v_seasons)<>'object' OR jsonb_typeof(v_restrictions)<>'object'
     OR jsonb_typeof(v_occupancy)<>'object' THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','Published pricing snapshot contains malformed commercial data');
  END IF;

  -- Validate applicable cumulative restrictions before calculating any amount.
  FOR v_rule IN SELECT key,value FROM jsonb_each(v_restrictions)
    WHERE value<>'null'::jsonb AND value->>'active'='true'
  LOOP
    IF NOT (v_rule.value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)) THEN
      CONTINUE;
    END IF;
    CASE v_rule.value->>'type'
      WHEN 'min_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_min_los:=GREATEST(v_min_los,(v_rule.value->>'value')::integer); END IF;
      WHEN 'max_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_max_los:=LEAST(COALESCE(v_max_los,365),(v_rule.value->>'value')::integer); END IF;
      WHEN 'closed_to_arrival' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to arrival');
        END IF;
      WHEN 'closed_to_departure' THEN
        IF _check_out BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to departure');
        END IF;
      WHEN 'stop_sell' THEN
        IF EXISTS (SELECT 1 FROM generate_series(_check_in,_check_out-1,interval '1 day') d
          WHERE d::date BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date) THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Stop sell applies to one or more stay nights');
        END IF;
      WHEN 'advance_booking_min_hours' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_hours:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/3600;
          IF v_hours < (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Minimum advance booking window not met');
          END IF;
        END IF;
      WHEN 'advance_booking_max_days' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_days:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/86400;
          IF v_days > (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Maximum advance booking window exceeded');
          END IF;
        END IF;
      ELSE
        RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Unsupported restriction type');
    END CASE;
  END LOOP;
  IF v_nights<v_min_los OR (v_max_los IS NOT NULL AND v_nights>v_max_los) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message',format('Stay length must be between %s and %s nights',v_min_los,COALESCE(v_max_los::text,'unlimited')));
  END IF;

  IF v_plan.pricing_basis='occupancy_based' THEN
    v_occupancy_key:=format('%s:%s:%s',_adults,COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0));
  END IF;

  v_day:=_check_in;
  WHILE v_day<_check_out LOOP
    v_rate:=NULL; v_source:=NULL; v_source_id:=NULL; v_source_key:=NULL;

    -- Approved overrides: exact room/date, plan+room type, room type, then plan.
    SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
    WHERE o.property_id=_property_id AND o.status='approved'
      AND o.scope='room_date' AND o.room_id=_room_id
      AND o.effective_from=v_day AND o.effective_to=v_day
    ORDER BY o.approved_at DESC,o.id LIMIT 1;
    IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
      v_source:='approved_room_date_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
    ELSE
      SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
      WHERE o.property_id=_property_id AND o.status='approved'
        AND o.scope='rate_plan_room_type' AND o.rate_plan_id=v_plan.id
        AND o.room_type_id=v_room.catalogue_type_id
        AND v_day BETWEEN o.effective_from AND o.effective_to
      ORDER BY o.approved_at DESC,o.id LIMIT 1;
      IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
        v_source:='approved_plan_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
      ELSE
        SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
        WHERE o.property_id=_property_id AND o.status='approved'
          AND o.scope='room_type' AND o.room_type_id=v_room.catalogue_type_id
          AND v_day BETWEEN o.effective_from AND o.effective_to
        ORDER BY o.approved_at DESC,o.id LIMIT 1;
        IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
          v_source:='approved_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
        ELSE
          SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
          WHERE o.property_id=_property_id AND o.status='approved'
            AND o.scope='rate_plan' AND o.rate_plan_id=v_plan.id
            AND v_day BETWEEN o.effective_from AND o.effective_to
          ORDER BY o.approved_at DESC,o.id LIMIT 1;
          IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
            v_source:='approved_plan_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Published daily rate supersedes seasonal and inherited/base rate.
    IF v_rate IS NULL THEN
      v_rate:=v_daily->v_day::text->v_room.catalogue_type_id::text;
      IF v_rate IS NOT NULL AND v_rate<>'null'::jsonb AND COALESCE((v_rate->>'active')::boolean,false) THEN
        v_source:='published_daily_rate'; v_source_key:=v_day::text;
      ELSE
        v_rate:=NULL;
      END IF;
    END IF;

    IF v_rate IS NULL THEN
      SELECT count(*) INTO v_matches
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text);
      SELECT s.key,s.value INTO v_source_key,v_rate
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
      ORDER BY (value->>'priority')::integer DESC,s.key LIMIT 1;
      IF v_matches>1 AND EXISTS (
        SELECT 1 FROM jsonb_each(v_seasons) s(key,value)
        WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
          AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
          AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
          GROUP BY (value->>'priority')::integer HAVING count(*)>1
      ) THEN
        RETURN jsonb_build_object('ok',false,'error_code','AMBIGUOUS_RATE_SOURCE',
          'message','Equal-priority seasonal rates overlap for a charged night');
      END IF;
      IF v_rate IS NOT NULL THEN v_source:='published_seasonal_rate'; END IF;
    END IF;

    IF v_rate IS NULL AND v_plan.pricing_basis='occupancy_based' THEN
      v_rate:=v_occupancy->v_room.catalogue_type_id::text->v_occupancy_key;
      IF v_rate IS NULL OR v_rate='null'::jsonb THEN
        RETURN jsonb_build_object('ok',false,'error_code','OCCUPANCY_RATE_MISSING',
          'message',format('No exact occupancy rate is published for %s',v_day));
      END IF;
      v_source:='published_occupancy_rate'; v_source_key:=v_occupancy_key;
    END IF;
    IF v_rate IS NULL AND v_plan.pricing_basis IN ('per_room','per_person') THEN
      v_rate:=v_base->v_room.catalogue_type_id::text;
      v_source:='published_base_rate'; v_source_key:=v_room.catalogue_type_id::text;
    END IF;
    IF v_rate IS NULL OR v_rate='null'::jsonb
       OR jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string' THEN
      RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
        'message',format('No valid published rate source for %s',v_day));
    END IF;
    IF v_rate->>'currency' IS DISTINCT FROM v_property_currency THEN
      RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
        'message',format('Rate currency mismatch on %s',v_day));
    END IF;
    v_rate_amount:=(v_rate->>'nightly_rate')::numeric;
    IF v_rate_amount<=0 THEN
      RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
        'message',format('Non-positive nightly rate on %s',v_day));
    END IF;
    IF v_source NOT IN ('published_occupancy_rate') THEN
      IF v_plan.pricing_basis='per_person' THEN
        v_nightly_rate:=round(v_rate_amount*v_paid_occupants,2);
      ELSE
        v_nightly_rate:=round(v_rate_amount,2);
      END IF;
    ELSE
      v_nightly_rate:=round(v_rate_amount,2);
    END IF;
    v_subtotal:=round(v_subtotal+v_nightly_rate,2);
    v_breakdown:=v_breakdown||jsonb_build_array(jsonb_build_object(
      'date',v_day,'nightly_rate',v_nightly_rate,'source_rate',v_rate_amount,'currency',v_property_currency,
      'source',v_source,'source_id',v_source_id,'source_key',v_source_key,
      'rate_plan_id',v_plan.id,'publication_id',v_publication.id,
      'publication_number',v_publication.publication_number,
      'rate_plan_version',v_publication.rate_plan_version,
      'snapshot_hash',v_publication.snapshot_hash,
      'pricing_basis',v_plan.pricing_basis,'occupancy_key',v_occupancy_key
    ));
    v_day:=v_day+1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'rate_plan_id',v_plan.id,'rate_plan_code',v_plan.code,
    'rate_plan_name',v_plan.name,'publication_id',v_publication.id,
    'publication_number',v_publication.publication_number,
    'rate_plan_version',v_publication.rate_plan_version,
    'snapshot_hash',v_publication.snapshot_hash,
    'currency',v_property_currency,'timezone',v_timezone,
    'check_in',_check_in,'check_out',_check_out,'nights',v_nights,
    'minimum_stay',v_min_los,
    'adults',_adults,'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),'occupants',v_occupants,
    'billable_occupants',v_paid_occupants,'nightly',v_breakdown,
    'accommodation_subtotal',v_subtotal
  );
EXCEPTION
  WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED','message','Pricing access denied');
  WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing data is malformed');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing resolution failed closed');
END;
$function$;

CREATE OR REPLACE FUNCTION public.calculate_staynas_room_pricing(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $adapter$
DECLARE
  v_result jsonb;
  v_nightly jsonb;
  v_room public.rooms%ROWTYPE;
BEGIN
  v_result:=public.resolve_staynas_published_room_pricing(
    _property_id,_room_id,_check_in,_check_out,_adults,
    COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0),NULL,now()
  );
  IF v_result->>'ok'='false' THEN RETURN v_result; END IF;
  IF v_result->>'mode'='legacy' THEN RETURN v_result->'pricing'; END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  SELECT COALESCE(jsonb_agg(
    n.value || jsonb_build_object(
      'base_rate',n.value->'source_rate',
      'occupancy_surcharge',0,
      'adjustment',0,
      'applied_rule_id',NULL,
      'applied_rule_type',n.value->>'source'
    ) ORDER BY n.ordinality
  ),'[]'::jsonb)
  INTO v_nightly
  FROM jsonb_array_elements(v_result->'nightly') WITH ORDINALITY n(value,ordinality);

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'currency',v_result->>'currency','check_in',_check_in,'check_out',_check_out,
    'nights',(v_result->>'nights')::integer,
    'adults',_adults,'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),
    'occupants',(v_result->>'occupants')::integer,
    'paid_occupants',(v_result->>'billable_occupants')::integer,
    'extra_occupants',0,'minimum_stay',COALESCE((v_result->>'minimum_stay')::integer,1),
    'nightly',v_nightly,
    'accommodation_subtotal',(v_result->>'accommodation_subtotal')::numeric,
    'pricing_evidence',jsonb_build_object(
      'rate_plan_id',v_result->'rate_plan_id',
      'publication_id',v_result->'publication_id',
      'publication_number',v_result->'publication_number',
      'rate_plan_version',v_result->'rate_plan_version',
      'snapshot_hash',v_result->'snapshot_hash',
      'timezone',v_result->'timezone'
    )
  );
END;
$adapter$;

CREATE OR REPLACE FUNCTION public.calculate_staynas_booking_quote(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0,
  _extras jsonb DEFAULT '[]'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_room_quote jsonb;
  v_extra record;
  v_extra_row public.extras%ROWTYPE;
  v_quantity integer;
  v_line numeric;
  v_extras_total numeric := 0;
  v_extra_lines jsonb := '[]'::jsonb;
  v_tax jsonb;
  v_tax_addition numeric := 0;
  v_tax_total numeric := 0;
  v_total numeric := 0;
  v_nights integer;
  v_occupants integer;
  v_currency text;
BEGIN
  IF jsonb_typeof(COALESCE(_extras,'[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Extras must be an array';
  END IF;
  v_room_quote := public.calculate_staynas_room_pricing(
    _property_id,_room_id,_check_in,_check_out,_adults,_children_below_6,_children_7_plus
  );
  IF v_room_quote->>'ok'='false' THEN RETURN v_room_quote; END IF;
  v_nights := (v_room_quote->>'nights')::integer;
  v_occupants := (v_room_quote->>'occupants')::integer;
  v_currency := v_room_quote->>'currency';

  FOR v_extra IN
    SELECT e->>'slug' AS slug, COALESCE((e->>'quantity')::integer,1) AS quantity
    FROM jsonb_array_elements(COALESCE(_extras,'[]'::jsonb)) e
  LOOP
    IF v_extra.slug IS NULL OR v_extra.quantity < 1 OR v_extra.quantity > 20 THEN
      RAISE EXCEPTION 'Invalid extra or quantity';
    END IF;
    SELECT * INTO v_extra_row
    FROM public.extras e
    WHERE e.slug = v_extra.slug AND e.active = true AND e.property_id = _property_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Extra not found for property: %',v_extra.slug; END IF;
    IF v_extra_row.currency IS NOT NULL AND upper(v_extra_row.currency) <> v_currency THEN
      RAISE EXCEPTION 'Extra currency % does not match property currency %',v_extra_row.currency,v_currency;
    END IF;
    v_line := round(v_extra_row.price * v_extra.quantity * CASE v_extra_row.unit
      WHEN 'per_stay' THEN 1
      WHEN 'per_night' THEN v_nights
      WHEN 'per_person' THEN v_occupants
      WHEN 'per_person_per_night' THEN v_occupants * v_nights
      ELSE 1
    END,2);
    v_extras_total := round(v_extras_total + v_line,2);
    v_extra_lines := v_extra_lines || jsonb_build_array(jsonb_build_object(
      'slug',v_extra_row.slug,'name',v_extra_row.name,'quantity',v_extra.quantity,
      'unit_price',v_extra_row.price,'unit',v_extra_row.unit,'line_total',v_line,
      'currency',v_currency
    ));
  END LOOP;

  v_tax := public.calculate_staynas_booking_taxes(
    _property_id,_check_in,v_nights,(v_room_quote->>'accommodation_subtotal')::numeric,
    v_extras_total,v_currency
  );
  v_tax_total := COALESCE((v_tax->>'tax_total')::numeric,0);
  v_tax_addition := COALESCE((v_tax->>'tax_addition')::numeric,0);
  v_total := round((v_room_quote->>'accommodation_subtotal')::numeric + v_extras_total + v_tax_addition,2);

  RETURN jsonb_build_object(
    'property_id',_property_id,'room_id',_room_id,'currency',v_currency,
    'check_in',_check_in,'check_out',_check_out,'nights',v_nights,
    'nightly',v_room_quote->'nightly',
    'pricing_evidence',v_room_quote->'pricing_evidence',
    'accommodation_subtotal',(v_room_quote->>'accommodation_subtotal')::numeric,
    'extras',v_extra_lines,'extras_total',v_extras_total,
    'taxes',v_tax_total,'tax_addition',v_tax_addition,
    'tax_breakdown',COALESCE(v_tax->'breakdown','[]'::jsonb),
    'total',v_total,'deposit_amount',round(v_total/2,2),
    'balance_due',v_total-round(v_total/2,2),
    'minimum_stay',(v_room_quote->>'minimum_stay')::integer,
    'occupants',(v_room_quote->>'occupants')::integer,
    'paid_occupants',(v_room_quote->>'paid_occupants')::integer,
    'extra_occupants',(v_room_quote->>'extra_occupants')::integer
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.try_calculate_staynas_booking_quote(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $safe$
DECLARE v_quote jsonb;
BEGIN
  v_quote:=public.calculate_staynas_booking_quote(
    _property_id,_room_id,_check_in,_check_out,_adults,_children_below_6,_children_7_plus,'[]'::jsonb
  );
  RETURN v_quote;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
    'message','Pricing quote failed closed');
END;
$safe$;

CREATE OR REPLACE FUNCTION public.get_staynas_room_availability_priced(
  _check_in date,
  _check_out date,
  _property_id uuid,
  _adults integer DEFAULT 1,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0
)
RETURNS TABLE(
  room_id uuid, slug text, name text, base_price numeric, currency text,
  capacity_adults integer, capacity_children integer, max_occupancy integer,
  included_guests integer, extra_guest_fee numeric, nights integer,
  nightly_total numeric, min_available integer, is_available boolean,
  fits_occupancy boolean, pricing_quote jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF _check_out <= _check_in THEN RAISE EXCEPTION 'check_out must be after check_in'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.staynas_properties p WHERE p.id=_property_id AND p.status='active') THEN
    RAISE EXCEPTION 'Property is not active or does not exist';
  END IF;
  RETURN QUERY
  WITH date_range AS (
    SELECT generate_series(_check_in,_check_out - interval '1 day',interval '1 day')::date AS d
  ), inventory AS (
    SELECT r.id AS room_id, dr.d,
      COALESCE(i.available_units,r.total_units) AS units,
      COALESCE(i.is_blocked,false) AS blocked,
      (SELECT count(*)::integer FROM public.booking_holds h
       WHERE h.room_id=r.id AND h.status='active' AND h.expires_at>now()
         AND h.check_in<=dr.d AND h.check_out>dr.d) AS hold_count
    FROM public.rooms r CROSS JOIN date_range dr
    LEFT JOIN public.room_inventory i ON i.room_id=r.id AND i.date=dr.d
    WHERE r.property_id=_property_id AND r.status='active'
  ), stock AS (
    SELECT inventory.room_id, min(greatest(units-hold_count,0))::integer AS min_units,
      bool_and(NOT blocked AND units-hold_count>0) AS available
    FROM inventory GROUP BY inventory.room_id
  )
  SELECT r.id,r.slug,r.name,r.base_price,r.currency,r.capacity_adults,r.capacity_children,
    r.max_occupancy,r.included_guests,r.extra_guest_fee,(_check_out-_check_in),
    CASE WHEN q.quote IS NULL OR q.quote->>'ok'='false' THEN 0 ELSE (q.quote->>'total')::numeric END,
    COALESCE(s.min_units,0),(COALESCE(s.available,false) AND q.quote IS NOT NULL AND COALESCE(q.quote->>'ok','true')<>'false'),
    (_adults<=r.capacity_adults
      AND (_children_below_6+_children_7_plus)<=r.capacity_children
      AND (_adults+_children_below_6+_children_7_plus)<=r.max_occupancy),
    q.quote
  FROM public.rooms r
  LEFT JOIN stock s ON s.room_id=r.id
  LEFT JOIN LATERAL (
    SELECT public.try_calculate_staynas_booking_quote(
      _property_id,r.id,_check_in,_check_out,_adults,_children_below_6,_children_7_plus
    ) AS quote
    WHERE _adults<=r.capacity_adults
      AND (_children_below_6+_children_7_plus)<=r.capacity_children
      AND (_adults+_children_below_6+_children_7_plus)<=r.max_occupancy
  ) q ON true
  WHERE r.property_id=_property_id AND r.status='active'
  ORDER BY CASE WHEN q.quote IS NULL OR q.quote->>'ok'='false' THEN 1 ELSE 0 END,
    CASE WHEN q.quote IS NULL OR q.quote->>'ok'='false' THEN r.base_price ELSE (q.quote->>'total')::numeric END;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_booking_for_property(
  _property_id uuid,
  _room_slug text,
  _check_in date,
  _check_out date,
  _adults integer,
  _children integer,
  _guest_name text,
  _guest_email text,
  _guest_phone text,
  _country text,
  _special_requests text,
  _extras jsonb DEFAULT '[]'::jsonb,
  _children_below_6 integer DEFAULT NULL,
  _children_7_plus integer DEFAULT NULL,
  _hold_id uuid DEFAULT NULL,
  _session_id text DEFAULT NULL,
  _payment_method text DEFAULT 'online'
)
RETURNS TABLE(
  booking_id uuid, reference text, total numeric, currency text,
  taxes numeric, tax_addition numeric, tax_breakdown jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_room public.rooms%ROWTYPE;
  v_hold public.booking_holds%ROWTYPE;
  v_extra public.extras%ROWTYPE;
  v_quote jsonb;
  v_night jsonb;
  v_extra_line jsonb;
  v_day date;
  v_units integer;
  v_other_holds integer;
  v_blocked boolean;
  v_booking_id uuid;
  v_reference text;
  v_below6 integer := COALESCE(_children_below_6,0);
  v_plus7 integer := COALESCE(_children_7_plus,GREATEST(0,COALESCE(_children,0)));
  v_children_total integer;
  v_nights integer;
  v_subtotal numeric;
  v_extras_total numeric;
  v_taxes numeric;
  v_tax_addition numeric;
  v_tax_breakdown jsonb;
  v_total numeric;
  v_deposit numeric;
  v_balance numeric;
  v_payment_method text := COALESCE(_payment_method,'online');
BEGIN
  IF _property_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.staynas_properties p WHERE p.id=_property_id AND p.status='active'
  ) THEN RAISE EXCEPTION 'Property not found or inactive'; END IF;
  IF _check_out<=_check_in THEN RAISE EXCEPTION 'check_out must be after check_in'; END IF;
  IF _adults IS NULL OR _adults<1 THEN RAISE EXCEPTION 'At least one adult required'; END IF;
  IF _guest_name IS NULL OR length(trim(_guest_name))<2 THEN RAISE EXCEPTION 'Guest name required'; END IF;
  IF _guest_email IS NULL OR _guest_email !~* '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' THEN RAISE EXCEPTION 'Valid email required'; END IF;
  IF v_payment_method NOT IN ('online','pay_at_property') THEN RAISE EXCEPTION 'Unsupported booking payment method'; END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.slug=_room_slug AND r.status='active' AND r.property_id=_property_id
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Room not found for property'; END IF;

  v_children_total := v_below6 + v_plus7;
  IF _children IS NOT NULL AND _children <> v_children_total THEN
    RAISE EXCEPTION 'Child counts do not match the supplied occupancy';
  END IF;
  v_nights := _check_out - _check_in;
  IF _hold_id IS NOT NULL THEN
    SELECT h.* INTO v_hold FROM public.booking_holds h
    JOIN public.rooms r ON r.id=h.room_id
    WHERE h.id=_hold_id AND r.property_id=_property_id
    FOR UPDATE OF h;
    IF NOT FOUND OR v_hold.status<>'active' OR v_hold.expires_at<=now() THEN
      RAISE EXCEPTION 'Booking hold invalid for property';
    END IF;
    IF v_hold.room_id<>v_room.id OR v_hold.check_in<>_check_in OR v_hold.check_out<>_check_out THEN
      RAISE EXCEPTION 'Hold does not match booking';
    END IF;
    IF _session_id IS NULL OR v_hold.session_id<>_session_id THEN RAISE EXCEPTION 'Hold session mismatch'; END IF;
  END IF;

  -- Lock the rows that determine the quote before resolving it. The final
  -- quote, nightly snapshot and inventory decrement therefore share one
  -- transactionally consistent pricing/inventory view.
  v_day := _check_in;
  WHILE v_day < _check_out LOOP
    INSERT INTO public.room_inventory(room_id,date,available_units)
    VALUES(v_room.id,v_day,v_room.total_units)
    ON CONFLICT(room_id,date) DO NOTHING;
    PERFORM 1 FROM public.room_inventory i
    WHERE i.room_id=v_room.id AND i.date=v_day FOR UPDATE;
    v_day := v_day + 1;
  END LOOP;

  PERFORM 1 FROM public.pricing_rules pr
  WHERE pr.property_id=_property_id AND pr.active=true
    AND (pr.scope='all' OR pr.room_id=v_room.id)
    AND (pr.starts_on IS NULL OR pr.starts_on<_check_out)
    AND (pr.ends_on IS NULL OR pr.ends_on>=_check_in)
  FOR SHARE;

  PERFORM 1 FROM public.staynas_property_tax_rules tr
  WHERE tr.property_id=_property_id AND tr.active=true
    AND (tr.valid_from IS NULL OR tr.valid_from<=_check_in)
    AND (tr.valid_to IS NULL OR tr.valid_to>=_check_in)
  FOR SHARE;

  PERFORM 1 FROM public.extras e
  WHERE e.property_id=_property_id AND e.active=true
    AND e.slug IN (
      SELECT item.value->>'slug' FROM jsonb_array_elements(COALESCE(_extras,'[]'::jsonb)) AS item(value)
    )
  FOR SHARE;

  v_quote := public.calculate_staynas_booking_quote(
    _property_id,v_room.id,_check_in,_check_out,_adults,v_below6,v_plus7,_extras
  );
  IF v_quote->>'ok'='false' THEN
    RAISE EXCEPTION 'StayNas pricing rejected [%]: %',v_quote->>'error_code',v_quote->>'message';
  END IF;
  v_room.currency := upper(v_room.currency);
  v_subtotal := (v_quote->>'accommodation_subtotal')::numeric;
  v_extras_total := (v_quote->>'extras_total')::numeric;
  v_taxes := (v_quote->>'taxes')::numeric;
  v_tax_addition := (v_quote->>'tax_addition')::numeric;
  v_tax_breakdown := COALESCE(v_quote->'tax_breakdown','[]'::jsonb);
  v_total := (v_quote->>'total')::numeric;
  v_deposit := CASE WHEN v_payment_method='pay_at_property' THEN 0 ELSE round(v_total/2,2) END;
  v_balance := v_total-v_deposit;
  v_reference := upper(substr(md5(random()::text||clock_timestamp()::text),1,10)) || '-' || to_char(now(),'YYMMDD');

  INSERT INTO public.bookings(
    reference,room_id,property_id,check_in,check_out,nights,adults,children,
    children_below_6,children_7_plus,guest_name,guest_email,guest_phone,country,
    special_requests,currency,source,payment_method,payment_provider,
    subtotal,extras_total,taxes,tax_addition,tax_breakdown,total,deposit_amount,balance_amount,balance_due,
    pricing_snapshot
  )
  VALUES(
    v_reference,v_room.id,_property_id,_check_in,_check_out,v_nights,_adults,v_children_total,
    v_below6,v_plus7,trim(_guest_name),lower(trim(_guest_email)),_guest_phone,_country,
    _special_requests,v_room.currency,'website',
    CASE WHEN v_payment_method='pay_at_property' THEN 'pay_at_property' ELSE NULL END,
    CASE WHEN v_payment_method='pay_at_property' THEN 'manual' ELSE 'pesapal' END,
    v_subtotal,v_extras_total,v_taxes,v_tax_addition,v_tax_breakdown,v_total,v_deposit,v_balance,v_balance,
    v_quote
  )
  RETURNING id INTO v_booking_id;

  FOR v_night IN SELECT value FROM jsonb_array_elements(v_quote->'nightly')
  LOOP
    v_day := (v_night->>'date')::date;
    INSERT INTO public.room_inventory(room_id,date,available_units)
    VALUES(v_room.id,v_day,v_room.total_units)
    ON CONFLICT(room_id,date) DO NOTHING;
    SELECT i.available_units,i.is_blocked,
      (SELECT count(*)::integer FROM public.booking_holds h
       WHERE h.room_id=v_room.id AND h.status='active' AND h.expires_at>now()
         AND h.check_in<=v_day AND h.check_out>v_day
         AND (_hold_id IS NULL OR h.id<>_hold_id))
    INTO v_units,v_blocked,v_other_holds
    FROM public.room_inventory i WHERE i.room_id=v_room.id AND i.date=v_day FOR UPDATE;
    IF v_blocked THEN RAISE EXCEPTION 'Room blocked on %',v_day; END IF;
    IF v_units-COALESCE(v_other_holds,0)<=0 THEN
      RAISE EXCEPTION 'No availability on %',v_day;
    END IF;
    UPDATE public.room_inventory SET available_units=GREATEST(available_units-1,0)
    WHERE room_id=v_room.id AND date=v_day;
    INSERT INTO public.booking_nights(booking_id,room_id,date,nightly_rate,pricing_snapshot)
    VALUES(v_booking_id,v_room.id,v_day,(v_night->>'nightly_rate')::numeric,v_night);
  END LOOP;

  FOR v_extra_line IN SELECT value FROM jsonb_array_elements(v_quote->'extras')
  LOOP
    SELECT * INTO v_extra FROM public.extras e
    WHERE e.slug=v_extra_line->>'slug' AND e.active=true AND e.property_id=_property_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Extra became unavailable during booking'; END IF;
    INSERT INTO public.booking_extras(booking_id,extra_id,quantity,unit_price,line_total)
    VALUES(v_booking_id,v_extra.id,(v_extra_line->>'quantity')::integer,
      (v_extra_line->>'unit_price')::numeric,(v_extra_line->>'line_total')::numeric);
  END LOOP;

  IF _hold_id IS NOT NULL THEN
    UPDATE public.booking_holds SET status='converted',converted_booking_id=v_booking_id,updated_at=now()
    WHERE id=_hold_id;
  END IF;
  PERFORM public.log_calendar_event(
    'reservation.created',v_room.id,v_booking_id,_hold_id,_check_in,_check_out,
    jsonb_build_object('property_id',_property_id,'reference',v_reference,'total',v_total,'currency',v_room.currency)
  );
  RETURN QUERY SELECT v_booking_id,v_reference,v_total,v_room.currency,v_taxes,v_tax_addition,v_tax_breakdown;
END;
$$;

-- The historical 16-argument booking RPC must not retain its older direct-pricing
-- implementation. Keep its return shape and delegate to the shared 17-argument path.
CREATE OR REPLACE FUNCTION public.create_booking_for_property(
  _property_id uuid,
  _room_slug text,
  _check_in date,
  _check_out date,
  _adults integer,
  _children integer,
  _guest_name text,
  _guest_email text,
  _guest_phone text,
  _country text,
  _special_requests text,
  _extras jsonb DEFAULT '[]'::jsonb,
  _children_below_6 integer DEFAULT NULL,
  _children_7_plus integer DEFAULT NULL,
  _hold_id uuid DEFAULT NULL,
  _session_id text DEFAULT NULL
)
RETURNS TABLE(booking_id uuid,reference text,total numeric,currency text)
LANGUAGE sql
SECURITY DEFINER
SET search_path=public
AS $compat$
  SELECT b.booking_id,b.reference,b.total,b.currency
  FROM public.create_booking_for_property(
    _property_id,_room_slug,_check_in,_check_out,_adults,_children,
    _guest_name,_guest_email,_guest_phone,_country,_special_requests,
    _extras,_children_below_6,_children_7_plus,_hold_id,_session_id,'online'
  ) b;
$compat$;

-- Keep the adapter internal, matching the SPE-02 RPC privilege boundary.
REVOKE ALL ON FUNCTION public.calculate_staynas_room_pricing(uuid,uuid,date,date,integer,integer,integer)
  FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.calculate_staynas_room_pricing_legacy(uuid,uuid,date,date,integer,integer,integer)
  FROM PUBLIC,anon,authenticated,service_role;


COMMIT;

-- SPE-04.05 regression correction: implicit selection must use the latest publication only.
-- Keeps the candidate count and selected plan query on the same immutable publication.
BEGIN;

CREATE OR REPLACE FUNCTION public.resolve_staynas_published_room_pricing(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0,
  _rate_plan_id uuid DEFAULT NULL,
  _booking_timestamp timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role',true);
  v_room public.rooms%ROWTYPE;
  v_property_currency text;
  v_timezone text;
  v_plan record;
  v_plan_count integer;
  v_active_plan_count integer;
  v_publication record;
  v_data jsonb;
  v_base jsonb;
  v_daily jsonb;
  v_seasons jsonb;
  v_restrictions jsonb;
  v_occupancy jsonb;
  v_occupancy_key text;
  v_rate jsonb;
  v_override record;
  v_day date;
  v_nights integer;
  v_occupants integer;
  v_paid_occupants integer;
  v_rate_amount numeric;
  v_nightly_rate numeric;
  v_subtotal numeric := 0;
  v_source text;
  v_source_id uuid;
  v_source_key text;
  v_breakdown jsonb := '[]'::jsonb;
  v_rule record;
  v_min_los integer := 1;
  v_max_los integer;
  v_local_booking timestamp;
  v_hours numeric;
  v_days numeric;
  v_matches integer;
BEGIN
  IF _property_id IS NULL OR _room_id IS NULL OR _check_in IS NULL OR _check_out IS NULL
     OR _check_out<=_check_in OR COALESCE(_adults,0)<1
     OR COALESCE(_children_below_6,0)<0 OR COALESCE(_children_7_plus,0)<0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','A valid property, room, stay and occupancy are required');
  END IF;

  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR public.staynas_active_property_id(v_uid) IS DISTINCT FROM _property_id
       OR NOT public.staynas_user_has_property_access(v_uid,_property_id)
       OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin','reservations','reception']::public.app_role[]) THEN
      RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED',
        'message','Pricing access denied for property');
    END IF;
  END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','ROOM_NOT_IN_PROPERTY',
      'message','Room is not active in the requested property');
  END IF;

  SELECT upper(p.currency),p.timezone
    INTO v_property_currency,v_timezone
  FROM public.staynas_properties p
  WHERE p.id=_property_id AND p.status='active';
  IF v_property_currency IS NULL OR v_property_currency !~ '^[A-Z]{3}$'
     OR v_timezone IS NULL OR NOT EXISTS (
       SELECT 1 FROM pg_timezone_names WHERE name=v_timezone
     ) THEN
    RETURN jsonb_build_object('ok',false,'error_code','PROPERTY_CONTEXT_INVALID',
      'message','Property currency and valid IANA timezone must be configured');
  END IF;
  IF upper(COALESCE(v_room.currency,''))<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Room currency does not match property currency');
  END IF;

  v_nights := _check_out-_check_in;
  v_occupants := _adults+_children_below_6+_children_7_plus;
  v_paid_occupants := _adults+_children_7_plus;
  IF _adults>COALESCE(v_room.capacity_adults,0)
     OR _children_below_6+_children_7_plus>COALESCE(v_room.capacity_children,0)
     OR v_occupants>COALESCE(v_room.max_occupancy,0) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message','Room occupancy capacity exceeded');
  END IF;

  SELECT count(*) INTO v_active_plan_count
  FROM public.staynas_rate_plans p
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true;

  SELECT count(*) INTO v_plan_count
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number) FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id AND pub2.rate_plan_id=pub.rate_plan_id
    );

  IF _rate_plan_id IS NOT NULL AND v_plan_count=0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Selected plan is not published, active, assigned, or effective for the complete stay');
  END IF;
  IF _rate_plan_id IS NULL AND v_plan_count>1 THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_PLAN_REQUIRED',
      'message','More than one eligible published rate plan applies; select one explicitly');
  END IF;
  IF v_plan_count=0 THEN
    IF v_active_plan_count>0 OR _rate_plan_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
        'message','Property has active published plans but none is eligible for this room and stay');
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'mode','legacy','rate_plan_id',NULL,'publication_id',NULL,
      'pricing',public.calculate_staynas_room_pricing_legacy(
        _property_id,_room_id,_check_in,_check_out,_adults,
        COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0)
      )
    );
  END IF;

  SELECT p.id,p.code,p.name,p.currency,p.pricing_basis,p.version,p.property_id
    INTO v_plan
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  WHERE p.id=COALESCE(_rate_plan_id,(
    SELECT p2.id FROM public.staynas_rate_plans p2
    JOIN public.staynas_rate_plan_room_types a2
      ON a2.property_id=p2.property_id AND a2.rate_plan_id=p2.id AND a2.active=true
    JOIN public.staynas_rate_plan_publications x
      ON x.property_id=p2.property_id AND x.rate_plan_id=p2.id
    WHERE p2.property_id=_property_id AND p2.publication_status='published' AND p2.active=true
      AND a2.room_type_id=v_room.catalogue_type_id
      AND (p2.effective_from IS NULL OR p2.effective_from<=_check_in)
      AND (p2.effective_to IS NULL OR p2.effective_to>=_check_out-1)
      AND (x.effective_from IS NULL OR x.effective_from<=_check_in)
      AND (x.effective_to IS NULL OR x.effective_to>=_check_out-1)
      AND x.publication_number=(
        SELECT max(x2.publication_number)
        FROM public.staynas_rate_plan_publications x2
        WHERE x2.property_id=x.property_id AND x2.rate_plan_id=x.rate_plan_id
      )
    ORDER BY p2.id LIMIT 1
  )) AND p.property_id=_property_id AND a.room_type_id=v_room.catalogue_type_id
  LIMIT 1;

  SELECT pub.* INTO v_publication
  FROM public.staynas_rate_plan_publications pub
  WHERE pub.property_id=_property_id AND pub.rate_plan_id=v_plan.id
  ORDER BY pub.publication_number DESC LIMIT 1;
  IF NOT FOUND OR v_publication.snapshot_hash IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
      'message','Eligible plan has no immutable publication snapshot');
  END IF;
  IF upper(v_plan.currency)<>v_property_currency
     OR upper(v_publication.currency)<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Published plan currency does not match property currency');
  END IF;

  v_data := v_publication.resolved_data;
  v_base := COALESCE(v_data->'base_rates','{}'::jsonb);
  v_daily := COALESCE(v_data->'daily_rates','{}'::jsonb);
  v_seasons := COALESCE(v_data->'seasonal_rates','{}'::jsonb);
  v_restrictions := COALESCE(v_data->'restrictions','{}'::jsonb);
  v_occupancy := COALESCE(v_data->'occupancy_rules','{}'::jsonb);

  IF jsonb_typeof(v_base)<>'object' OR jsonb_typeof(v_daily)<>'object'
     OR jsonb_typeof(v_seasons)<>'object' OR jsonb_typeof(v_restrictions)<>'object'
     OR jsonb_typeof(v_occupancy)<>'object' THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','Published pricing snapshot contains malformed commercial data');
  END IF;

  -- Validate applicable cumulative restrictions before calculating any amount.
  FOR v_rule IN SELECT key,value FROM jsonb_each(v_restrictions)
    WHERE value<>'null'::jsonb AND value->>'active'='true'
  LOOP
    IF NOT (v_rule.value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)) THEN
      CONTINUE;
    END IF;
    CASE v_rule.value->>'type'
      WHEN 'min_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_min_los:=GREATEST(v_min_los,(v_rule.value->>'value')::integer); END IF;
      WHEN 'max_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_max_los:=LEAST(COALESCE(v_max_los,365),(v_rule.value->>'value')::integer); END IF;
      WHEN 'closed_to_arrival' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to arrival');
        END IF;
      WHEN 'closed_to_departure' THEN
        IF _check_out BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to departure');
        END IF;
      WHEN 'stop_sell' THEN
        IF EXISTS (SELECT 1 FROM generate_series(_check_in,_check_out-1,interval '1 day') d
          WHERE d::date BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date) THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Stop sell applies to one or more stay nights');
        END IF;
      WHEN 'advance_booking_min_hours' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_hours:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/3600;
          IF v_hours < (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Minimum advance booking window not met');
          END IF;
        END IF;
      WHEN 'advance_booking_max_days' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_days:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/86400;
          IF v_days > (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Maximum advance booking window exceeded');
          END IF;
        END IF;
      ELSE
        RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Unsupported restriction type');
    END CASE;
  END LOOP;
  IF v_nights<v_min_los OR (v_max_los IS NOT NULL AND v_nights>v_max_los) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message',format('Stay length must be between %s and %s nights',v_min_los,COALESCE(v_max_los::text,'unlimited')));
  END IF;

  IF v_plan.pricing_basis='occupancy_based' THEN
    v_occupancy_key:=format('%s:%s:%s',_adults,COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0));
  END IF;

  v_day:=_check_in;
  WHILE v_day<_check_out LOOP
    v_rate:=NULL; v_source:=NULL; v_source_id:=NULL; v_source_key:=NULL;

    -- Approved overrides: exact room/date, plan+room type, room type, then plan.
    SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
    WHERE o.property_id=_property_id AND o.status='approved'
      AND o.scope='room_date' AND o.room_id=_room_id
      AND o.effective_from=v_day AND o.effective_to=v_day
    ORDER BY o.approved_at DESC,o.id LIMIT 1;
    IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
      v_source:='approved_room_date_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
    ELSE
      SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
      WHERE o.property_id=_property_id AND o.status='approved'
        AND o.scope='rate_plan_room_type' AND o.rate_plan_id=v_plan.id
        AND o.room_type_id=v_room.catalogue_type_id
        AND v_day BETWEEN o.effective_from AND o.effective_to
      ORDER BY o.approved_at DESC,o.id LIMIT 1;
      IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
        v_source:='approved_plan_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
      ELSE
        SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
        WHERE o.property_id=_property_id AND o.status='approved'
          AND o.scope='room_type' AND o.room_type_id=v_room.catalogue_type_id
          AND v_day BETWEEN o.effective_from AND o.effective_to
        ORDER BY o.approved_at DESC,o.id LIMIT 1;
        IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
          v_source:='approved_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
        ELSE
          SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
          WHERE o.property_id=_property_id AND o.status='approved'
            AND o.scope='rate_plan' AND o.rate_plan_id=v_plan.id
            AND v_day BETWEEN o.effective_from AND o.effective_to
          ORDER BY o.approved_at DESC,o.id LIMIT 1;
          IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
            v_source:='approved_plan_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Published daily rate supersedes seasonal and inherited/base rate.
    IF v_rate IS NULL THEN
      v_rate:=v_daily->v_day::text->v_room.catalogue_type_id::text;
      IF v_rate IS NOT NULL AND v_rate<>'null'::jsonb AND COALESCE((v_rate->>'active')::boolean,false) THEN
        v_source:='published_daily_rate'; v_source_key:=v_day::text;
      ELSE
        v_rate:=NULL;
      END IF;
    END IF;

    IF v_rate IS NULL THEN
      SELECT count(*) INTO v_matches
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text);
      SELECT s.key,s.value INTO v_source_key,v_rate
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
      ORDER BY (value->>'priority')::integer DESC,s.key LIMIT 1;
      IF v_matches>1 AND EXISTS (
        SELECT 1 FROM jsonb_each(v_seasons) s(key,value)
        WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
          AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
          AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
          GROUP BY (value->>'priority')::integer HAVING count(*)>1
      ) THEN
        RETURN jsonb_build_object('ok',false,'error_code','AMBIGUOUS_RATE_SOURCE',
          'message','Equal-priority seasonal rates overlap for a charged night');
      END IF;
      IF v_rate IS NOT NULL THEN v_source:='published_seasonal_rate'; END IF;
    END IF;

    IF v_rate IS NULL AND v_plan.pricing_basis='occupancy_based' THEN
      v_rate:=v_occupancy->v_room.catalogue_type_id::text->v_occupancy_key;
      IF v_rate IS NULL OR v_rate='null'::jsonb THEN
        RETURN jsonb_build_object('ok',false,'error_code','OCCUPANCY_RATE_MISSING',
          'message',format('No exact occupancy rate is published for %s',v_day));
      END IF;
      v_source:='published_occupancy_rate'; v_source_key:=v_occupancy_key;
    END IF;
    IF v_rate IS NULL AND v_plan.pricing_basis IN ('per_room','per_person') THEN
      v_rate:=v_base->v_room.catalogue_type_id::text;
      v_source:='published_base_rate'; v_source_key:=v_room.catalogue_type_id::text;
    END IF;
    IF v_rate IS NULL OR v_rate='null'::jsonb
       OR jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string' THEN
      RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
        'message',format('No valid published rate source for %s',v_day));
    END IF;
    IF v_rate->>'currency' IS DISTINCT FROM v_property_currency THEN
      RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
        'message',format('Rate currency mismatch on %s',v_day));
    END IF;
    v_rate_amount:=(v_rate->>'nightly_rate')::numeric;
    IF v_rate_amount<=0 THEN
      RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
        'message',format('Non-positive nightly rate on %s',v_day));
    END IF;
    IF v_source NOT IN ('published_occupancy_rate') THEN
      IF v_plan.pricing_basis='per_person' THEN
        v_nightly_rate:=round(v_rate_amount*v_paid_occupants,2);
      ELSE
        v_nightly_rate:=round(v_rate_amount,2);
      END IF;
    ELSE
      v_nightly_rate:=round(v_rate_amount,2);
    END IF;
    v_subtotal:=round(v_subtotal+v_nightly_rate,2);
    v_breakdown:=v_breakdown||jsonb_build_array(jsonb_build_object(
      'date',v_day,'nightly_rate',v_nightly_rate,'source_rate',v_rate_amount,'currency',v_property_currency,
      'source',v_source,'source_id',v_source_id,'source_key',v_source_key,
      'rate_plan_id',v_plan.id,'publication_id',v_publication.id,
      'publication_number',v_publication.publication_number,
      'rate_plan_version',v_publication.rate_plan_version,
      'snapshot_hash',v_publication.snapshot_hash,
      'pricing_basis',v_plan.pricing_basis,'occupancy_key',v_occupancy_key
    ));
    v_day:=v_day+1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'rate_plan_id',v_plan.id,'rate_plan_code',v_plan.code,
    'rate_plan_name',v_plan.name,'publication_id',v_publication.id,
    'publication_number',v_publication.publication_number,
    'rate_plan_version',v_publication.rate_plan_version,
    'snapshot_hash',v_publication.snapshot_hash,
    'currency',v_property_currency,'timezone',v_timezone,
    'check_in',_check_in,'check_out',_check_out,'nights',v_nights,
    'minimum_stay',v_min_los,
    'adults',_adults,'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),'occupants',v_occupants,
    'billable_occupants',v_paid_occupants,'nightly',v_breakdown,
    'accommodation_subtotal',v_subtotal
  );
EXCEPTION
  WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED','message','Pricing access denied');
  WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing data is malformed');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing resolution failed closed');
END;
$function$;

COMMIT;

-- SPE-04.07.02 — propagate explicit plan selection through shared booking contracts.
BEGIN;

CREATE OR REPLACE FUNCTION public.calculate_staynas_room_pricing(
  _property_id uuid,_room_id uuid,_check_in date,_check_out date,
  _adults integer,_children_below_6 integer DEFAULT 0,_children_7_plus integer DEFAULT 0
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public
AS $adapter$
DECLARE
  v_result jsonb;
  v_nightly jsonb;
  v_room public.rooms%ROWTYPE;
  v_rate_plan_id uuid;
BEGIN
  v_rate_plan_id := NULLIF(current_setting('staynas.rate_plan_id',true),'')::uuid;
  v_result:=public.resolve_staynas_published_room_pricing(
    _property_id,_room_id,_check_in,_check_out,_adults,
    COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0),v_rate_plan_id,now()
  );
  IF v_result->>'ok'='false' THEN RETURN v_result; END IF;
  IF v_result->>'mode'='legacy' THEN RETURN v_result->'pricing'; END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  SELECT COALESCE(jsonb_agg(
    n.value || jsonb_build_object(
      'base_rate',n.value->'source_rate','occupancy_surcharge',0,'adjustment',0,
      'applied_rule_id',NULL,'applied_rule_type',n.value->>'source'
    ) ORDER BY n.ordinality
  ),'[]'::jsonb)
  INTO v_nightly
  FROM jsonb_array_elements(v_result->'nightly') WITH ORDINALITY n(value,ordinality);

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'currency',v_result->>'currency','check_in',_check_in,'check_out',_check_out,
    'nights',(v_result->>'nights')::integer,'adults',_adults,
    'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),
    'occupants',(v_result->>'occupants')::integer,
    'paid_occupants',(v_result->>'billable_occupants')::integer,
    'extra_occupants',0,'minimum_stay',COALESCE((v_result->>'minimum_stay')::integer,1),
    'nightly',v_nightly,
    'accommodation_subtotal',(v_result->>'accommodation_subtotal')::numeric,
    'pricing_evidence',jsonb_build_object(
      'rate_plan_id',v_result->'rate_plan_id','publication_id',v_result->'publication_id',
      'publication_number',v_result->'publication_number','rate_plan_version',v_result->'rate_plan_version',
      'snapshot_hash',v_result->'snapshot_hash','timezone',v_result->'timezone'
    )
  );
END;
$adapter$;

CREATE OR REPLACE FUNCTION public.get_staynas_booking_quote_with_rate_plan(
  _property_id uuid,_room_slug text,_check_in date,_check_out date,_adults integer,
  _children_below_6 integer DEFAULT 0,_children_7_plus integer DEFAULT 0,
  _extras jsonb DEFAULT '[]'::jsonb,_rate_plan_id uuid DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public
AS $quote$
DECLARE v_room_id uuid;
BEGIN
  SELECT r.id INTO v_room_id FROM public.rooms r
  WHERE r.property_id=_property_id AND r.slug=_room_slug AND r.status='active';
  IF v_room_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error_code','ROOM_NOT_FOUND','message','Room not found for property');
  END IF;
  PERFORM set_config('staynas.rate_plan_id',COALESCE(_rate_plan_id::text,''),true);
  RETURN public.calculate_staynas_booking_quote(
    _property_id,v_room_id,_check_in,_check_out,_adults,_children_below_6,_children_7_plus,_extras
  );
END;
$quote$;

CREATE OR REPLACE FUNCTION public.get_staynas_room_availability_priced_with_rate_plan(
  _check_in date,_check_out date,_property_id uuid,_adults integer DEFAULT 1,
  _children_below_6 integer DEFAULT 0,_children_7_plus integer DEFAULT 0,
  _rate_plan_id uuid DEFAULT NULL
) RETURNS TABLE(
  room_id uuid,slug text,name text,base_price numeric,currency text,
  capacity_adults integer,capacity_children integer,max_occupancy integer,
  included_guests integer,extra_guest_fee numeric,nights integer,nightly_total numeric,
  min_available integer,is_available boolean,fits_occupancy boolean,pricing_quote jsonb
)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public
AS $availability$
BEGIN
  PERFORM set_config('staynas.rate_plan_id',COALESCE(_rate_plan_id::text,''),true);
  RETURN QUERY
  SELECT a.room_id,a.slug,a.name,a.base_price,a.currency,a.capacity_adults,a.capacity_children,
    a.max_occupancy,a.included_guests,a.extra_guest_fee,a.nights,a.nightly_total,a.min_available,
    CASE WHEN a.pricing_quote->>'error_code'='RATE_PLAN_REQUIRED'
      THEN a.min_available>0 ELSE a.is_available END AS is_available,
    a.fits_occupancy,a.pricing_quote
  FROM public.get_staynas_room_availability_priced(
    _check_in,_check_out,_property_id,_adults,_children_below_6,_children_7_plus
  ) a;
END;
$availability$;

CREATE OR REPLACE FUNCTION public.create_booking_for_property_with_rate_plan(
  _property_id uuid,_room_slug text,_check_in date,_check_out date,
  _adults integer,_children integer,_guest_name text,_guest_email text,
  _guest_phone text,_country text,_special_requests text,
  _extras jsonb DEFAULT '[]'::jsonb,_children_below_6 integer DEFAULT NULL,
  _children_7_plus integer DEFAULT NULL,_hold_id uuid DEFAULT NULL,
  _session_id text DEFAULT NULL,_payment_method text DEFAULT 'online',
  _rate_plan_id uuid DEFAULT NULL
) RETURNS TABLE(
  booking_id uuid,reference text,total numeric,currency text,
  taxes numeric,tax_addition numeric,tax_breakdown jsonb
)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public
AS $booking$
BEGIN
  PERFORM set_config('staynas.rate_plan_id',COALESCE(_rate_plan_id::text,''),true);
  RETURN QUERY SELECT * FROM public.create_booking_for_property(
    _property_id,_room_slug,_check_in,_check_out,_adults,_children,
    _guest_name,_guest_email,_guest_phone,_country,_special_requests,
    _extras,_children_below_6,_children_7_plus,_hold_id,_session_id,_payment_method
  );
END;
$booking$;

REVOKE ALL ON FUNCTION public.get_staynas_booking_quote_with_rate_plan(uuid,text,date,date,integer,integer,integer,jsonb,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.get_staynas_room_availability_priced_with_rate_plan(date,date,uuid,integer,integer,integer,uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.create_booking_for_property_with_rate_plan(uuid,text,date,date,integer,integer,text,text,text,text,text,jsonb,integer,integer,uuid,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_staynas_booking_quote_with_rate_plan(uuid,text,date,date,integer,integer,integer,jsonb,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_staynas_room_availability_priced_with_rate_plan(date,date,uuid,integer,integer,integer,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.create_booking_for_property_with_rate_plan(uuid,text,date,date,integer,integer,text,text,text,text,text,jsonb,integer,integer,uuid,text,text,uuid) TO service_role;

COMMIT;

-- SPE-04.07 authorization hardening: recognize PostgREST JWT role claim formats.
-- Keeps the existing staff/property authorization path unchanged for non-service callers.
BEGIN;

CREATE OR REPLACE FUNCTION public.resolve_staynas_published_room_pricing(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0,
  _rate_plan_id uuid DEFAULT NULL,
  _booking_timestamp timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_jwt_role text := COALESCE(NULLIF(current_setting('request.jwt.claim.role',true),''), NULLIF(current_setting('request.jwt.claims',true),'')::jsonb->>'role', auth.role());
  v_room public.rooms%ROWTYPE;
  v_property_currency text;
  v_timezone text;
  v_plan record;
  v_plan_count integer;
  v_active_plan_count integer;
  v_publication record;
  v_data jsonb;
  v_base jsonb;
  v_daily jsonb;
  v_seasons jsonb;
  v_restrictions jsonb;
  v_occupancy jsonb;
  v_occupancy_key text;
  v_rate jsonb;
  v_override record;
  v_day date;
  v_nights integer;
  v_occupants integer;
  v_paid_occupants integer;
  v_rate_amount numeric;
  v_nightly_rate numeric;
  v_subtotal numeric := 0;
  v_source text;
  v_source_id uuid;
  v_source_key text;
  v_breakdown jsonb := '[]'::jsonb;
  v_rule record;
  v_min_los integer := 1;
  v_max_los integer;
  v_local_booking timestamp;
  v_hours numeric;
  v_days numeric;
  v_matches integer;
BEGIN
  IF _property_id IS NULL OR _room_id IS NULL OR _check_in IS NULL OR _check_out IS NULL
     OR _check_out<=_check_in OR COALESCE(_adults,0)<1
     OR COALESCE(_children_below_6,0)<0 OR COALESCE(_children_7_plus,0)<0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','A valid property, room, stay and occupancy are required');
  END IF;

  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR public.staynas_active_property_id(v_uid) IS DISTINCT FROM _property_id
       OR NOT public.staynas_user_has_property_access(v_uid,_property_id)
       OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin','reservations','reception']::public.app_role[]) THEN
      RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED',
        'message','Pricing access denied for property');
    END IF;
  END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','ROOM_NOT_IN_PROPERTY',
      'message','Room is not active in the requested property');
  END IF;

  SELECT upper(p.currency),p.timezone
    INTO v_property_currency,v_timezone
  FROM public.staynas_properties p
  WHERE p.id=_property_id AND p.status='active';
  IF v_property_currency IS NULL OR v_property_currency !~ '^[A-Z]{3}$'
     OR v_timezone IS NULL OR NOT EXISTS (
       SELECT 1 FROM pg_timezone_names WHERE name=v_timezone
     ) THEN
    RETURN jsonb_build_object('ok',false,'error_code','PROPERTY_CONTEXT_INVALID',
      'message','Property currency and valid IANA timezone must be configured');
  END IF;
  IF upper(COALESCE(v_room.currency,''))<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Room currency does not match property currency');
  END IF;

  v_nights := _check_out-_check_in;
  v_occupants := _adults+_children_below_6+_children_7_plus;
  v_paid_occupants := _adults+_children_7_plus;
  IF _adults>COALESCE(v_room.capacity_adults,0)
     OR _children_below_6+_children_7_plus>COALESCE(v_room.capacity_children,0)
     OR v_occupants>COALESCE(v_room.max_occupancy,0) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message','Room occupancy capacity exceeded');
  END IF;

  SELECT count(*) INTO v_active_plan_count
  FROM public.staynas_rate_plans p
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true;

  SELECT count(*) INTO v_plan_count
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number) FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id AND pub2.rate_plan_id=pub.rate_plan_id
    );

  IF _rate_plan_id IS NOT NULL AND v_plan_count=0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Selected plan is not published, active, assigned, or effective for the complete stay');
  END IF;
  IF _rate_plan_id IS NULL AND v_plan_count>1 THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_PLAN_REQUIRED',
      'message','More than one eligible published rate plan applies; select one explicitly');
  END IF;
  IF v_plan_count=0 THEN
    IF v_active_plan_count>0 OR _rate_plan_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
        'message','Property has active published plans but none is eligible for this room and stay');
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'mode','legacy','rate_plan_id',NULL,'publication_id',NULL,
      'pricing',public.calculate_staynas_room_pricing(
        _property_id,_room_id,_check_in,_check_out,_adults,
        COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0)
      )
    );
  END IF;

  SELECT p.id,p.code,p.name,p.currency,p.pricing_basis,p.version,p.property_id
    INTO v_plan
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  WHERE p.id=COALESCE(_rate_plan_id,(
    SELECT p2.id FROM public.staynas_rate_plans p2
    JOIN public.staynas_rate_plan_room_types a2
      ON a2.property_id=p2.property_id AND a2.rate_plan_id=p2.id AND a2.active=true
    JOIN public.staynas_rate_plan_publications x
      ON x.property_id=p2.property_id AND x.rate_plan_id=p2.id
    WHERE p2.property_id=_property_id AND p2.publication_status='published' AND p2.active=true
      AND a2.room_type_id=v_room.catalogue_type_id
      AND (p2.effective_from IS NULL OR p2.effective_from<=_check_in)
      AND (p2.effective_to IS NULL OR p2.effective_to>=_check_out-1)
      AND (x.effective_from IS NULL OR x.effective_from<=_check_in)
      AND (x.effective_to IS NULL OR x.effective_to>=_check_out-1)
    ORDER BY p2.id LIMIT 1
  )) AND p.property_id=_property_id AND a.room_type_id=v_room.catalogue_type_id
  LIMIT 1;

  SELECT pub.* INTO v_publication
  FROM public.staynas_rate_plan_publications pub
  WHERE pub.property_id=_property_id AND pub.rate_plan_id=v_plan.id
  ORDER BY pub.publication_number DESC LIMIT 1;
  IF NOT FOUND OR v_publication.snapshot_hash IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
      'message','Eligible plan has no immutable publication snapshot');
  END IF;
  IF upper(v_plan.currency)<>v_property_currency
     OR upper(v_publication.currency)<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Published plan currency does not match property currency');
  END IF;

  v_data := v_publication.resolved_data;
  v_base := COALESCE(v_data->'base_rates','{}'::jsonb);
  v_daily := COALESCE(v_data->'daily_rates','{}'::jsonb);
  v_seasons := COALESCE(v_data->'seasonal_rates','{}'::jsonb);
  v_restrictions := COALESCE(v_data->'restrictions','{}'::jsonb);
  v_occupancy := COALESCE(v_data->'occupancy_rules','{}'::jsonb);

  IF jsonb_typeof(v_base)<>'object' OR jsonb_typeof(v_daily)<>'object'
     OR jsonb_typeof(v_seasons)<>'object' OR jsonb_typeof(v_restrictions)<>'object'
     OR jsonb_typeof(v_occupancy)<>'object' THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','Published pricing snapshot contains malformed commercial data');
  END IF;

  -- Validate applicable cumulative restrictions before calculating any amount.
  FOR v_rule IN SELECT key,value FROM jsonb_each(v_restrictions)
    WHERE value<>'null'::jsonb AND value->>'active'='true'
  LOOP
    IF NOT (v_rule.value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)) THEN
      CONTINUE;
    END IF;
    CASE v_rule.value->>'type'
      WHEN 'min_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_min_los:=GREATEST(v_min_los,(v_rule.value->>'value')::integer); END IF;
      WHEN 'max_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_max_los:=LEAST(COALESCE(v_max_los,365),(v_rule.value->>'value')::integer); END IF;
      WHEN 'closed_to_arrival' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to arrival');
        END IF;
      WHEN 'closed_to_departure' THEN
        IF _check_out BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to departure');
        END IF;
      WHEN 'stop_sell' THEN
        IF EXISTS (SELECT 1 FROM generate_series(_check_in,_check_out-1,interval '1 day') d
          WHERE d::date BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date) THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Stop sell applies to one or more stay nights');
        END IF;
      WHEN 'advance_booking_min_hours' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_hours:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/3600;
          IF v_hours < (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Minimum advance booking window not met');
          END IF;
        END IF;
      WHEN 'advance_booking_max_days' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_days:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/86400;
          IF v_days > (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Maximum advance booking window exceeded');
          END IF;
        END IF;
      ELSE
        RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Unsupported restriction type');
    END CASE;
  END LOOP;
  IF v_nights<v_min_los OR (v_max_los IS NOT NULL AND v_nights>v_max_los) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message',format('Stay length must be between %s and %s nights',v_min_los,COALESCE(v_max_los::text,'unlimited')));
  END IF;

  IF v_plan.pricing_basis='occupancy_based' THEN
    v_occupancy_key:=format('%s:%s:%s',_adults,COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0));
  END IF;

  v_day:=_check_in;
  WHILE v_day<_check_out LOOP
    v_rate:=NULL; v_source:=NULL; v_source_id:=NULL; v_source_key:=NULL;

    -- Approved overrides: exact room/date, plan+room type, room type, then plan.
    SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
    WHERE o.property_id=_property_id AND o.status='approved'
      AND o.scope='room_date' AND o.room_id=_room_id
      AND o.effective_from=v_day AND o.effective_to=v_day
    ORDER BY o.approved_at DESC,o.id LIMIT 1;
    IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
      v_source:='approved_room_date_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
    ELSE
      SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
      WHERE o.property_id=_property_id AND o.status='approved'
        AND o.scope='rate_plan_room_type' AND o.rate_plan_id=v_plan.id
        AND o.room_type_id=v_room.catalogue_type_id
        AND v_day BETWEEN o.effective_from AND o.effective_to
      ORDER BY o.approved_at DESC,o.id LIMIT 1;
      IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
        v_source:='approved_plan_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
      ELSE
        SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
        WHERE o.property_id=_property_id AND o.status='approved'
          AND o.scope='room_type' AND o.room_type_id=v_room.catalogue_type_id
          AND v_day BETWEEN o.effective_from AND o.effective_to
        ORDER BY o.approved_at DESC,o.id LIMIT 1;
        IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
          v_source:='approved_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
        ELSE
          SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
          WHERE o.property_id=_property_id AND o.status='approved'
            AND o.scope='rate_plan' AND o.rate_plan_id=v_plan.id
            AND v_day BETWEEN o.effective_from AND o.effective_to
          ORDER BY o.approved_at DESC,o.id LIMIT 1;
          IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
            v_source:='approved_plan_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Published daily rate supersedes seasonal and inherited/base rate.
    IF v_rate IS NULL THEN
      v_rate:=v_daily->v_day::text->v_room.catalogue_type_id::text;
      IF v_rate IS NOT NULL AND v_rate<>'null'::jsonb AND COALESCE((v_rate->>'active')::boolean,false) THEN
        v_source:='published_daily_rate'; v_source_key:=v_day::text;
      ELSE
        v_rate:=NULL;
      END IF;
    END IF;

    IF v_rate IS NULL THEN
      SELECT count(*) INTO v_matches
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text);
      SELECT s.key,s.value INTO v_source_key,v_rate
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
      ORDER BY (value->>'priority')::integer DESC,s.key LIMIT 1;
      IF v_matches>1 AND EXISTS (
        SELECT 1 FROM jsonb_each(v_seasons) s(key,value)
        WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
          AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
          AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
          GROUP BY (value->>'priority')::integer HAVING count(*)>1
      ) THEN
        RETURN jsonb_build_object('ok',false,'error_code','AMBIGUOUS_RATE_SOURCE',
          'message','Equal-priority seasonal rates overlap for a charged night');
      END IF;
      IF v_rate IS NOT NULL THEN v_source:='published_seasonal_rate'; END IF;
    END IF;

    IF v_rate IS NULL AND v_plan.pricing_basis='occupancy_based' THEN
      v_rate:=v_occupancy->v_room.catalogue_type_id::text->v_occupancy_key;
      IF v_rate IS NULL OR v_rate='null'::jsonb THEN
        RETURN jsonb_build_object('ok',false,'error_code','OCCUPANCY_RATE_MISSING',
          'message',format('No exact occupancy rate is published for %s',v_day));
      END IF;
      v_source:='published_occupancy_rate'; v_source_key:=v_occupancy_key;
    END IF;
    IF v_rate IS NULL AND v_plan.pricing_basis IN ('per_room','per_person') THEN
      v_rate:=v_base->v_room.catalogue_type_id::text;
      v_source:='published_base_rate'; v_source_key:=v_room.catalogue_type_id::text;
    END IF;
    IF v_rate IS NULL OR v_rate='null'::jsonb
       OR jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string' THEN
      RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
        'message',format('No valid published rate source for %s',v_day));
    END IF;
    IF v_rate->>'currency' IS DISTINCT FROM v_property_currency THEN
      RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
        'message',format('Rate currency mismatch on %s',v_day));
    END IF;
    v_rate_amount:=(v_rate->>'nightly_rate')::numeric;
    IF v_rate_amount<=0 THEN
      RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
        'message',format('Non-positive nightly rate on %s',v_day));
    END IF;
    IF v_source NOT IN ('published_occupancy_rate') THEN
      IF v_plan.pricing_basis='per_person' THEN
        v_nightly_rate:=round(v_rate_amount*v_paid_occupants,2);
      ELSE
        v_nightly_rate:=round(v_rate_amount,2);
      END IF;
    ELSE
      v_nightly_rate:=round(v_rate_amount,2);
    END IF;
    v_subtotal:=round(v_subtotal+v_nightly_rate,2);
    v_breakdown:=v_breakdown||jsonb_build_array(jsonb_build_object(
      'date',v_day,'nightly_rate',v_nightly_rate,'source_rate',v_rate_amount,'currency',v_property_currency,
      'source',v_source,'source_id',v_source_id,'source_key',v_source_key,
      'rate_plan_id',v_plan.id,'publication_id',v_publication.id,
      'publication_number',v_publication.publication_number,
      'rate_plan_version',v_publication.rate_plan_version,
      'snapshot_hash',v_publication.snapshot_hash,
      'pricing_basis',v_plan.pricing_basis,'occupancy_key',v_occupancy_key
    ));
    v_day:=v_day+1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'rate_plan_id',v_plan.id,'rate_plan_code',v_plan.code,
    'rate_plan_name',v_plan.name,'publication_id',v_publication.id,
    'publication_number',v_publication.publication_number,
    'rate_plan_version',v_publication.rate_plan_version,
    'snapshot_hash',v_publication.snapshot_hash,
    'currency',v_property_currency,'timezone',v_timezone,
    'check_in',_check_in,'check_out',_check_out,'nights',v_nights,
    'minimum_stay',v_min_los,
    'adults',_adults,'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),'occupants',v_occupants,
    'billable_occupants',v_paid_occupants,'nightly',v_breakdown,
    'accommodation_subtotal',v_subtotal
  );
EXCEPTION
  WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED','message','Pricing access denied');
  WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing data is malformed');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing resolution failed closed');
END;
$function$;

COMMIT;

DO $patch$
DECLARE
  v_definition text;
  v_old text;
  v_new text;
BEGIN
  v_definition := pg_get_functiondef(
    'public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamp with time zone)'::regprocedure
  );

  v_old := '  v_uid uuid := auth.uid();';
  v_new := v_old || E'\n  v_publication_rate_plan_id uuid;';
  IF position(v_old in v_definition) = 0 THEN
    RAISE EXCEPTION 'SPE-04.07 patch precondition failed: declaration anchor missing';
  END IF;
  v_definition := replace(v_definition, v_old, v_new);

  v_old := '  IF v_jwt_role IS DISTINCT FROM ''service_role'' THEN';
  v_new := E'  -- Public plan discovery returns a publication identifier in some client paths.\n' ||
    E'  -- Accept either the canonical rate_plan_id or its publication id, scoped to this property.\n' ||
    E'  IF _rate_plan_id IS NOT NULL AND NOT EXISTS (\n' ||
    E'    SELECT 1 FROM public.staynas_rate_plans p\n' ||
    E'    WHERE p.id = _rate_plan_id AND p.property_id = _property_id\n' ||
    E'  ) THEN\n' ||
    E'    SELECT pub.rate_plan_id INTO v_publication_rate_plan_id\n' ||
    E'    FROM public.staynas_rate_plan_publications pub\n' ||
    E'    WHERE pub.id = _rate_plan_id AND pub.property_id = _property_id\n' ||
    E'    ORDER BY pub.publication_number DESC LIMIT 1;\n' ||
    E'    IF FOUND THEN _rate_plan_id := v_publication_rate_plan_id; END IF;\n' ||
    E'  END IF;\n\n' || v_old;
  IF position(v_old in v_definition) = 0 THEN
    RAISE EXCEPTION 'SPE-04.07 patch precondition failed: authorization anchor missing';
  END IF;
  v_definition := replace(v_definition, v_old, v_new);

  EXECUTE v_definition;
END
$patch$;

-- SPE-04.08: pin plan selection to the single eligible latest publication candidate.
-- Feature branch only. Existing quote/availability/booking RPCs are not rerouted here.
BEGIN;

CREATE OR REPLACE FUNCTION public.resolve_staynas_published_room_pricing(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0,
  _rate_plan_id uuid DEFAULT NULL,
  _booking_timestamp timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role',true);
  v_room public.rooms%ROWTYPE;
  v_property_currency text;
  v_timezone text;
  v_plan record;
  v_plan_count integer;
  v_active_plan_count integer;
  v_publication record;
  v_data jsonb;
  v_base jsonb;
  v_daily jsonb;
  v_seasons jsonb;
  v_restrictions jsonb;
  v_occupancy jsonb;
  v_occupancy_key text;
  v_rate jsonb;
  v_override record;
  v_day date;
  v_nights integer;
  v_occupants integer;
  v_paid_occupants integer;
  v_rate_amount numeric;
  v_nightly_rate numeric;
  v_subtotal numeric := 0;
  v_source text;
  v_source_id uuid;
  v_source_key text;
  v_breakdown jsonb := '[]'::jsonb;
  v_rule record;
  v_min_los integer := 1;
  v_max_los integer;
  v_local_booking timestamp;
  v_hours numeric;
  v_days numeric;
  v_matches integer;
BEGIN
  IF _property_id IS NULL OR _room_id IS NULL OR _check_in IS NULL OR _check_out IS NULL
     OR _check_out<=_check_in OR COALESCE(_adults,0)<1
     OR COALESCE(_children_below_6,0)<0 OR COALESCE(_children_7_plus,0)<0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','A valid property, room, stay and occupancy are required');
  END IF;

  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR public.staynas_active_property_id(v_uid) IS DISTINCT FROM _property_id
       OR NOT public.staynas_user_has_property_access(v_uid,_property_id)
       OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin','reservations','reception']::public.app_role[]) THEN
      RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED',
        'message','Pricing access denied for property');
    END IF;
  END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','ROOM_NOT_IN_PROPERTY',
      'message','Room is not active in the requested property');
  END IF;

  SELECT upper(p.currency),p.timezone
    INTO v_property_currency,v_timezone
  FROM public.staynas_properties p
  WHERE p.id=_property_id AND p.status='active';
  IF v_property_currency IS NULL OR v_property_currency !~ '^[A-Z]{3}$'
     OR v_timezone IS NULL OR NOT EXISTS (
       SELECT 1 FROM pg_timezone_names WHERE name=v_timezone
     ) THEN
    RETURN jsonb_build_object('ok',false,'error_code','PROPERTY_CONTEXT_INVALID',
      'message','Property currency and valid IANA timezone must be configured');
  END IF;
  IF upper(COALESCE(v_room.currency,''))<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Room currency does not match property currency');
  END IF;

  v_nights := _check_out-_check_in;
  v_occupants := _adults+_children_below_6+_children_7_plus;
  v_paid_occupants := _adults+_children_7_plus;
  IF _adults>COALESCE(v_room.capacity_adults,0)
     OR _children_below_6+_children_7_plus>COALESCE(v_room.capacity_children,0)
     OR v_occupants>COALESCE(v_room.max_occupancy,0) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message','Room occupancy capacity exceeded');
  END IF;

  SELECT count(*) INTO v_active_plan_count
  FROM public.staynas_rate_plans p
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true;

  SELECT count(*) INTO v_plan_count
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number) FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id AND pub2.rate_plan_id=pub.rate_plan_id
    );

  IF _rate_plan_id IS NOT NULL AND v_plan_count=0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Selected plan is not published, active, assigned, or effective for the complete stay');
  END IF;
  IF _rate_plan_id IS NULL AND v_plan_count>1 THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_PLAN_REQUIRED',
      'message','More than one eligible published rate plan applies; select one explicitly');
  END IF;
  IF v_plan_count=0 THEN
    IF v_active_plan_count>0 OR _rate_plan_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
        'message','Property has active published plans but none is eligible for this room and stay');
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'mode','legacy','rate_plan_id',NULL,'publication_id',NULL,
      'pricing',public.calculate_staynas_room_pricing(
        _property_id,_room_id,_check_in,_check_out,_adults,
        COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0)
      )
    );
  END IF;

  -- v_plan_count has already enforced exactly one eligible candidate for
  -- implicit selection, or exactly one matching candidate for an explicit ID.
  -- Select from that same latest-publication candidate set; never order by UUID.
  SELECT p.id,p.code,p.name,p.currency,p.pricing_basis,p.version,p.property_id
    INTO v_plan
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id
    AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number)
      FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id
        AND pub2.rate_plan_id=pub.rate_plan_id
    )
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Eligible rate plan and latest publication could not be resolved consistently');
  END IF;

  SELECT pub.* INTO v_publication
  FROM public.staynas_rate_plan_publications pub
  WHERE pub.property_id=_property_id AND pub.rate_plan_id=v_plan.id
  ORDER BY pub.publication_number DESC LIMIT 1;
  IF NOT FOUND OR v_publication.snapshot_hash IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
      'message','Eligible plan has no immutable publication snapshot');
  END IF;
  IF upper(v_plan.currency)<>v_property_currency
     OR upper(v_publication.currency)<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Published plan currency does not match property currency');
  END IF;

  v_data := v_publication.resolved_data;
  v_base := COALESCE(v_data->'base_rates','{}'::jsonb);
  v_daily := COALESCE(v_data->'daily_rates','{}'::jsonb);
  v_seasons := COALESCE(v_data->'seasonal_rates','{}'::jsonb);
  v_restrictions := COALESCE(v_data->'restrictions','{}'::jsonb);
  v_occupancy := COALESCE(v_data->'occupancy_rules','{}'::jsonb);

  IF jsonb_typeof(v_base)<>'object' OR jsonb_typeof(v_daily)<>'object'
     OR jsonb_typeof(v_seasons)<>'object' OR jsonb_typeof(v_restrictions)<>'object'
     OR jsonb_typeof(v_occupancy)<>'object' THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','Published pricing snapshot contains malformed commercial data');
  END IF;

  -- Validate applicable cumulative restrictions before calculating any amount.
  FOR v_rule IN SELECT key,value FROM jsonb_each(v_restrictions)
    WHERE value<>'null'::jsonb AND value->>'active'='true'
  LOOP
    IF NOT (v_rule.value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)) THEN
      CONTINUE;
    END IF;
    CASE v_rule.value->>'type'
      WHEN 'min_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_min_los:=GREATEST(v_min_los,(v_rule.value->>'value')::integer); END IF;
      WHEN 'max_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_max_los:=LEAST(COALESCE(v_max_los,365),(v_rule.value->>'value')::integer); END IF;
      WHEN 'closed_to_arrival' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to arrival');
        END IF;
      WHEN 'closed_to_departure' THEN
        IF _check_out BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to departure');
        END IF;
      WHEN 'stop_sell' THEN
        IF EXISTS (SELECT 1 FROM generate_series(_check_in,_check_out-1,interval '1 day') d
          WHERE d::date BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date) THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Stop sell applies to one or more stay nights');
        END IF;
      WHEN 'advance_booking_min_hours' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_hours:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/3600;
          IF v_hours < (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Minimum advance booking window not met');
          END IF;
        END IF;
      WHEN 'advance_booking_max_days' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_days:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/86400;
          IF v_days > (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Maximum advance booking window exceeded');
          END IF;
        END IF;
      ELSE
        RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Unsupported restriction type');
    END CASE;
  END LOOP;
  IF v_nights<v_min_los OR (v_max_los IS NOT NULL AND v_nights>v_max_los) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message',format('Stay length must be between %s and %s nights',v_min_los,COALESCE(v_max_los::text,'unlimited')));
  END IF;

  IF v_plan.pricing_basis='occupancy_based' THEN
    v_occupancy_key:=format('%s:%s:%s',_adults,COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0));
  END IF;

  v_day:=_check_in;
  WHILE v_day<_check_out LOOP
    v_rate:=NULL; v_source:=NULL; v_source_id:=NULL; v_source_key:=NULL;

    -- Approved overrides: exact room/date, plan+room type, room type, then plan.
    SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
    WHERE o.property_id=_property_id AND o.status='approved'
      AND o.scope='room_date' AND o.room_id=_room_id
      AND o.effective_from=v_day AND o.effective_to=v_day
    ORDER BY o.approved_at DESC,o.id LIMIT 1;
    IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
      v_source:='approved_room_date_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
    ELSE
      SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
      WHERE o.property_id=_property_id AND o.status='approved'
        AND o.scope='rate_plan_room_type' AND o.rate_plan_id=v_plan.id
        AND o.room_type_id=v_room.catalogue_type_id
        AND v_day BETWEEN o.effective_from AND o.effective_to
      ORDER BY o.approved_at DESC,o.id LIMIT 1;
      IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
        v_source:='approved_plan_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
      ELSE
        SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
        WHERE o.property_id=_property_id AND o.status='approved'
          AND o.scope='room_type' AND o.room_type_id=v_room.catalogue_type_id
          AND v_day BETWEEN o.effective_from AND o.effective_to
        ORDER BY o.approved_at DESC,o.id LIMIT 1;
        IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
          v_source:='approved_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
        ELSE
          SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
          WHERE o.property_id=_property_id AND o.status='approved'
            AND o.scope='rate_plan' AND o.rate_plan_id=v_plan.id
            AND v_day BETWEEN o.effective_from AND o.effective_to
          ORDER BY o.approved_at DESC,o.id LIMIT 1;
          IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
            v_source:='approved_plan_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Published daily rate supersedes seasonal and inherited/base rate.
    IF v_rate IS NULL THEN
      v_rate:=v_daily->v_day::text->v_room.catalogue_type_id::text;
      IF v_rate IS NOT NULL AND v_rate<>'null'::jsonb AND COALESCE((v_rate->>'active')::boolean,false) THEN
        v_source:='published_daily_rate'; v_source_key:=v_day::text;
      ELSE
        v_rate:=NULL;
      END IF;
    END IF;

    IF v_rate IS NULL THEN
      SELECT count(*) INTO v_matches
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text);
      SELECT s.key,s.value INTO v_source_key,v_rate
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
      ORDER BY (value->>'priority')::integer DESC,s.key LIMIT 1;
      IF v_matches>1 AND EXISTS (
        SELECT 1 FROM jsonb_each(v_seasons) s(key,value)
        WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
          AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
          AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
          GROUP BY (value->>'priority')::integer HAVING count(*)>1
      ) THEN
        RETURN jsonb_build_object('ok',false,'error_code','AMBIGUOUS_RATE_SOURCE',
          'message','Equal-priority seasonal rates overlap for a charged night');
      END IF;
      IF v_rate IS NOT NULL THEN v_source:='published_seasonal_rate'; END IF;
    END IF;

    IF v_rate IS NULL AND v_plan.pricing_basis='occupancy_based' THEN
      v_rate:=v_occupancy->v_room.catalogue_type_id::text->v_occupancy_key;
      IF v_rate IS NULL OR v_rate='null'::jsonb THEN
        RETURN jsonb_build_object('ok',false,'error_code','OCCUPANCY_RATE_MISSING',
          'message',format('No exact occupancy rate is published for %s',v_day));
      END IF;
      v_source:='published_occupancy_rate'; v_source_key:=v_occupancy_key;
    END IF;
    IF v_rate IS NULL AND v_plan.pricing_basis IN ('per_room','per_person') THEN
      v_rate:=v_base->v_room.catalogue_type_id::text;
      v_source:='published_base_rate'; v_source_key:=v_room.catalogue_type_id::text;
    END IF;
    IF v_rate IS NULL OR v_rate='null'::jsonb
       OR jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string' THEN
      RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
        'message',format('No valid published rate source for %s',v_day));
    END IF;
    IF v_rate->>'currency' IS DISTINCT FROM v_property_currency THEN
      RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
        'message',format('Rate currency mismatch on %s',v_day));
    END IF;
    v_rate_amount:=(v_rate->>'nightly_rate')::numeric;
    IF v_rate_amount<=0 THEN
      RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
        'message',format('Non-positive nightly rate on %s',v_day));
    END IF;
    IF v_source NOT IN ('published_occupancy_rate') THEN
      IF v_plan.pricing_basis='per_person' THEN
        v_nightly_rate:=round(v_rate_amount*v_paid_occupants,2);
      ELSE
        v_nightly_rate:=round(v_rate_amount,2);
      END IF;
    ELSE
      v_nightly_rate:=round(v_rate_amount,2);
    END IF;
    v_subtotal:=round(v_subtotal+v_nightly_rate,2);
    v_breakdown:=v_breakdown||jsonb_build_array(jsonb_build_object(
      'date',v_day,'nightly_rate',v_nightly_rate,'source_rate',v_rate_amount,'currency',v_property_currency,
      'source',v_source,'source_id',v_source_id,'source_key',v_source_key,
      'rate_plan_id',v_plan.id,'publication_id',v_publication.id,
      'publication_number',v_publication.publication_number,
      'rate_plan_version',v_publication.rate_plan_version,
      'snapshot_hash',v_publication.snapshot_hash,
      'pricing_basis',v_plan.pricing_basis,'occupancy_key',v_occupancy_key
    ));
    v_day:=v_day+1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'rate_plan_id',v_plan.id,'rate_plan_code',v_plan.code,
    'rate_plan_name',v_plan.name,'publication_id',v_publication.id,
    'publication_number',v_publication.publication_number,
    'rate_plan_version',v_publication.rate_plan_version,
    'snapshot_hash',v_publication.snapshot_hash,
    'currency',v_property_currency,'timezone',v_timezone,
    'check_in',_check_in,'check_out',_check_out,'nights',v_nights,
    'minimum_stay',v_min_los,
    'adults',_adults,'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),'occupants',v_occupants,
    'billable_occupants',v_paid_occupants,'nightly',v_breakdown,
    'accommodation_subtotal',v_subtotal
  );
EXCEPTION
  WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED','message','Pricing access denied');
  WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing data is malformed');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing resolution failed closed');
END;
$function$;

REVOKE ALL ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz)
  TO authenticated,service_role;

COMMENT ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz) IS
  'SPE-04 database-authoritative published-plan accommodation resolver. Reads latest immutable publication snapshot; returns nightly source evidence and structured fail-closed outcomes. Does not mutate inventory or bookings.';

COMMIT;

-- SPE-04.08: pin plan selection to the single eligible latest publication candidate.
-- Feature branch only. Existing quote/availability/booking RPCs are not rerouted here.
BEGIN;

CREATE OR REPLACE FUNCTION public.resolve_staynas_published_room_pricing(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0,
  _rate_plan_id uuid DEFAULT NULL,
  _booking_timestamp timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role',true);
  v_room public.rooms%ROWTYPE;
  v_property_currency text;
  v_timezone text;
  v_plan record;
  v_plan_count integer;
  v_active_plan_count integer;
  v_publication record;
  v_data jsonb;
  v_base jsonb;
  v_daily jsonb;
  v_seasons jsonb;
  v_restrictions jsonb;
  v_occupancy jsonb;
  v_occupancy_key text;
  v_rate jsonb;
  v_override record;
  v_day date;
  v_nights integer;
  v_occupants integer;
  v_paid_occupants integer;
  v_rate_amount numeric;
  v_nightly_rate numeric;
  v_subtotal numeric := 0;
  v_source text;
  v_source_id uuid;
  v_source_key text;
  v_breakdown jsonb := '[]'::jsonb;
  v_rule record;
  v_min_los integer := 1;
  v_max_los integer;
  v_local_booking timestamp;
  v_hours numeric;
  v_days numeric;
  v_matches integer;
BEGIN
  IF _property_id IS NULL OR _room_id IS NULL OR _check_in IS NULL OR _check_out IS NULL
     OR _check_out<=_check_in OR COALESCE(_adults,0)<1
     OR COALESCE(_children_below_6,0)<0 OR COALESCE(_children_7_plus,0)<0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','A valid property, room, stay and occupancy are required');
  END IF;

  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR public.staynas_active_property_id(v_uid) IS DISTINCT FROM _property_id
       OR NOT public.staynas_user_has_property_access(v_uid,_property_id)
       OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin','reservations','reception']::public.app_role[]) THEN
      RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED',
        'message','Pricing access denied for property');
    END IF;
  END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','ROOM_NOT_IN_PROPERTY',
      'message','Room is not active in the requested property');
  END IF;

  SELECT upper(p.currency),p.timezone
    INTO v_property_currency,v_timezone
  FROM public.staynas_properties p
  WHERE p.id=_property_id AND p.status='active';
  IF v_property_currency IS NULL OR v_property_currency !~ '^[A-Z]{3}$'
     OR v_timezone IS NULL OR NOT EXISTS (
       SELECT 1 FROM pg_timezone_names WHERE name=v_timezone
     ) THEN
    RETURN jsonb_build_object('ok',false,'error_code','PROPERTY_CONTEXT_INVALID',
      'message','Property currency and valid IANA timezone must be configured');
  END IF;
  IF upper(COALESCE(v_room.currency,''))<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Room currency does not match property currency');
  END IF;

  v_nights := _check_out-_check_in;
  v_occupants := _adults+_children_below_6+_children_7_plus;
  v_paid_occupants := _adults+_children_7_plus;
  IF _adults>COALESCE(v_room.capacity_adults,0)
     OR _children_below_6+_children_7_plus>COALESCE(v_room.capacity_children,0)
     OR v_occupants>COALESCE(v_room.max_occupancy,0) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message','Room occupancy capacity exceeded');
  END IF;

  SELECT count(*) INTO v_active_plan_count
  FROM public.staynas_rate_plans p
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true;

  SELECT count(*) INTO v_plan_count
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number) FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id AND pub2.rate_plan_id=pub.rate_plan_id
    );

  IF _rate_plan_id IS NOT NULL AND v_plan_count=0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Selected plan is not published, active, assigned, or effective for the complete stay');
  END IF;
  IF _rate_plan_id IS NULL AND v_plan_count>1 THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_PLAN_REQUIRED',
      'message','More than one eligible published rate plan applies; select one explicitly');
  END IF;
  IF v_plan_count=0 THEN
    IF v_active_plan_count>0 OR _rate_plan_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
        'message','Property has active published plans but none is eligible for this room and stay');
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'mode','legacy','rate_plan_id',NULL,'publication_id',NULL,
      'pricing',public.calculate_staynas_room_pricing(
        _property_id,_room_id,_check_in,_check_out,_adults,
        COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0)
      )
    );
  END IF;

  -- v_plan_count has already enforced exactly one eligible candidate for
  -- implicit selection, or exactly one matching candidate for an explicit ID.
  -- Select from that same latest-publication candidate set; never order by UUID.
  SELECT p.id,p.code,p.name,p.currency,p.pricing_basis,p.version,p.property_id
    INTO v_plan
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id
    AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number)
      FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id
        AND pub2.rate_plan_id=pub.rate_plan_id
    )
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Eligible rate plan and latest publication could not be resolved consistently');
  END IF;

  SELECT pub.* INTO v_publication
  FROM public.staynas_rate_plan_publications pub
  WHERE pub.property_id=_property_id AND pub.rate_plan_id=v_plan.id
  ORDER BY pub.publication_number DESC LIMIT 1;
  IF NOT FOUND OR v_publication.snapshot_hash IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
      'message','Eligible plan has no immutable publication snapshot');
  END IF;
  IF upper(v_plan.currency)<>v_property_currency
     OR upper(v_publication.currency)<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Published plan currency does not match property currency');
  END IF;

  v_data := v_publication.resolved_data;
  v_base := COALESCE(v_data->'base_rates','{}'::jsonb);
  v_daily := COALESCE(v_data->'daily_rates','{}'::jsonb);
  v_seasons := COALESCE(v_data->'seasonal_rates','{}'::jsonb);
  v_restrictions := COALESCE(v_data->'restrictions','{}'::jsonb);
  v_occupancy := COALESCE(v_data->'occupancy_rules','{}'::jsonb);

  IF jsonb_typeof(v_base)<>'object' OR jsonb_typeof(v_daily)<>'object'
     OR jsonb_typeof(v_seasons)<>'object' OR jsonb_typeof(v_restrictions)<>'object'
     OR jsonb_typeof(v_occupancy)<>'object' THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','Published pricing snapshot contains malformed commercial data');
  END IF;

  -- Validate applicable cumulative restrictions before calculating any amount.
  FOR v_rule IN SELECT key,value FROM jsonb_each(v_restrictions)
    WHERE value<>'null'::jsonb AND value->>'active'='true'
  LOOP
    IF NOT (v_rule.value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)) THEN
      CONTINUE;
    END IF;
    CASE v_rule.value->>'type'
      WHEN 'min_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_min_los:=GREATEST(v_min_los,(v_rule.value->>'value')::integer); END IF;
      WHEN 'max_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_max_los:=LEAST(COALESCE(v_max_los,365),(v_rule.value->>'value')::integer); END IF;
      WHEN 'closed_to_arrival' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to arrival');
        END IF;
      WHEN 'closed_to_departure' THEN
        IF _check_out BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to departure');
        END IF;
      WHEN 'stop_sell' THEN
        IF EXISTS (SELECT 1 FROM generate_series(_check_in,_check_out-1,interval '1 day') d
          WHERE d::date BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date) THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Stop sell applies to one or more stay nights');
        END IF;
      WHEN 'advance_booking_min_hours' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_hours:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/3600;
          IF v_hours < (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Minimum advance booking window not met');
          END IF;
        END IF;
      WHEN 'advance_booking_max_days' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_days:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/86400;
          IF v_days > (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Maximum advance booking window exceeded');
          END IF;
        END IF;
      ELSE
        RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Unsupported restriction type');
    END CASE;
  END LOOP;
  IF v_nights<v_min_los OR (v_max_los IS NOT NULL AND v_nights>v_max_los) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message',format('Stay length must be between %s and %s nights',v_min_los,COALESCE(v_max_los::text,'unlimited')));
  END IF;

  IF v_plan.pricing_basis='occupancy_based' THEN
    v_occupancy_key:=format('%s:%s:%s',_adults,COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0));
  END IF;

  v_day:=_check_in;
  WHILE v_day<_check_out LOOP
    v_rate:=NULL; v_source:=NULL; v_source_id:=NULL; v_source_key:=NULL;

    -- Approved overrides: exact room/date, plan+room type, room type, then plan.
    SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
    WHERE o.property_id=_property_id AND o.status='approved'
      AND o.scope='room_date' AND o.room_id=_room_id
      AND o.effective_from=v_day AND o.effective_to=v_day
    ORDER BY o.approved_at DESC,o.id LIMIT 1;
    IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
      v_source:='approved_room_date_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
    ELSE
      SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
      WHERE o.property_id=_property_id AND o.status='approved'
        AND o.scope='rate_plan_room_type' AND o.rate_plan_id=v_plan.id
        AND o.room_type_id=v_room.catalogue_type_id
        AND v_day BETWEEN o.effective_from AND o.effective_to
      ORDER BY o.approved_at DESC,o.id LIMIT 1;
      IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
        v_source:='approved_plan_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
      ELSE
        SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
        WHERE o.property_id=_property_id AND o.status='approved'
          AND o.scope='room_type' AND o.room_type_id=v_room.catalogue_type_id
          AND v_day BETWEEN o.effective_from AND o.effective_to
        ORDER BY o.approved_at DESC,o.id LIMIT 1;
        IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
          v_source:='approved_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
        ELSE
          SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
          WHERE o.property_id=_property_id AND o.status='approved'
            AND o.scope='rate_plan' AND o.rate_plan_id=v_plan.id
            AND v_day BETWEEN o.effective_from AND o.effective_to
          ORDER BY o.approved_at DESC,o.id LIMIT 1;
          IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
            v_source:='approved_plan_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Published daily rate supersedes seasonal and inherited/base rate.
    IF v_rate IS NULL THEN
      v_rate:=v_daily->v_day::text->v_room.catalogue_type_id::text;
      IF v_rate IS NOT NULL AND v_rate<>'null'::jsonb AND COALESCE((v_rate->>'active')::boolean,false) THEN
        v_source:='published_daily_rate'; v_source_key:=v_day::text;
      ELSE
        v_rate:=NULL;
      END IF;
    END IF;

    IF v_rate IS NULL THEN
      SELECT count(*) INTO v_matches
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text);
      SELECT s.key,s.value INTO v_source_key,v_rate
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
      ORDER BY (value->>'priority')::integer DESC,s.key LIMIT 1;
      IF v_matches>1 AND EXISTS (
        SELECT 1 FROM jsonb_each(v_seasons) s(key,value)
        WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
          AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
          AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
          GROUP BY (value->>'priority')::integer HAVING count(*)>1
      ) THEN
        RETURN jsonb_build_object('ok',false,'error_code','AMBIGUOUS_RATE_SOURCE',
          'message','Equal-priority seasonal rates overlap for a charged night');
      END IF;
      IF v_rate IS NOT NULL THEN v_source:='published_seasonal_rate'; END IF;
    END IF;

    IF v_rate IS NULL AND v_plan.pricing_basis='occupancy_based' THEN
      v_rate:=v_occupancy->v_room.catalogue_type_id::text->v_occupancy_key;
      IF v_rate IS NULL OR v_rate='null'::jsonb THEN
        RETURN jsonb_build_object('ok',false,'error_code','OCCUPANCY_RATE_MISSING',
          'message',format('No exact occupancy rate is published for %s',v_day));
      END IF;
      v_source:='published_occupancy_rate'; v_source_key:=v_occupancy_key;
    END IF;
    IF v_rate IS NULL AND v_plan.pricing_basis IN ('per_room','per_person') THEN
      v_rate:=v_base->v_room.catalogue_type_id::text;
      v_source:='published_base_rate'; v_source_key:=v_room.catalogue_type_id::text;
    END IF;
    IF v_rate IS NULL OR v_rate='null'::jsonb
       OR jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string' THEN
      RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
        'message',format('No valid published rate source for %s',v_day));
    END IF;
    IF v_rate->>'currency' IS DISTINCT FROM v_property_currency THEN
      RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
        'message',format('Rate currency mismatch on %s',v_day));
    END IF;
    v_rate_amount:=(v_rate->>'nightly_rate')::numeric;
    IF v_rate_amount<=0 THEN
      RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
        'message',format('Non-positive nightly rate on %s',v_day));
    END IF;
    IF v_source NOT IN ('published_occupancy_rate') THEN
      IF v_plan.pricing_basis='per_person' THEN
        v_nightly_rate:=round(v_rate_amount*v_paid_occupants,2);
      ELSE
        v_nightly_rate:=round(v_rate_amount,2);
      END IF;
    ELSE
      v_nightly_rate:=round(v_rate_amount,2);
    END IF;
    v_subtotal:=round(v_subtotal+v_nightly_rate,2);
    v_breakdown:=v_breakdown||jsonb_build_array(jsonb_build_object(
      'date',v_day,'nightly_rate',v_nightly_rate,'source_rate',v_rate_amount,'currency',v_property_currency,
      'source',v_source,'source_id',v_source_id,'source_key',v_source_key,
      'rate_plan_id',v_plan.id,'publication_id',v_publication.id,
      'publication_number',v_publication.publication_number,
      'rate_plan_version',v_publication.rate_plan_version,
      'snapshot_hash',v_publication.snapshot_hash,
      'pricing_basis',v_plan.pricing_basis,'occupancy_key',v_occupancy_key
    ));
    v_day:=v_day+1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'rate_plan_id',v_plan.id,'rate_plan_code',v_plan.code,
    'rate_plan_name',v_plan.name,'publication_id',v_publication.id,
    'publication_number',v_publication.publication_number,
    'rate_plan_version',v_publication.rate_plan_version,
    'snapshot_hash',v_publication.snapshot_hash,
    'currency',v_property_currency,'timezone',v_timezone,
    'check_in',_check_in,'check_out',_check_out,'nights',v_nights,
    'minimum_stay',v_min_los,
    'adults',_adults,'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),'occupants',v_occupants,
    'billable_occupants',v_paid_occupants,'nightly',v_breakdown,
    'accommodation_subtotal',v_subtotal
  );
EXCEPTION
  WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED','message','Pricing access denied');
  WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing data is malformed');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing resolution failed closed');
END;
$function$;

REVOKE ALL ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz)
  TO authenticated,service_role;

COMMENT ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz) IS
  'SPE-04 database-authoritative published-plan accommodation resolver. Reads latest immutable publication snapshot; returns nightly source evidence and structured fail-closed outcomes. Does not mutate inventory or bookings.';

COMMIT;

-- SPE-04.10 — break recursive legacy fallback and keep resolver boundary canonical.
-- The published resolver must call the legacy-only calculator directly when
-- (and only when) a property has no active published plans. Calling the shared
-- adapter here would recurse back into the resolver.
-- SPE-04.08: pin plan selection to the single eligible latest publication candidate.
-- Feature branch only. Existing quote/availability/booking RPCs are not rerouted here.
BEGIN;

CREATE OR REPLACE FUNCTION public.resolve_staynas_published_room_pricing(
  _property_id uuid,
  _room_id uuid,
  _check_in date,
  _check_out date,
  _adults integer,
  _children_below_6 integer DEFAULT 0,
  _children_7_plus integer DEFAULT 0,
  _rate_plan_id uuid DEFAULT NULL,
  _booking_timestamp timestamptz DEFAULT now()
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path=public
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_jwt_role text := current_setting('request.jwt.claim.role',true);
  v_room public.rooms%ROWTYPE;
  v_property_currency text;
  v_timezone text;
  v_plan record;
  v_plan_count integer;
  v_active_plan_count integer;
  v_publication record;
  v_data jsonb;
  v_base jsonb;
  v_daily jsonb;
  v_seasons jsonb;
  v_restrictions jsonb;
  v_occupancy jsonb;
  v_occupancy_key text;
  v_rate jsonb;
  v_override record;
  v_day date;
  v_nights integer;
  v_occupants integer;
  v_paid_occupants integer;
  v_rate_amount numeric;
  v_nightly_rate numeric;
  v_subtotal numeric := 0;
  v_source text;
  v_source_id uuid;
  v_source_key text;
  v_breakdown jsonb := '[]'::jsonb;
  v_rule record;
  v_min_los integer := 1;
  v_max_los integer;
  v_local_booking timestamp;
  v_hours numeric;
  v_days numeric;
  v_matches integer;
BEGIN
  IF _property_id IS NULL OR _room_id IS NULL OR _check_in IS NULL OR _check_out IS NULL
     OR _check_out<=_check_in OR COALESCE(_adults,0)<1
     OR COALESCE(_children_below_6,0)<0 OR COALESCE(_children_7_plus,0)<0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','A valid property, room, stay and occupancy are required');
  END IF;

  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    IF v_uid IS NULL
       OR public.staynas_active_property_id(v_uid) IS DISTINCT FROM _property_id
       OR NOT public.staynas_user_has_property_access(v_uid,_property_id)
       OR NOT public.has_any_role(v_uid,ARRAY['owner','manager','finance','admin','reservations','reception']::public.app_role[]) THEN
      RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED',
        'message','Pricing access denied for property');
    END IF;
  END IF;

  SELECT * INTO v_room FROM public.rooms r
  WHERE r.id=_room_id AND r.property_id=_property_id AND r.status='active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','ROOM_NOT_IN_PROPERTY',
      'message','Room is not active in the requested property');
  END IF;

  SELECT upper(p.currency),p.timezone
    INTO v_property_currency,v_timezone
  FROM public.staynas_properties p
  WHERE p.id=_property_id AND p.status='active';
  IF v_property_currency IS NULL OR v_property_currency !~ '^[A-Z]{3}$'
     OR v_timezone IS NULL OR NOT EXISTS (
       SELECT 1 FROM pg_timezone_names WHERE name=v_timezone
     ) THEN
    RETURN jsonb_build_object('ok',false,'error_code','PROPERTY_CONTEXT_INVALID',
      'message','Property currency and valid IANA timezone must be configured');
  END IF;
  IF upper(COALESCE(v_room.currency,''))<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Room currency does not match property currency');
  END IF;

  v_nights := _check_out-_check_in;
  v_occupants := _adults+_children_below_6+_children_7_plus;
  v_paid_occupants := _adults+_children_7_plus;
  IF _adults>COALESCE(v_room.capacity_adults,0)
     OR _children_below_6+_children_7_plus>COALESCE(v_room.capacity_children,0)
     OR v_occupants>COALESCE(v_room.max_occupancy,0) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message','Room occupancy capacity exceeded');
  END IF;

  SELECT count(*) INTO v_active_plan_count
  FROM public.staynas_rate_plans p
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true;

  SELECT count(*) INTO v_plan_count
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number) FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id AND pub2.rate_plan_id=pub.rate_plan_id
    );

  IF _rate_plan_id IS NOT NULL AND v_plan_count=0 THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Selected plan is not published, active, assigned, or effective for the complete stay');
  END IF;
  IF _rate_plan_id IS NULL AND v_plan_count>1 THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_PLAN_REQUIRED',
      'message','More than one eligible published rate plan applies; select one explicitly');
  END IF;
  IF v_plan_count=0 THEN
    IF v_active_plan_count>0 OR _rate_plan_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
        'message','Property has active published plans but none is eligible for this room and stay');
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'mode','legacy','rate_plan_id',NULL,'publication_id',NULL,
      'pricing',public.calculate_staynas_room_pricing_legacy(
        _property_id,_room_id,_check_in,_check_out,_adults,
        COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0)
      )
    );
  END IF;

  -- v_plan_count has already enforced exactly one eligible candidate for
  -- implicit selection, or exactly one matching candidate for an explicit ID.
  -- Select from that same latest-publication candidate set; never order by UUID.
  SELECT p.id,p.code,p.name,p.currency,p.pricing_basis,p.version,p.property_id
    INTO v_plan
  FROM public.staynas_rate_plans p
  JOIN public.staynas_rate_plan_room_types a
    ON a.property_id=p.property_id AND a.rate_plan_id=p.id AND a.active=true
  JOIN public.staynas_rate_plan_publications pub
    ON pub.property_id=p.property_id AND pub.rate_plan_id=p.id
  WHERE p.property_id=_property_id
    AND p.publication_status='published' AND p.active=true
    AND a.room_type_id=v_room.catalogue_type_id
    AND (p.effective_from IS NULL OR p.effective_from<=_check_in)
    AND (p.effective_to IS NULL OR p.effective_to>=_check_out-1)
    AND (pub.effective_from IS NULL OR pub.effective_from<=_check_in)
    AND (pub.effective_to IS NULL OR pub.effective_to>=_check_out-1)
    AND (_rate_plan_id IS NULL OR p.id=_rate_plan_id)
    AND pub.publication_number=(
      SELECT max(pub2.publication_number)
      FROM public.staynas_rate_plan_publications pub2
      WHERE pub2.property_id=pub.property_id
        AND pub2.rate_plan_id=pub.rate_plan_id
    )
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'error_code','NO_ELIGIBLE_RATE_PLAN',
      'message','Eligible rate plan and latest publication could not be resolved consistently');
  END IF;

  SELECT pub.* INTO v_publication
  FROM public.staynas_rate_plan_publications pub
  WHERE pub.property_id=_property_id AND pub.rate_plan_id=v_plan.id
  ORDER BY pub.publication_number DESC LIMIT 1;
  IF NOT FOUND OR v_publication.snapshot_hash IS NULL THEN
    RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
      'message','Eligible plan has no immutable publication snapshot');
  END IF;
  IF upper(v_plan.currency)<>v_property_currency
     OR upper(v_publication.currency)<>v_property_currency THEN
    RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
      'message','Published plan currency does not match property currency');
  END IF;

  v_data := v_publication.resolved_data;
  v_base := COALESCE(v_data->'base_rates','{}'::jsonb);
  v_daily := COALESCE(v_data->'daily_rates','{}'::jsonb);
  v_seasons := COALESCE(v_data->'seasonal_rates','{}'::jsonb);
  v_restrictions := COALESCE(v_data->'restrictions','{}'::jsonb);
  v_occupancy := COALESCE(v_data->'occupancy_rules','{}'::jsonb);

  IF jsonb_typeof(v_base)<>'object' OR jsonb_typeof(v_daily)<>'object'
     OR jsonb_typeof(v_seasons)<>'object' OR jsonb_typeof(v_restrictions)<>'object'
     OR jsonb_typeof(v_occupancy)<>'object' THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
      'message','Published pricing snapshot contains malformed commercial data');
  END IF;

  -- Validate applicable cumulative restrictions before calculating any amount.
  FOR v_rule IN SELECT key,value FROM jsonb_each(v_restrictions)
    WHERE value<>'null'::jsonb AND value->>'active'='true'
  LOOP
    IF NOT (v_rule.value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)) THEN
      CONTINUE;
    END IF;
    CASE v_rule.value->>'type'
      WHEN 'min_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_min_los:=GREATEST(v_min_los,(v_rule.value->>'value')::integer); END IF;
      WHEN 'max_los' THEN IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN v_max_los:=LEAST(COALESCE(v_max_los,365),(v_rule.value->>'value')::integer); END IF;
      WHEN 'closed_to_arrival' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to arrival');
        END IF;
      WHEN 'closed_to_departure' THEN
        IF _check_out BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Closed to departure');
        END IF;
      WHEN 'stop_sell' THEN
        IF EXISTS (SELECT 1 FROM generate_series(_check_in,_check_out-1,interval '1 day') d
          WHERE d::date BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date) THEN
          RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Stop sell applies to one or more stay nights');
        END IF;
      WHEN 'advance_booking_min_hours' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_hours:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/3600;
          IF v_hours < (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Minimum advance booking window not met');
          END IF;
        END IF;
      WHEN 'advance_booking_max_days' THEN
        IF _check_in BETWEEN (v_rule.value->>'start_date')::date AND (v_rule.value->>'end_date')::date THEN
          v_local_booking:=COALESCE(_booking_timestamp,now()) AT TIME ZONE v_timezone;
          v_days:=extract(epoch FROM (_check_in::timestamp-v_local_booking))/86400;
          IF v_days > (v_rule.value->>'value')::numeric THEN
            RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED','message','Maximum advance booking window exceeded');
          END IF;
        END IF;
      ELSE
        RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Unsupported restriction type');
    END CASE;
  END LOOP;
  IF v_nights<v_min_los OR (v_max_los IS NOT NULL AND v_nights>v_max_los) THEN
    RETURN jsonb_build_object('ok',false,'error_code','RESTRICTION_BLOCKED',
      'message',format('Stay length must be between %s and %s nights',v_min_los,COALESCE(v_max_los::text,'unlimited')));
  END IF;

  IF v_plan.pricing_basis='occupancy_based' THEN
    v_occupancy_key:=format('%s:%s:%s',_adults,COALESCE(_children_below_6,0),COALESCE(_children_7_plus,0));
  END IF;

  v_day:=_check_in;
  WHILE v_day<_check_out LOOP
    v_rate:=NULL; v_source:=NULL; v_source_id:=NULL; v_source_key:=NULL;

    -- Approved overrides: exact room/date, plan+room type, room type, then plan.
    SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
    WHERE o.property_id=_property_id AND o.status='approved'
      AND o.scope='room_date' AND o.room_id=_room_id
      AND o.effective_from=v_day AND o.effective_to=v_day
    ORDER BY o.approved_at DESC,o.id LIMIT 1;
    IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
      v_source:='approved_room_date_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
    ELSE
      SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
      WHERE o.property_id=_property_id AND o.status='approved'
        AND o.scope='rate_plan_room_type' AND o.rate_plan_id=v_plan.id
        AND o.room_type_id=v_room.catalogue_type_id
        AND v_day BETWEEN o.effective_from AND o.effective_to
      ORDER BY o.approved_at DESC,o.id LIMIT 1;
      IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
        v_source:='approved_plan_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
      ELSE
        SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
        WHERE o.property_id=_property_id AND o.status='approved'
          AND o.scope='room_type' AND o.room_type_id=v_room.catalogue_type_id
          AND v_day BETWEEN o.effective_from AND o.effective_to
        ORDER BY o.approved_at DESC,o.id LIMIT 1;
        IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
          v_source:='approved_room_type_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
        ELSE
          SELECT o.* INTO v_override FROM public.staynas_rate_overrides o
          WHERE o.property_id=_property_id AND o.status='approved'
            AND o.scope='rate_plan' AND o.rate_plan_id=v_plan.id
            AND v_day BETWEEN o.effective_from AND o.effective_to
          ORDER BY o.approved_at DESC,o.id LIMIT 1;
          IF FOUND THEN v_rate:=jsonb_build_object('nightly_rate',v_override.nightly_rate,'currency',v_override.currency);
            v_source:='approved_plan_override'; v_source_id:=v_override.id; v_source_key:=v_override.id::text;
          END IF;
        END IF;
      END IF;
    END IF;

    -- Published daily rate supersedes seasonal and inherited/base rate.
    IF v_rate IS NULL THEN
      v_rate:=v_daily->v_day::text->v_room.catalogue_type_id::text;
      IF v_rate IS NOT NULL AND v_rate<>'null'::jsonb AND COALESCE((v_rate->>'active')::boolean,false) THEN
        v_source:='published_daily_rate'; v_source_key:=v_day::text;
      ELSE
        v_rate:=NULL;
      END IF;
    END IF;

    IF v_rate IS NULL THEN
      SELECT count(*) INTO v_matches
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text);
      SELECT s.key,s.value INTO v_source_key,v_rate
      FROM jsonb_each(v_seasons) s(key,value)
      WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
        AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
        AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
      ORDER BY (value->>'priority')::integer DESC,s.key LIMIT 1;
      IF v_matches>1 AND EXISTS (
        SELECT 1 FROM jsonb_each(v_seasons) s(key,value)
        WHERE value<>'null'::jsonb AND COALESCE((value->>'active')::boolean,false)
          AND (value->>'start_date')::date<=v_day AND (value->>'end_date')::date>=v_day
          AND value->'room_type_ids' @> jsonb_build_array(v_room.catalogue_type_id::text)
          GROUP BY (value->>'priority')::integer HAVING count(*)>1
      ) THEN
        RETURN jsonb_build_object('ok',false,'error_code','AMBIGUOUS_RATE_SOURCE',
          'message','Equal-priority seasonal rates overlap for a charged night');
      END IF;
      IF v_rate IS NOT NULL THEN v_source:='published_seasonal_rate'; END IF;
    END IF;

    IF v_rate IS NULL AND v_plan.pricing_basis='occupancy_based' THEN
      v_rate:=v_occupancy->v_room.catalogue_type_id::text->v_occupancy_key;
      IF v_rate IS NULL OR v_rate='null'::jsonb THEN
        RETURN jsonb_build_object('ok',false,'error_code','OCCUPANCY_RATE_MISSING',
          'message',format('No exact occupancy rate is published for %s',v_day));
      END IF;
      v_source:='published_occupancy_rate'; v_source_key:=v_occupancy_key;
    END IF;
    IF v_rate IS NULL AND v_plan.pricing_basis IN ('per_room','per_person') THEN
      v_rate:=v_base->v_room.catalogue_type_id::text;
      v_source:='published_base_rate'; v_source_key:=v_room.catalogue_type_id::text;
    END IF;
    IF v_rate IS NULL OR v_rate='null'::jsonb
       OR jsonb_typeof(v_rate->'nightly_rate') IS DISTINCT FROM 'number'
       OR jsonb_typeof(v_rate->'currency') IS DISTINCT FROM 'string' THEN
      RETURN jsonb_build_object('ok',false,'error_code','RATE_SOURCE_MISSING',
        'message',format('No valid published rate source for %s',v_day));
    END IF;
    IF v_rate->>'currency' IS DISTINCT FROM v_property_currency THEN
      RETURN jsonb_build_object('ok',false,'error_code','CURRENCY_MISMATCH',
        'message',format('Rate currency mismatch on %s',v_day));
    END IF;
    v_rate_amount:=(v_rate->>'nightly_rate')::numeric;
    IF v_rate_amount<=0 THEN
      RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION',
        'message',format('Non-positive nightly rate on %s',v_day));
    END IF;
    IF v_source NOT IN ('published_occupancy_rate') THEN
      IF v_plan.pricing_basis='per_person' THEN
        v_nightly_rate:=round(v_rate_amount*v_paid_occupants,2);
      ELSE
        v_nightly_rate:=round(v_rate_amount,2);
      END IF;
    ELSE
      v_nightly_rate:=round(v_rate_amount,2);
    END IF;
    v_subtotal:=round(v_subtotal+v_nightly_rate,2);
    v_breakdown:=v_breakdown||jsonb_build_array(jsonb_build_object(
      'date',v_day,'nightly_rate',v_nightly_rate,'source_rate',v_rate_amount,'currency',v_property_currency,
      'source',v_source,'source_id',v_source_id,'source_key',v_source_key,
      'rate_plan_id',v_plan.id,'publication_id',v_publication.id,
      'publication_number',v_publication.publication_number,
      'rate_plan_version',v_publication.rate_plan_version,
      'snapshot_hash',v_publication.snapshot_hash,
      'pricing_basis',v_plan.pricing_basis,'occupancy_key',v_occupancy_key
    ));
    v_day:=v_day+1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',true,'property_id',_property_id,'room_id',_room_id,
    'rate_plan_id',v_plan.id,'rate_plan_code',v_plan.code,
    'rate_plan_name',v_plan.name,'publication_id',v_publication.id,
    'publication_number',v_publication.publication_number,
    'rate_plan_version',v_publication.rate_plan_version,
    'snapshot_hash',v_publication.snapshot_hash,
    'currency',v_property_currency,'timezone',v_timezone,
    'check_in',_check_in,'check_out',_check_out,'nights',v_nights,
    'minimum_stay',v_min_los,
    'adults',_adults,'children_below_6',COALESCE(_children_below_6,0),
    'children_7_plus',COALESCE(_children_7_plus,0),'occupants',v_occupants,
    'billable_occupants',v_paid_occupants,'nightly',v_breakdown,
    'accommodation_subtotal',v_subtotal
  );
EXCEPTION
  WHEN insufficient_privilege THEN
    RETURN jsonb_build_object('ok',false,'error_code','AUTHORIZATION_DENIED','message','Pricing access denied');
  WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing data is malformed');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok',false,'error_code','INVALID_RATE_CONFIGURATION','message','Published pricing resolution failed closed');
END;
$function$;

REVOKE ALL ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz)
  TO authenticated,service_role;

COMMENT ON FUNCTION public.resolve_staynas_published_room_pricing(uuid,uuid,date,date,integer,integer,integer,uuid,timestamptz) IS
  'SPE-04 database-authoritative published-plan accommodation resolver. Reads latest immutable publication snapshot; returns nightly source evidence and structured fail-closed outcomes. Does not mutate inventory or bookings.';

COMMIT;

-- SPE-05 — property-scoped tax, fee and promotion engine.
-- Additive only. Existing booking/finance records and legacy tax rows are preserved.
BEGIN;

ALTER TABLE public.staynas_property_tax_rules
  ADD COLUMN IF NOT EXISTS tax_mode text NOT NULL DEFAULT 'exclusive',
  ADD COLUMN IF NOT EXISTS taxable_components text[] NOT NULL DEFAULT ARRAY['accommodation','extras']::text[],
  ADD COLUMN IF NOT EXISTS jurisdiction_code text,
  ADD COLUMN IF NOT EXISTS display_label text,
  ADD COLUMN IF NOT EXISTS priority integer NOT NULL DEFAULT 100,
  ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS created_by uuid,
  ADD COLUMN IF NOT EXISTS updated_by uuid;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='staynas_tax_mode_check') THEN
    ALTER TABLE public.staynas_property_tax_rules
      ADD CONSTRAINT staynas_tax_mode_check CHECK (tax_mode IN ('inclusive','exclusive'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='staynas_tax_rate_check') THEN
    ALTER TABLE public.staynas_property_tax_rules
      ADD CONSTRAINT staynas_tax_rate_check CHECK (rate >= 0);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='staynas_tax_validity_check') THEN
    ALTER TABLE public.staynas_property_tax_rules
      ADD CONSTRAINT staynas_tax_validity_check CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from);
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.staynas_property_fee_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  property_id uuid NOT NULL REFERENCES public.staynas_properties(id) ON DELETE CASCADE,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  calculation_type text NOT NULL CHECK (calculation_type IN ('fixed','percentage','per_night','per_guest','per_booking','per_room')),
  amount numeric(14,4) NOT NULL CHECK (amount >= 0),
  currency text,
  applies_to text[] NOT NULL DEFAULT ARRAY['accommodation']::text[],
  taxable boolean NOT NULL DEFAULT false,
  tax_rule_ids uuid[] NOT NULL DEFAULT '{}'::uuid[],
  minimum_amount numeric(14,2),
  maximum_amount numeric(14,2),
  valid_from date,
  valid_to date,
  priority integer NOT NULL DEFAULT 100,
  active boolean NOT NULL DEFAULT true,
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  created_by uuid,
  updated_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT staynas_fee_code_unique UNIQUE(property_id, code),
  CONSTRAINT staynas_fee_validity_check CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from),
  CONSTRAINT staynas_fee_bounds_check CHECK(maximum_amount IS NULL OR minimum_amount IS NULL OR maximum_amount >= minimum_amount)
);

CREATE TABLE IF NOT EXISTS public.staynas_property_promotions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  property_id uuid NOT NULL REFERENCES public.staynas_properties(id) ON DELETE CASCADE,
  code text,
  name text NOT NULL,
  description text,
  discount_type text NOT NULL CHECK(discount_type IN ('percentage','fixed')),
  discount_value numeric(14,4) NOT NULL CHECK(discount_value > 0),
  currency text,
  eligible_room_ids uuid[] NOT NULL DEFAULT '{}'::uuid[],
  eligible_rate_plan_ids uuid[] NOT NULL DEFAULT '{}'::uuid[],
  minimum_nights integer NOT NULL DEFAULT 1 CHECK(minimum_nights > 0),
  minimum_booking_value numeric(14,2) NOT NULL DEFAULT 0 CHECK(minimum_booking_value >= 0),
  booking_window_from date,
  booking_window_to date,
  stay_from date,
  stay_to date,
  valid_from timestamptz,
  valid_to timestamptz,
  usage_limit integer CHECK(usage_limit IS NULL OR usage_limit > 0),
  per_guest_limit integer CHECK(per_guest_limit IS NULL OR per_guest_limit > 0),
  usage_count integer NOT NULL DEFAULT 0 CHECK(usage_count >= 0),
  auto_apply boolean NOT NULL DEFAULT false,
  stackable boolean NOT NULL DEFAULT false,
  priority integer NOT NULL DEFAULT 100,
  status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','active','suspended','revoked','expired')),
  version integer NOT NULL DEFAULT 1 CHECK(version > 0),
  created_by uuid,
  updated_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT staynas_promotion_code_unique UNIQUE(property_id, code),
  CONSTRAINT staynas_promotion_dates_check CHECK(
